quests[27823] = { id = 27823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch ein Zwerg hat Bedürfnisse", description = "Versteht mich nicht falsch, ich weiß eine gute Ausgrabung genauso zu schätzen, wie jeder andere Zwerg. Es ist nur so… Nun, wir graben und graben und bekommen kaum einen Schluck zu trinken. Manchmal denke ich, ich sollte meine Schaufel einfach an den Nagel hängen und zurück nach Eisenschmiede gehen.\n\nAber nicht heute. Ein bisschen Grabungsstimmung steckt noch in mir.\n\nDiese Dunkeleisenzwerge an Hammerzehs Grabungsstätte, direkt nördlich von hier, stellen ein starkes und feines Bier her, mitten in der Wüste. Meint Ihr, Ihr könntet mir ein wenig davon besorgen?", sourceObjective = "Besorgt 15 Krüge Schattenbräu.", progress = "<Sigrun leckt sich erwartungsvoll die Lippen.>", completion = "<Sigrun kippt sofort einen staubigen Krug Schattenbräu.>\n\nHui, das Zeug ist stark! Ich wusste, dass sie Bier haben, aber ich hätte nie gedacht, dass sie Schattenbräu haben! Das ist mein allerliebstes Schattenbier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27824] = { id = 27824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gute Zeug", description = "Ich habe einen kleinen Vorschlag für Euch, wenn Ihr interessiert seid.\n\nDiese Dunkeleisen waren hier, bevor Durdin und seine Leute angekommen sind. Das bedeutet, dass die Dunkeleisen die ersten waren, die hineingekommen sind, als sich diese Titanenruinen geöffnet haben, und sie haben sicher das ganze gute Zeug mitgehen lassen. Ich bin sicher, dass sie diese Schätze immer noch in der Festung Angor nördlich von hier eingeschlossen haben.\n\nIhr habt Eure Fähigkeit, Zwergen eins auf den Deckel zu geben, mehr als bewiesen. Geht in diese Festung und prügelt Euch zu den Titanenschätzen durch.\n\nIch würde ja mitkommen, aber ich bin betrunken.", sourceObjective = "Sucht im untersten Stockwerk der Festung Angor nach Schätzen.", progress = "So früh schon zurück?", completion = "Na das nenne ich doch einen Schatz! Ich habe mir schon langsam Sorgen gemacht, dass das hier gar keine Titanenruinen sind!\n\nDas werde ich Durdin zeigen. Nochmals danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27825] = { id = 27825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben der Dicksten", description = "Uns gehen die Vorräte zur Neige, Fremder. Solange die schwarzen Drachen unsere Jagdgründe mit Zerstörung überziehen, haben wir keine Chance, an Nahrung zu gelangen.\n\nDie Oger im Süden jedoch haben genau, was wir brauchen. In ihrer Grotte solltet Ihr ausreichend Nahrung und Handwerkswaren finden.\n\nSie könnten sich aber mit Euch darum schlagen wollen. Seid also vorsichtig.", sourceObjective = "Erlangt 6 Fleischstücke der Staubspeier und 10 Lagen Seide der Staubspeier.", progress = "Willkommen zurück.", completion = "Ich nehme an, die Oger waren für Euch keine zu große Hürde. Hier - ein paar Münzen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27826] = { id = 27826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Drachenschlund", description = "<Dr. Blam starrt das Ei in ehrfürchtiger Stille an, blinzelt ein paar Mal und schaut dann zu Euch hoch.>\n\nH... Habt Ihr das gesehen? Unfassbar! Meine Titanendingsidee hat funktioniert! Mit Eurer Hilfe, natürlich.\n\nNun, ich möchte das hier zu Rhea zurückbringen. Sie befindet sich nicht länger an der Lethlorklamm. Sie hat es mit Bravour geschafft, ihre Tarnung auffliegen zu lassen, als sie sich vor all diesen Welpen in ihre wirkliche Form verwandelte. Sie ist jetzt im Westen und hält sich in einem Allianzcamp mit Namen Drachenschlund auf.\n\nSie wird dort auf Euch warten. Und auf das Ei.", sourceObjective = "Bringt das geläuterte Schwarzdrachenei zu Rhea in Drachenschlund im Ödland zurück.", progress = "Ihr habt eine ziemlich wertvolle Ladung bei Euch, {name}.", completion = "Ich werde Euch das Ei jetzt abnehmen. Wir müssen das Ei ausbrüten... und schnell verstecken. Es gibt eine Menge wütender Drachen, die hiernach suchen.\n\nÜbrigens - schön, Euch wieder zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27827] = { id = 27827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flinke, der Starke und der Schreckliche", description = "In meiner Eile, aus der Lethlorklamm zu entkommen, habe ich ein paar Dinge vergessen: Nyxondra. Sie ist frei und hat beim schwarzen Drachenschwarm Alarm geschlagen. Der halbe Schwarm ist hier im westlichen Ödland auf der Suche nach diesem Ei.\n\nIch werde das Ei verstecken. Ihr kümmert Euch um diese lästigen Drachen. Ihr werdet Hilfe bekommen.\n\nRedet mit Eric, drüben auf der anderen Seite des Lagers. Er und seine Brüder werden Euch begleiten.", sourceObjective = "Sprecht mit Eric \"Dem Flinken\" beim Drachenschlund im Ödland.", completion = "Seid Ihr der {race}, auf den wir gewartet haben? Es wurde auch Zeit, dass Ihr kommt. Meine Beine könnten ein bisschen Bewegung vertragen.\n\nNa los, Jungs! Lasst uns ein paar schwarze Drachen jagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27828] = { id = 27828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric, der nützliche Zwerg", description = "Bevor wir allzu übermütig werden, was das Drachentöten angeht, möchte ich Euch ein bisschen über die Art, wie ich kämpfe, erzählen.\n\nMan nennt mich \"der Flinke\" und zwar aus folgendem Grund: Ich renne geradewegs auf Eure Feinde los - natürlich mit dem Helm vorneweg - und betäube sie für ein paar Sekunden. Außerdem werde ich einige Tränke bei mir tragen, falls es einmal eng werden sollte.\n\nWarum üben wir nicht, gemeinsam zu kämpfen? Geht hinaus aufs Feld und stellt meine Fähigkeiten auf die Probe.", sourceObjective = "Benutzt 'Erics Sturmangriff' und 'Erics Taschentrank'.", progress = "Wir sind noch nicht fertig, {name}.", completion = "Ich bin nicht das, was man gemeinhin \"sehr stark\" oder \"kampfgestählt\" nennt, aber ich bekomme das auch so hin.\n\nIch freue mich darauf, mit Euch gemeinsam zu kämpfen. Ich habe noch nie mit einem schicken {class} gekämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27829] = { id = 27829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn eines Drachenschwarms", description = "Hallo, {name}. Mir scheint, Ihr vier hattet genug Zeit, Euch anzufreunden.\n\nIch habe eine erste Aufgabe für Euch. Kalaran, ein uralter schwarzer Drache mit beträchtlicher Macht, hat sich der Jagd auf das von uns beschützte Ei angeschlossen. Wir müssen ihn aufhalten, bevor er ihm zu nahe kommt.\n\nIhr findet ihn und seine Diener im Staubbecken, nordöstlich vom Drachenschlund. Sucht und besiegt ihn. Wahrscheinlich werdet Ihr die Hilfe Eurer neuen Zwergenverbündeten brauchen.", sourceObjective = "Tötet Kalaran den Vernichter und 4 Soldaten des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27830] = { id = 27830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd geht weiter", description = "Der schwarze Drachenschwarm meint es ernst. Wie es scheint hat er einen Großteil von Neu-Kargath, der Siedlung der Horde nordwestlich des Drachenschlunds, an sich gerissen. Ihre Truppen stehen unter dem Befehl von General Jirakka und seinem Champion Moldarr. Sie müssen aufgehalten werden.\n\nWir Drachen mischen uns nicht in die kindischen Streitereien zwischen Horde und Allianz ein, aber mir ist bewusst, welches Risiko Ihr eingeht, wenn Ihr Neu-Kargath betretet. Bitte, Helden... Seid vorsichtig.", sourceObjective = "Besiegt General Jirakka, Moldarr und 6 Mitglieder der Drachenbrut des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27831] = { id = 27831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leid und der Zorn", description = "Am meisten bereue ich, wie wir... nein, wie ich Nyxondra behandelt habe. Ich habe sie gezwungen, Eier zu legen, und dann mit ihnen experimentiert. Immer und immer und immer wieder.\n\nObwohl ich selbst Mutter bin, kann ich mir ihr Leid kaum vorstellen.\n\nNein... Ich darf nicht schwach werden. Unsere Arbeit dient immerhin dem Wohl der zukünftigen Generationen der schwarzen Drachen. Ihr Opfer war notwendig.\n\nNun umkreist sie die Ruinen von Kargath, nordwestlich von Neu-Kargath, wahnsinnig vor Zorn. Bitte, Helden... erlöst sie von ihrem Elend.", sourceObjective = "Erschlagt Nyxondra und 12 von Nyxondras Brutlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27832] = { id = 27832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteckte Gelege", description = "Jetzt, da die meisten schwarzen Drachen aus dem Ödland abgezogen sind, können wir das Ei wieder sicher transportieren. Ihr findet mich auf einer kleinen Hochebene nördlich von Neu-Kargath.\n\nSucht mich dort auf.", sourceObjective = "Sprecht mit Rhea im Versteckten Gelege im Ödland.", completion = "Das Ei muss immer in Bewegung bleiben. Wir sind hier nicht mehr sicher.\n\nSogar in seinem Wahnsinn kennt Todesschwinge alle versteckten Orte dieser Welt. Das Ei kann nicht an einem Ort bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27833] = { id = 27833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonnenschwere Starrköpfe", description = "Ich würde sagen, wir haben ein Drachenproblem. Aber es sieht aus, als wären sie eher an Neu-Kargath interessiert als an unserem kleinen Lager. Trotzdem habe ich unsere besten Männer darauf angesetzt, die Drachen zurückzuhalten.\n\nEin Problem, das jedoch ungelöst bleibt, ist das Ogerlager im Südwesten. Eine kleine Armee von Kämpfern scheint vor ihrem Unterschlupf aufgetaucht zu sein.\n\nWir können nicht einfach herumsitzen und darauf warten, dass sie uns über die Flanke angreifen. Dünnt ihre Reihen aus, bevor sie unsere ausdünnen.", sourceObjective = "Tötet 12 Kämpfer der Staubspeier. Ihr könnt Raufer oder Schamanen der Staubspeier töten.", completion = "Ich danke Euch, {race}. Allerdings befürchte ich, dass ich Euch außer einer aufrichtigen Runde Applaus nicht viel geben kann.\n\n\n\nOh, das hier habe ich doch. Hier, nehmt Euch, was Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27834] = { id = 27834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baelog, die Glaskanone", description = "Bevor ich anfange, Pfeile auf diese Drachen regnen zu lassen, stelle ich mich erstmal vor.\n\nIch bin Baelog, der Mann fürs Grobe in dieser Gruppe. Mein Schwert beißt wie ein Krokilisk und meine Pfeile singen wie Banshees. Dafür erschöpfe ich aber schnell und kann auch nicht so viel einstecken wie meine Brüder.\n\nEin Wort von Euch genügt, und ich kann einen gezielten Pfeil mitten ins Herz des Ziels schicken. Ich kann auch meine Brüder anfeuern und sie sich in einen Kampfrausch steigern lassen.\n\nWarum ziehen wir nicht zusammen in die Schlacht?", sourceObjective = "Benutzt 'Baelogs Valhallaschuss' und 'Baelogs Kriegsschrei'.", progress = "Wir sind noch nicht ganz bereit. Noch etwas mehr Übung und wir fangen mit dem Drachentöten an.", completion = "Ich glaube, Ihr seid soweit, {name}. Ihr habt den Dreh raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27835] = { id = 27835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olaf, der dicke Brocken", description = "Es ist Euch vielleicht nicht aufgefallen, aber für einen Zwerg bin ich recht groß.\n\nIch stelle sicher, dass meine beiden Brüder hier nicht in zu große Schwierigkeiten geraten. Sie sind klein und haben nicht so einen großen Schild wie ich. Ich bin groß und kann ein paar Schläge von Monstern gut wegstecken! Außerdem kann ich es meistens schaffen, dass sie nur meinen Schild treffen!\n\nIch kann auch Euch beschützen. Kommt, gehen wir ein bisschen trainieren. Ich sorge dafür, dass die Gegner mich angreifen, nicht Euch.", sourceObjective = "Benutzt 'Olafs Schildwall' und 'Olafs mächtigen Ruf'.", completion = "Seht Ihr? Kein Grund zur Sorge, wenn Olaf da ist. Sagt mir nur Bescheid und ich beschütze Euch vor den Monstern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27836] = { id = 27836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung eindämmen", description = "Es wird nicht reichen, die widerlichen Kreaturen, die den Fluss verseuchen, zu töten, {name}.\n\nEine neue Generation dieser Monstrositäten droht bereits in unseren heiligen Wassern ausgebrütet zu werden.\n\nSucht ihre unreinen Eier und zerstört sie.", sourceObjective = "Zerstört 6 Gleitereier.", completion = "Ich danke Euch, {name}. Dies wird unsere prophetischen Visionen so viel klarer werden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27837] = { id = 27837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebetene Besucher im Wasser", description = "Kurz, nachdem Uldums Schutzbarriere fiel, wurde der Vir'naal von einer furchtbaren Verderbnis befallen.\n\nOb diese mit böser Absicht oder versehentlich hierher gebracht wurde, spielt keine große Rolle.\n\nDas Ergebnis ist das gleiche. Je trüber der Fluss wird, umso mehr trübt sich auch unsere Fähigkeit, vorauszusehen, was die Zukunft uns bringt.\n\nSchaut hinaus, {class}. Diesen widerwärtigen Kreaturen war es nie bestimmt, in den makellosen Wassern unseres Flusses zu leben. \n\nTötet sie, damit der Fluss uns wieder Visionen ermöglicht.", sourceObjective = "Tötet 8 Stillwassergleiter.", completion = "Ja, {name}. Ich spüre bereits, wie die Beeinträchtigung des Flusses schwindet.\n\nDennoch spüre ich, dass die Quelle dieser Verderbnis weiterhin lauert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27838] = { id = 27838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Übels", description = "Ihr mögt Euch den Symptomen unseres Problems angenommen haben, {name}. Aber ich habe diese widerwärtigen Biester beobachtet und sie legen ihre Eier nicht hier.\n\nDie Strömung trägt ihre Eier zum Damm, aber was immer sie legt, befindet sich am Oberlauf des Flusses.\n\nGeht nach Nordosten zur Hauptquelle des Flusses und beseitigt die Wurzel des Übels.", sourceObjective = "Geht zur nordöstlichen Quelle des Vir'naal und tötet Schuppenmutter Hevna.", completion = "Ja. Die Wasser werden klarer.\n\nIch bin sicher, dass wir eine Vision haben werden, bevor der Hohe Rat zusammentrifft.\n\nSeid gewarnt, {race}. Meine Stimme wird sich nach dem richten, was ich sehe.\n\nIhr habt uns sicherlich heute hier sehr geholfen, aber wenn die Vision mir rät, mich gegen den Krieg auszusprechen, dann werde ich meine Stimme auch so abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27839] = { id = 27839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Waffen", description = "Obwohl wir uns noch nicht offiziell im Krieg befinden, zögern die Neferset nicht, alle, die unbefugt ihr Gebiet betreten, ins Gefängnis zu werfen oder zu töten.\n\nKönig Phaoris weigert sich, darauf zu antworten, auch wenn sie unser Land dazu benutzen, gestohlene Relikte aus den Grabstätten unserer Ahnen herauszuschmuggeln.\n\nMeine Späher berichten mir, dass die Neferset in Kürze südlich von hier eine größere Ladung geplünderter Waffen in Bewegung setzen wollen.\n\nIch habe die Arbeiter, die Ihr angeworben habt, angewiesen, Euch zu helfen. Ruft sie mit diesem Horn, wenn Ihr die Schmuggler findet und holt die Waffen.", sourceObjective = "Besorgt die uralten Waffen der Tol'vir", progress = "Ihr seid zurückgekehrt, {name}. Wie ist die Operation verlaufen?", completion = "Das kommt gerade recht. Ich werde diese Waffen an meine besten Leute und die Arbeiter, die Ihr angeworben habt, verteilen.\n\nIch habe das Gefühl, sie werden ebenso viel Mut beweisen, wie meine bestens ausgebildeten Hauptleute.", sourceObjectiveStatus = "unverified-source-field" }
quests[27840] = { id = 27840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethystkristalle", description = "Die Verlorenen, die in der Zuflucht der Verirrten leben, sehen aus wie wir, aber sie sind Monster, die durch die Strapazen unserer Reise nach Azeroth den Verstand verloren haben. Einst waren sie unsere Brüder, aber jetzt leben sie in der Zuflucht der Verirrten im Westen. Dort fangen oder töten sie jeden, der ihnen nahe kommt.\n\nAußerdem haben sie uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nWir haben nicht genug Leute, um die Zuflucht der Verirrten zu betreten und uns das gestohlene Draenethyst aus ihren Hütten und von ihren Lagerfeuern zurückzuholen. Doch ohne diese Kristalle... könnte es sein, dass auch wir uns verirren.", sourceObjective = "Sammelt 5 Draenethystkristalle in der Zuflucht der Verirrten auf.", progress = "Habt Ihr die Kristalle?", completion = "Danke, {name}. Wir stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[27841] = { id = 27841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Goblingeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27842] = { id = 27842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst der Anfang", description = "Ich ich sehne mich nach den Zeiten, als Legionen mächtiger Oger von der Horde in die Schlacht geführt wurden und die lächerliche Allianz sich vor Angst in die Hosen gemacht hat. Vielleicht kehren diese Tage ja wieder, bevor die Ahnen mich zu sich rufen.\n\nDerzeit jedoch ist dies noch nicht der Fall. Ein Ogermagier, Glubtok, hat sich mit der verabscheuungswürdigen Bruderschaft der Defias eingelassen und spielt für sie den Vorarbeiter für ihre Bergbauoperationen. Dieser erbärmliche Narr! Beendet sein Leben für mich und zum Ruhme der Horde!", sourceObjective = "Tötet Glubtok.", sourceObjectiveStatus = "unverified-source-field" }
quests[27843] = { id = 27843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkungen abgelehnt", description = "Einfach nur Oger zu töten wird nicht ausreichen. Die Oger selbst werden viel zu schnell aufs Schlachtfeld gerufen.\n\nIch möchte, dass Ihr weit hinter die feindlichen Linien geht und ihre Beschwörer ausschaltet. Diese Orcs verwenden Hexenmeister, um ihre Verstärkungen zu rufen.\n\nHackt diese Hexenmeister in Stücke, und die Portale sollten in greifbarer Nähe sein. Es gibt nicht zu viele von ihnen... Ein schneller, präziser Schlag sollte den Feind schwächen.", sourceObjective = "Tötet 3 Hexenmeister von Steinard.", completion = "Erneut gute Arbeit. Noch ein paar solcher Vorstöße und die Schlacht wird uns gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27844] = { id = 27844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter!!!", description = "Die Goblins, die mit den Defias zusammenarbeiten, sind offiziell Verräter am Bilgewasserkartell, der Zerschmetterten Hand und der Horde selbst!\n\nIch wurde noch nicht bei der Zerschmetterten Hand initiiert, also gilt meine Treue vor allem meinem Volk. Helix Ritzelbrecher hat offensichtlich keine Zeit für solche Bündnisse und baut gerade einen Mast für die Moloch der Defias. Würdet Ihr Helix im Namen von Fräulein Fiasko und mir \"beseitigen\"?", sourceObjective = "Besiegt Helix Ritzelbrecher.", completion = "Meine Auftraggeber haben für Verräter nichts übrig.\n\nIm Gegensatz dazu sind sie für ihre ausgesprochene Freundlichkeit unseren treu Ergebenen gegenüber bekannt. Ihr verdient es, belohnt zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[27845] = { id = 27845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markiert die Gefallenen", description = "Wir haben mehr Leben genommen, als wir verloren haben, aber wir haben immer noch zu viele verloren. Zu viele Tapfere haben da draußen ihr Leben für die Allianz gegeben. Ich will, dass sie die verdienten Ehren erhalten, egal, wie wild diese Schlacht auch wird.\n\nNehmt diese Flaggen mit Euch und platziert je eine auf jedem gefallenen Soldaten, den Ihr seht. Die Schutzzauber, die ihnen anhaften, werden nicht vor mutwilliger Entweihung schützen, aber sie sind besser als nichts. Ich werde so auch besser aus der Entfernung einschätzen können, wie viele wir verloren haben.", sourceObjective = "Benutzt die Banner der Gefallenen, um 7 gefallene Fußsoldaten der Sumpftidenwacht zu markieren.", completion = "Danke, {name}. Diese Soldaten verdienen Besseres, als mit dem Gesicht im Dreck liegengelassen zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27847] = { id = 27847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch nicht ganz fertig", description = "Diese Prototypen werden die Kriegsführung der Horde revolutionieren, wenn ich sie erstmal perfektioniert habe! Das Problem ist nur, dass ihre Energievorräte nicht für große Chassis ausreichen, oder um komplizierte Kampfmanöver durchzuführen, obwohl beides sehr wünschenswert wäre.\n\nDie Defias haben - mithilfe einiger Goblinverräter wie Helix - beinahe den Feindschnitter 5000 fertiggestellt, einen riesigen Golem, der sogar funktionieren wird!\n\nDas darf auf keinen Fall publik werden, oder ich verliere Kunden!", sourceObjective = "Zerstört den Feindschnitter 5000.", completion = "Großartig! Nun muss ich nur noch mein Werk vollenden und meine Chaosernter werden... Chaos... auf jedem Schlachtfeld der Horde säen!\n\nUnd es wird keine Emporkömmlinge der Defias geben, die meine Profite stehlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27848] = { id = 27848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Absichten... Schlechte Durchführung", description = "Die Defias planen, die Moloch fertigzustellen und damit Sturmwind in Schutt und Asche zu legen. Es ist eine ehrenvolle Aufgabe und eine, die jeder wahre Orckrieger ohne zu zögern annehmen würde!\n\nVanessas Fehler ist die Ausführung ihres Plans. Das Schiff ist mangelhaft konstruiert, die Crew ohne Erfahrung und, was am schlimmsten ist, da ist dieser Worgen unter ihnen!\n\nSein Name ist Admiral Knurrreißer und er muss ohne jede Gnade im Namen des Kriegshäuptlings erschlagen werden. Lok'tar ogar!", sourceObjective = "Tötet Admiral Knurrreißer.", sourceObjectiveStatus = "unverified-source-field" }
quests[27849] = { id = 27849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Steinard", description = "Das ist es, {name}. Wir haben es endlich nach Steinard geschafft.\n\nIch sollte zwar niemanden daran erinnern müssen, tue es aber trotzdem: Wir sind keine Orcs, und wir werden auch wegen Rachegelüsten und Boshaftigkeit nicht zu welchen werden. Steinard wird nicht dem Erdboden gleichgemacht werden, damit wir auf seiner Asche tanzen.\n\nNein, ich will, dass das hier auf anständige Art gemacht wird. Ein chirugischer Eingriff. Haltet Euren Kopf aufrecht und erschlagt jeden Orc, der eine Waffe auf Euch richtet.", sourceObjective = "Erschlagt 6 Verteidiger von Steinard.", completion = "Ihr habt Euren Befehlen ausgezeichnet Folge geleistet, {name}. Im Namen der Krone belobige ich Euch für Euren Mut auf dem Schlachtfeld.", sourceObjectiveStatus = "unverified-source-field" }
quests[27850] = { id = 27850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nummer Eins der Defias", description = "Die Zerschmetterte Hand hat sich jahrelang im Hintergrund gehalten.\n\nDas hat nun ein Ende! Ihr werdet das Instrument unserer Wiedergeburt sein, {name}. Erschlagt die Nummer Eins der Defias und erbeutet ihr Schiff zum Ruhme der Horde! Wir werden sie wie ein richtiges Orckriegsschiff ausstatten und Sturmwind endlich in Schutt und Asche legen!\n\nJeder Überlebende wird die Kunde unserer unaufhaltsamen Macht in ganz Azeroth verbreiten und alle werden vor uns erzittern!\n\nGeht jetzt. Van Cleefs Tod wird Eure bisher größte Tat darstellen, Held!", sourceObjective = "Tötet die Nummer Eins der Defias.", completion = "FEIGLING!!! Vanessa van Cleef ist ein dreckiger Feigling von einem Menschen! Wie kann sie es wagen, einem Kampf mit der Horde zu entfliehen und ihre unwürdigen Lakaien zurückzulassen?\n\n<Kagtha beruhigt sich wieder.>\n\nUnwichtig. Ihr Schiff ist Belohnung genug. Die Einwohner Sturmwinds werden aus erster Hand erfahren, wie sich unsere Ehrfurcht gebietende Macht anfühlt, wenn wir sie mit einem Schiff angreifen, das zum Teil vom selben Architekten gebaut worden ist, der auch ihre Stadt erbaut hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[27851] = { id = 27851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschubunterbrechung", description = "Wir werden Steinard zwar nicht dem Erdboden gleich machen, aber ich will kein zweites Mal dort hineingehen müssen.\n\nSammelt alle Vorräte, die Ihr seht, wenn Ihr in der Stadt seid. Ohne Nahrung werden ihnen nach einem Tag keine Kämpfer mehr bleiben.\n\nEs sollten in der ganzen Stadt Kisten herumstehen.", sourceObjective = "Erbeutet 5 Kisten mit Vorräten von Steinard.", progress = "Wie ist die Lage?", completion = "Gute Arbeit, {name}. Dank dieser Kisten ist es nur eine Frage der Zeit, bis die Orcs zum Portal fliehen oder darum betteln, sich ergeben zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27852] = { id = 27852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs und Menschen", description = "Der Krieg tobt im Sumpf, {name}. Niederträchtige Menschen haben sich nördlich der Stadt niedergelassen und eine Armee an unsere Türschwelle gebracht.\n\nIn diesem Sumpf gibt es für sie nichts zu holen. Der einzige Grund, weswegen sie hier sind, ist, uns unprovoziert anzugreifen!\n\nWir sind unterbemannt und brauchen jeden fähigen Orc, um zu kämpfen. Geht und erschlagt so viele Menschen, wie Ihr nur könnt!", sourceObjective = "Tötet 10 Fußsoldaten der Sumpftidenwacht.", completion = "Wir werden bis auf den letzten {race} kämpfen, {name}. Ich hoffe, Ihr könnt Euch lange genug am Leben erhalten, um diese Eindringlinge gründlich zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27853] = { id = 27853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trampel", description = "Die Allianz ist uns zahlenmäßig überlegen. In ihrer Angst entsenden sie eine Armee, um eine einzelne Siedlung zu zerstören. Aber wir werden nicht aufgeben!\n\nWenn sie keine Resourcen haben, werden ihre Soldaten im Nachteil sein. Menschliche Bauern sind damit beschäftigt, in den Wäldern außerhalb der Sumpftidenwacht Holz zu sammeln, um ihre einstürzenden Wälle wieder aufzubauen.\n\nVersagt ihnen das Holz - und ihr Leben.", sourceObjective = "Tötet 5 Bauern der Sumpftidenwacht.", completion = "Kein wahres Mitglied der Horde sollte Gefallen daran finden, solch verängstigte Schwächlinge zu töten... dem Sieg fehlt zum Nervenkitzel dann die Herausforderung.\n\nDoch Eure schmutzige Arbeit hat dazu beigetragen, dass wir die Allianz abwehren und unser Zuhause hier schützen konnten. Seid stolz auf Eure Arbeit für die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27854] = { id = 27854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flut der Dunkelheit", description = "Wir mussten schwere Verluste einstecken, {name}. Die Feste Schreckensfels hat Oger aus den Verwüsten Landen als Verstärkung geschickt, aber ihre Zahl ist begrenzt. Die Allianz setzt ihnen genau in diesem Moment zu.\n\nDie Allianz versucht, mit Rittern gegen unsere Oger vorzugehen. Diese Strategie hat ihnen schon im Zweiten Krieg gute Dienste geleistet. Wir müssen unsere stärksten Krieger einsetzen, wenn wir die Schlacht für uns entscheiden wollen!\n\nKehrt zum Blutsumpf zurück, {name}, und bringt diese Ritter zu Fall!", sourceObjective = "Tötet 6 Ritter der Sumpftidenwacht.", completion = "Ihr seid ein wahrer Champion, {name}, dass Ihr auf dem Schlachtfeld so vielen das Leben genommen habt. Ich hoffe, dass es ausreicht, um Steinard zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27855] = { id = 27855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkungen abgelehnt", description = "Die Allianz hat ihre Magier mitgebracht, um weitere Verstärkungen von hinter ihrer Festung direkt auf das Schlachtfeld zu bringen. Das muss unterbunden werden!\n\nEs sind ihrer nur wenige, aber ein einziges Portal kann schon den Ausgang der Schlacht verändern. Greift ihre Magier an und zerstört diese Portale!", sourceObjective = "Tötet 3 Magier der Sumpftidenwacht.", completion = "Ohne eine Verbindung zur Außenwelt muss sich die Allianz auf das verlassen, was sie in die Sümpfe mitgebracht hat. Wollen wir doch mal sehen, wie sie mit unserer vertrauten Umwelt fertig werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27856] = { id = 27856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markiert die Gefallenen", description = "Viele Krieger haben den Tod gefunden, um uns den Sieg zu bringen, {name}. Das ist das Schicksal eines wahren Orcs.\n\nIch habe gesehen, wie die Allianz die Leichen unserer Gefallenen plündert und sich wie Hamster an unseren Sachen festklammert. Sie werden nicht unsere gefallenen Helden auf diesem Schlachtfeld entehren.\n\nNehmt diese Banner mit Euch in den Blutsumpf. Platziert sie auf die Leichen unserer gefallenen Krieger. Ich werde Euch beobachten, damit ich sehe, wie viele gefallen sind und um ihr Opfer zu ehren. Hoffen wir, dass die Geister uns helfen, unseren Respekt zu erweisen.", sourceObjective = "Benutzt das Banner der Gefallenen, um 7 gefallene Krieger von Steinard zu markieren.", completion = "Mit Eurem Mut ehrt Ihr sowohl die Toten als auch die Lebenden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27857] = { id = 27857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir werden angegriffen!", description = "Die Allianz hat unsere Mauern erreicht!\n\n{name}, Euer Handeln hat ihren Vorstoß verlangsamt, doch sind sie uns zahlenmäßig immer noch weit überlegen. Dies wird unser letztes Gefecht sein. Sieg oder Tod...\n\nIch wünsche Euch einen ehrenhaften Kampf, {name}. In diesem Augenblick toben die Kämpfe bereits innerhalb unserer Mauern. Treibt diese Bestien aus Steinard. Für die Horde!", sourceObjective = "Tötet 12 Eindringlinge der Sumpftidenwacht.", completion = "Die Allianz wurde vertrieben. Steinard ist dank Eures Mutes wieder sicher! Lok'tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27858] = { id = 27858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastraszas Geschenk", description = "Wartet hier. Ich werde das Ei holen.", sourceObjective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27859] = { id = 27859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ei lebt weiter", sourceObjective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", completion = "Ihr wart nicht der einzige Sterbliche, dem sich Rheastrasza anvertraut hat. Auch ich habe das Vertrauen des Drachen gewonnen.\n\nIch habe bereits das echte, gereinigte Ei an einen sichereren Ort weitab vom Ödland geschafft. Es wird weiter wachsen, ohne dass Todesschwinge seinen Aufenthaltsort kennt.\n\nDie Macht des roten Drachenschwarms wird nur von seiner Güte übertroffen. Rheastraszas letzter Wunsch war es, dass ich Euch dies gebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27860] = { id = 27860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verirrten", description = "Als das Dunkle Portal sich vor vielen Jahren schloss, überkam viele von uns, die in dieses Land gekommen sind, Reue und Angst. In ihrer Verzweiflung verfluchten sie den Namen des Lichts und verfielen in Gewalttätigkeit und Hass.\n\nDiese gefallenen Seelen sind jetzt als die Verirrten bekannt. Sie sind kaum mehr als geistlose Monster, die alles anfallen, was sich ihnen nähert. Ihre Verderbtheit wächst mit jedem Tag. Und in ihrem Kampf ums Überleben haben sie jetzt begonnen, Leute aus dem Sicheren Hafen zu entführen.\n\nIhnen kann nicht mehr geholfen werden, {name}. Ihr Leiden muss ein Ende finden. Werdet Ihr sie aus ihrer Not befreien?", sourceObjective = "Tötet 12 Verirrte in der Zuflucht der Verirrten.", completion = "Meine Bitte an Euch bereitet meinem Herzen immer noch Qual, obwohl ich weiß, dass es keinen anderen Weg gibt. Ihr habt uns, die wir immer noch an unserem Verstand festhalten, vor einer schlimmen Bedrohung gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27861] = { id = 27861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", description = "Ich hab mich schon gewundert, wann Ihr endlich hier aufkreuzt, {name}! Mit einem ehemaligen Champion aus dem Ring des Blutes wird es hier richtig was zu sehen geben! Wir werden reich sein, <Kumpel/Süße>! REICH!\n\nWie dem auch sei, hier ist eine alte Kampfgrube des Drachenmals. Wir mussten für unsere Bedürfnisse nicht viel daran ändern. Ich habe meine Fühler ein bisschen ausgestreckt, um die besten Schläger Azeroths für das Gemetzel zu finden. Es ist an der Zeit, Gold zu verdienen!\n\nIhr wisst ja, wie es abläuft, {name}. Wenn Ihr soweit seid, sagt Bescheid, und wir fangen mit der Vorstellung an!", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", sourceObjectiveStatus = "unverified-source-field" }
quests[27862] = { id = 27862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", sourceObjectiveStatus = "unverified-source-field" }
quests[27863] = { id = 27863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", description = "Eins sag ich Euch, man kann hier natürlich nicht mit den Wogenden Ebenen von Nagrand oder der Arena in Zul'Drak vergleichen, aber hey, ich bin da, wo das Gold ist! Willkommen im Schattenhochland!\n\nIhr seid neu hier, also lasst mich Euch ein paar Sachen erklären. Ich bin der Kampfveranstalter und der angriffslustige Troll hier ist Wodin, mein Leibwächter. Ihr seid meine Unterhaltung. Wenn Ihr kämpfen wollt, sagt Bescheid, und ich finde den passenden Gegner für Euch.\n\nWenn Ihr mit Freunden hier seid, können wir auch gleich anfangen! Was meint Ihr?", sourceObjective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", completion = "Nicht schlecht, nicht schlecht. Ihr könntet hier einen Batzen Gold verdienen - wenn Ihr nicht vorher sterbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27864] = { id = 27864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Todbringer des Drachenmals!", description = "Das wird Euch gefallen! Der Drachenmalklan hat gehört, dass Ihr die Arena betreten wollt und man ist wild entschlossen zu verhindern, dass Ihr sie wieder verlasst.\n\nJetzt ist es Zeit für ein bisschen {race}-gegen-Orc-Action! Sagt mir Bescheid, wenn Ihr dazu bereit seid!", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Torg Drachenschinder!", completion = "Wie ich sehe, tragt Ihr keine Liebe für Orcs in Euch. Den Burschen habt Ihr wirklich zu Kleinholz verarbeitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27865] = { id = 27865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Der unberechenbare Wildhammer!", description = "Das wird Euch gefallen! Der Wildhammerklan habt gehört, dass Ihr die Arena betreten wollt und man ist wild entschlossen zu verhindern, dass Ihr sie wieder verlasst.\n\nJetzt ist es Zeit für ein bisschen {race}-gegen-Zwerg-Action! Sagt mir Bescheid, wenn Ihr dazu bereit seid!", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Sully Kniescheibler!", completion = "Wie ich sehe, tragt Ihr keine Liebe für Zwerge in Euch. Den Burschen habt Ihr wirklich zu Kleinholz verarbeitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27866] = { id = 27866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Calders Geschöpf!", description = "Grauenvoll und blutig - die nächste Paarung wird die Menge auf jeden Fall zum Stöhnen bringen. Calder Grau hat die Körperteile seiner besiegten Herausforderer aufgesammelt und daraus den perfekten Champion gebaut.\n\nDieses Ding ist die ultimative Zusammensetzung zusammengeschusterter zombifizierter Zweikämpfer. Eine mörderische Mixtur matschiger Monstrositäten. Seid Ihr bereit für das Chaos?! Ich bin es! Sagt mir Bescheid, wenn Ihr bereit seid, damit wir anfangen können!", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt die Kadavercollage!", completion = "Wow! Als ich das... Ding in die Arena stolpern sah, war ich sicher, dass Ihr keine Chance habt. Aber Ihr habt mir das Gegenteil bewiesen. Ihr habt es zerfetzt!\n\nGrauenhafte Angelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27867] = { id = 27867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Der Graf des Ausweidens!", description = "Mit dem hier werdet Ihr alle Hände voll zu tun haben, Kumpel. Wir haben hier einen erfahrenen Ehrenmann und Krieger! Er stammt aus Gilneas und will beweisen, dass er der beste Krieger diesseits von Azeroth ist.\n\nAlso schnürt Euch Eure Stiefel und gürtet die Hose, denn hier drin wird's jetzt richtig zur Sache geh'n. Sagt Bescheid, wenn Ihr was auf die Ohren bekommen wollt.", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Lord Geoffery Tulvan!", completion = "Das habt Ihr wirklich gut hinbekommen. Ich dachte, Ihr hättet es hinter Euch, als er sich in einen Wolf verwandelte und anfing, die Arena in Stücke zu reißen. Aber allmählich sollte ich wohl wissen, dass Ihr nicht so einfach kleinzukriegen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[27868] = { id = 27868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmelztiegel des Gemetzels: Der Schattenterror!", description = "Wir haben jemanden hier, den Ihr mit Sicherheit nur allzu gern hassen werdet. Zunächst war ich nicht sicher, ob wir ihn in die Grube lassen sollten, aber ein Kampf ist ein Kampf! Und wer bin ich schon, dass ich sicheres Geld ablehne?!\n\nDieser Kerl kommt aus der Schattenzitadelle und ist bewaffnet mit einem heißen Schlag. Ihr solltet Euch lieber schnell bewegen und immer auf der Hut sein! Sagt Bescheid, wenn Ihr für ein wenig Action bereit seid.", sourceObjective = "Betretet die Arena am Schmelztiegel des Gemetzels und besiegt Glutnarbe den Verschlinger!", completion = "Sieht so aus, als ob der Titel Euch gehört! Das habt Ihr aus dem Feuer gezogen. \n\nMeine Glückwünsche. Ich hoffe, das Geld wird Euch gute Dienste erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27869] = { id = 27869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Drache und der Tempel", description = "Diese Schlangen müssen aus dem Tempel von Atal'Hakkar kommen. Ich hatte bereits einen Hinweis...\n\nVor ein paar Tagen hatte ich einen Besucher, der meinte, ich solle die Augen nach dergleichen aufhalten. Ein Elf mit Namen Itharius. Ich glaube nicht, dass er wusste, dass ich sein Äußeres durchschauen konnte... Er war ein grüner Drache in Verkleidung. Wollte bestimmt seinen gefallenen Brüdern helfen.\n\nEr ist sicher hinter irgendwas her. Itharius ist zum Tempel selbst aufgebrochen. Vielleicht sucht Ihr dort besser nach ihm. Irgendetwas Übles geht hier vor.", sourceObjective = "Redet mit Lord Itharius oben auf den äußeren Stufen des Tempels von Atal'Hakkar.", completion = "Das Goblinmädchen schickt Euch? Sie hat ein gutes Auge, die Kleine.\n\nSie spricht die Wahrheit. Ich bin hier, um die Flut der Verderbnis, die von diesem Tempel ausströmt, aufzuhalten. Wenn Ihr Euer Volk vor einem üblen Schicksal bewahren wollt, {name}, dann bitte ich um Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27870] = { id = 27870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Sumpftidenwacht", description = "Egal, ob Ihr mir im Tempel helft oder nicht, Euer Volk muss erfahren, was hier vor sich geht.\n\nNördlich des Tempels haben ein paar Menschen Eurer Allianz der Sterblichen einen Posten errichtet, den sie die Sumpftidenwacht nennen. Sie führen überall im Sumpf Krieg gegen die Horde, und ich fürchte, dass dieser Konflikt sich noch weiter ausbreitet.\n\nEs ist nicht meine Aufgabe, mich in die Angelegenheiten der Sterblichen einzumischen, {name}. Ich bitte Euch einfach nur, Euer Volk davor zu warnen, was im Tempel lauert.", sourceObjective = "Sprecht mit Joanna Blauherz bei der Sumpftidenwacht.", completion = "Ärger im Tempel... Ich wünschte, wir hätten genügend Streitkräfte, um uns darum zu kümmern. Der Krieg mit Steinard ist bereits im vollen Gange. Wir brauchen jeden Mann, den wir kriegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27871] = { id = 27871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Steinard", description = "Egal, ob Ihr mir im Tempel helft oder nicht, Euer Volk muss erfahren, was hier vor sich geht.\n\nSüdwestlich des Tempels liegt die Hordenstadt Steinard. Die Orcs dort führen mit den neu in den Sümpfen angekommenen Menschen Krieg, und ich fürchte, dass dieser Konflikt sich noch weiter ausbreitet.\n\nEs ist nicht meine Aufgabe, mich in die Angelegenheiten der Sterblichen einzumischen, {name}. Ich bitte Euch einfach nur, Euer Volk davor zu warnen, was im Tempel lauert.", sourceObjective = "Sprecht mit Zentralenkommandant Ruag in Steinard in den Sümpfen des Elends.", completion = "Wir haben keine Zeit, um Orcs in den Tempel zu schicken, {name}. Die Menschen kommen in großen Scharen. Wir müssen Steinard verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27874] = { id = 27874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avianas Vermächtnis", description = "Eure Erfahrung wird woanders gebraucht, {name}.\n\nDirekt südwestlich des Weltenbaums findet Ihr den Schrein von Aviana, Heimat der Druiden der Kralle. Aviana, die oberste Mutter aller geflügelten Kreaturen, hat ihr Leben vor zehntausend Jahren für diese Welt hergegeben.\n\nIch spüre, dass ihr Schrein in Gefahr ist, genau wie die Druiden, die ihn bewachen. Sucht Choluna, einen der weisesten der geflügelten Druiden, tief innerhalb des Schreins auf.", sourceObjective = "Findet Choluna im Schrein von Aviana auf dem Hyjal.", completion = "Ysera selbst schickt Euch zu mir? Oh! Welch eine Ehre, mit einem Abgesandten der Aspekte zu sprechen.\n\nEs stimmt, dass unser Schrein in Gefahr ist. Die Harpyien, denen unsere Äste Schutz boten, haben sich gegen uns gewandt.\n\nDoch bitte stürzt Euch nicht in die Schlacht, bis Ihr nicht bereit seid. Unser Schrein ist nicht wie ein gewöhnliches Schlachtfeld. Benutzt seine Ruhe und Macht, um Eure Mitte zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27875] = { id = 27875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebetsblume", description = "Ich habe jahrelang daran gearbeitet, die Krankheit der Zerschlagenen heilen zu können. Die verruchten Energien, die sie verdorben haben, haben mehr getan, als nur ihre Körper zu verunstalten... Sie haben ihnen das Licht geraubt. Sie können seine Wärme nicht spüren.\n\nIch kann Magtoor nicht der Dunkelheit überlassen, {name}. Bevor es mit ihm schlimmer wurde, habe ich die Gebetsblume untersucht, die im Wabersumpf gedeiht. Selbst im dunkelsten Schatten wächst sie dort. Ich flehe Euch an, bringt mir einige davon, um des armen Magtoors Willen.", sourceObjective = "Sammelt 10 Zweige der Gebetsblume im Wabersumpf.", progress = "Habt Ihr die Gebetsblume dabei?", completion = "Die Zerschlagenen haben seit ihrer Ankunft in diesem Sumpf Gebetsblumen als Heilmittel verwendet. Wenn sie körperliche Schmerzen lindern, können sie vielleicht auch für mächtigere Heilungen verwendet werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[27876] = { id = 27876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Sumpfes", description = "Der Wabersumpf verdankt seinen Namen einem einzigartigen Phänomen. Durch irgendeine Kraft angetrieben, sammelt sich der extrem feine Schlick und bewegt sich von allein vorwärts, als wäre er lebendig.\n\nZuerst war ich beunruhigt, dass dies eine verderbliche Kraft sei, aber meine Studien ergaben das Gegenteil: Welche Energie auch immer diesem Boden Leben einhaucht, sie ist positiver Natur. Vielleicht könnten auch die Zerschlagenen auf diese Art zu ihrem früheren Selbst wiedererweckt werden.\n\nDer Schlick mag es vielleicht nicht, eingesammelt zu werden, {name}, aber bitte tut es trotzdem.", sourceObjective = "Sammelt 10 Exemplare kräftigen Schlick von Wabersumpfklumpen.", progress = "Konntet Ihr die Proben besorgen?", completion = "Wir werden es reinigen müssen, aber dann wird es sich als äußerst hilfreich erweisen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27877] = { id = 27877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwachkopfliga", description = "Ich brauche Eure Hilfe bei einem kleinen Projekt, an dem ich arbeite, {name}. Es fällt in einen Bereich, den ich gerne als \"defensive Archäologie\" bezeichne.\n\nIch möchte nichtmagische Gegenstände an verdächtigen Orten vergraben, damit diese Idioten der Allianz glauben, sie hätten etwas Wertvolles gefunden.\n\nHmm... An Hammerzehs Ausgrabungsstätte und der Festung Angor im Norden treiben sich die Dunkeleisenzwerge herum. Bringt mir ihre Köpfe. Ja, Ihr habt richtig verstanden, ihre Köpfe.\n\nSobald wir ihnen das Fleisch abgezogen haben, können wir die Schädel nutzen, um die Arbeiten der Zwerge zu stören.", sourceObjective = "Besorgt 15 Dunkeleisenköpfe.", progress = "<Lidia schaut Euch erwartungsvoll an.>", completion = "Ausgezeichnet! Wir werden sie sofort vergraben. Diese Dummköpfe der Forscherliga werden niemals darauf kommen, dass wir das waren!", sourceObjectiveStatus = "unverified-source-field" }
quests[27878] = { id = 27878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewaltsame Aneignung", description = "Ich habe Euch einen kleinen Vorschlag zu machen, wenn Ihr interessiert seid.\n\nDie Dunkeleisenzwerge waren schon lange vor uns hier. Das heißt, dass die Zwerge als Erste dort waren, als die Titanenruinen zum Vorschein kamen, und sich die wertvollsten Gegenstände unter den Nagel gerissen haben. Ich wette, diese Schätze sind noch immer in der Festung Angor, nordwestlich von hier, unter Verschluss.\n\nWenn Ihr einen solchen Schatz haben wollt... stehlt ihn einfach.", sourceObjective = "Sucht im untersten Geschoss der Festung Angor nach Schätzen.", progress = "So früh schon zurück?", completion = "Ich wusste es! Der Oberste Prüfer wird das mit Freuden sehen.\n\nGute Arbeit, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27879] = { id = 27879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben der Dicksten", description = "Uns gehen die Vorräte zur Neige, Fremder. Solange die schwarzen Drachen unsere Jagdgründe mit Zerstörung überziehen, haben wir keine Chance, an Nahrung zu gelangen.\n\nDie Oger im Süden jedoch haben genau, was wir brauchen. In ihrer Grotte solltet Ihr ausreichend Nahrung und Handwerkswaren finden.\n\nSie könnten sich aber mit Euch darum schlagen wollen. Seid also vorsichtig.", sourceObjective = "Erlangt 6 Fleischstücke der Staubspeier und 10 Lagen Seide der Staubspeier.", progress = "Willkommen zurück.", completion = "Ich nehme an, die Oger waren für Euch keine zu große Hürde. Hier - ein paar Münzen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27880] = { id = 27880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonnenschwere Starrköpfe", description = "Meine Grunzer haben dieses Drachenproblem im Griff. Im Übrigen kann ich nicht zulassen, dass ein Grünschnabel wie Ihr, {class}, dort hineinrennt und unsere Schlachtpläne ruiniert.\n\nIhr wollt Arbeit? Na schön, ich gebe Euch Arbeit, Untersucht das Ogerlager im Südwesten. Nach dem, was ich höre, scheint eine kleine Armee Kämpfer vor ihrem Unterschlupf aufgetaucht zu sein.\n\nWir können nicht herumsitzen und warten, bis sie uns in die Flanke fallen, Soldat... zumal wir bereits von schwarzen Drachen in Kämpfe verwickelt werden. Dünnt ihre Ränge aus, bevor sie es mit den unseren tun.", sourceObjective = "Tötet 12 Kämpfer der Staubspeier. Ihr könnt sowohl Raufer als auch Schamanen der Staubspeier töten.", completion = "Ihr habt den Hauch eines Helden in Euch, {race}.\n\nJetzt verschwindet von meinem Schlachtfeld.", sourceObjectiveStatus = "unverified-source-field" }
quests[27881] = { id = 27881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwächterposten", description = "Ich habe eine Idee, die reine Spekulation ist. Zum Glück sind reine Spekulationen eine meiner Spezialitäten.\n\nNördlich von hier hat die Archäologische Akademie neue Ruinen der Titanen unter dem Sand gefunden. Wenn es jemanden gibt, der älter und weiser ist als die Drachen, sind es die Titanen. Ich habe sogar Gerüchte gehört, dass die Titanen die Drachen ERSCHAFFEN haben.\n\nSprecht mit dem Obersten Prüfer Tae'thelan Blutwächter in seinem Lager nordwestlich von hier. Er wird weitaus mehr über die Titanen wissen als ich.\n\nWas habe ich Euch gesagt? Reine Spekulation.", sourceObjective = "Sprecht mit dem Obersten Prüfer Tae'thelan Blutwächter am Blutwächterposten im Ödland.", completion = "Titanen? Ihr seid hier, um mit mir über die Titanen zu reden?\n\nDa seid Ihr am richtigen Ort, denn wir stehen kurz vor einer großen Entdeckung. Doch zuerst werdet Ihr Euch Euren Platz hier verdienen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27882] = { id = 27882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht nicht um Geschichte, sondern um Macht", description = "Die Forscherliga mag ja einiges über den Vorgang des Grabens wissen. Was ihnen allerdings fehlt, ist ein Gefühl dafür, wie man die Artefakte BENUTZT, die sie ausgraben. Sie stellen ihre Schätze in statische Museen, statt diese mächtigen Dinge gemäß ihrer wahren Bestimmung zu verwenden.\n\nDie Zwerge sind Narren. Zum Glück sterben sie sehr schnell.\n\nIhr findet sie nördlich von hier, wie sie in die Wände der Schlucht hineingraben. Reißt ihnen alles, was Ihr könnt, aus ihren Händen mit den Stummelfingern und bringt es mir.", sourceObjective = "Beschafft einen zerbrochenen Kelch, eine staubige Vase, eine irdene Hieroglyphe und ein Troggwerkzeug.", progress = "Ihr seid mit den befreiten Artefakten zurückgekehrt, nehme ich an?", completion = "Kelch... wertlos.\n\nVase... gefälscht.\n\nHieroglyphe... interessant, aber ziemlich weit verbreitet.\n\nWas ist das? Ich habe noch nie Trogghandwerkskunst von diesem Ausmaß gesehen! Da seid Ihr tatsächlich etwas äußerst Seltenem begegnet, {name}.\n\nWir dürfen keineswegs die Troggs einfach übersehen. Sie mögen von schlichtem Gemüt sein, aber sie wissen Dinge über die tiefen, versteckten Orte dieser Welt.\n\nIhr habt Eure Arbeit recht ordentlich gemacht. Reden wir über Titanen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27883] = { id = 27883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer des Wächters", description = "Einer der wenigen Gegenstände von Wert, die wir aus diesen Ruinen mitgenommen haben, ist diese kleine Jadestatue.\n\nWir glauben, es ist eine Art Schlüssel, aber wir konnten nicht feststellen, was sie öffnet. Daher ist sie nutzlos für mich.\n\nVielleicht werdet Ihr mehr Glück damit haben.", sourceObjective = "Findet im Grab der Wächter im Ödland Verwendung für den Bauer des Wächters.\n\nBereitgestellter Gegenstand:", completion = "<Die Statue rastet in ihren Platz auf der großen Steinplatte ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27884] = { id = 27884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bauer der Schildwache", description = "Wir haben diese kleine rote Statue bei der Leiche eines dieser Forscherliga-Archäologen gefunden. Leider waren es nicht wir, die sie umgebracht haben. Die örtliche Wildnis hatte das bereits übernommen.\n\nDie Statue ist schön gearbeitet, hat aber anscheinend ihre magische Kraft verloren. Ihr könnt mit ihr machen, was immer Ihr für richtig haltet.", sourceObjective = "Findet eine Verwendung für den Bauern der Schildwache innerhalb des Tempels des Grabes der Behüter im Ödland.", completion = "<Die Statue gleitet über den kalten Marmorboden und rastet ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27885] = { id = 27885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel des Wächters", description = "Ihr seht, wie sich die Statue erst in zwei, dann in vier, dann in acht identische Statuen in quadratischer Anordnung teilt.\n\nIhr hört eine Stimme, jedoch nicht mit Euren Ohren, sondern direkt in Eurem Kopf:\n\n\"Ein wahrer Wächter sieht nicht nach AUSSEN, um nach Anzeichen der Gefahr zu suchen.\n\n Ein wahrer Wächter richtet seinen Blick nach INNEN, immer darauf konzentriert, seine Beute zu schützen.\"\n\nVielleicht ist dies eine Art Rätsel?", sourceObjective = "Beendet das Spiel des Wächters, indem Ihr die Bauern des Wächters in eine nach innen gerichtete Position teleportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[27886] = { id = 27886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schildwachenspiel", description = "Als Ihr die Statue an ihren Platz stellt, erscheinen weitere steinerne Statuen in dem Raum. Es taucht auch eine rubinfarbene Statue auf, in einer kleinen Nische am hinteren Ende des Raums. Ihr hört eine Stimme:\n\n \"Die Schildwache sieht.\n Die Schildwache beschützt.\n Der Blick der Schildwache ist niemals abgelenkt.\"\n\nDiese rote Statue am anderen Ende des Raums sieht wichtig aus. Vielleicht solltet Ihr versuchen, die beiden roten Statuen zu verbinden?", sourceObjective = "Schließt das Spiel der Schildwache ab, indem Ihr die beiden roten Statuen verbindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27887] = { id = 27887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Beschützer", description = "Man hört ganz schön viel Gerumpel aus der zentralen Kammer des Grabes. Diese zwei großen Statuen sahen ganz schön verdächtig aus.", sourceObjective = "Untersucht den Wächter und die Schildwache.", sourceObjectiveStatus = "unverified-source-field" }
quests[27888] = { id = 27888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Blam", description = "Innerhalb der Kiste findet Ihr einen kleinen, runden Gegenstand, der auf einem Kissen liegt.\n\nWenn es hier unten ein Titanenartefakt geben sollte, dann muss es das sein. Ihr beschließt, ihn zu Dr. Blam zurückzubringen.", sourceObjective = "Bringt das Auge der Behüter zu Dr. Hieronymus Blam bei der Agmondkuppe im Ödland.", progress = "Und? Hat sich unser Schuss ins Blaue ausgezahlt?", completion = "Bloß ein winzig kleines Gerät?\n\nIch habe diese Titanen noch nie verstanden.\n\nNun gut! Wollen wir doch mal sehen, was dieser Piepser kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[27889] = { id = 27889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu-Kargath", description = "<Dr. Blam sieht sich das Ei schweigend an, zwinkert ein paar Mal und schaut Euch dann an.>\n\nHabt... Habt Ihr das gesehen? Unglaublich! Meine Idee mit dem Titanending hat funktioniert! Mit Eurer Hilfe, natürlich.\n\nWir sollten das hier zu Rhea bringen. Sie ist nicht mehr in der Lethlorklamm... Ihre Tarnung ist wohl aufgeflogen, als sie vor all diesen Welpen ihre wahre Form angenommen hat. Jetzt ist sie in einer großen Hordenniederlassung im Westen mit Namen \"Neu-Kargath\".\n\nSie wird auf Euch warten. Und auf das Ei.", sourceObjective = "Bringt das geläuterte Schwarzdrachenei zu Rhea in Neu-Kargath im Ödland.", progress = "Da habt Ihr aber eine ganz schön wertvolle Ladung dabei, {name}.", completion = "Ich nehme Euch das Ei nun ab. Wir müssen es schleunigst bebrüten... und verstecken. Eine Menge wütender Drachen suchen danach.\n\nEs ist übrigens schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27890] = { id = 27890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die harten Hunde", description = "In meiner Hast bei der Flucht aus der Lethlorklamm habe ich vergessen, mich um eine letzte Sache zu kümmern: Nyxondra. Sie ist frei und hat Alarm beim schwarzen Drachenschwarm ausgelöst. Der halbe Schwarm ist hier im westlichen Ödland und sucht nach dem Ei.\n\nIch kümmere mich darum, das Ei zu verstecken. Ihr kümmert Euch um einige der vorwitzigeren Drachen. Und Ihr werdet Hilfe dabei haben. Ich habe ein paar Söldner angeheuert, Ihr werdete sie in diesem Gasthaus finden.", sourceObjective = "Sprecht mit Amakkar in Neu-Kargath im Ödland.", completion = "Ihr seid der, auf den wir gewartet haben? Wurde auch Zeit, dass Ihr hier seid. Ich warte schon darauf, mir die Beine zu vertreten.\n\nAbmarsch, Jungs! Gehen wir ein paar schwarze Drachen töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27891] = { id = 27891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amakkar, der Alleskönner", description = "Bevor wir mit der Drachenjagd beginnen, lasst mich Euch ein bisschen erklären, wie ich kämpfe.\n\nIch bin nicht so stark oder robust wie diese zwei, aber ich hab ein paar Tricks im Ärmel. Auf Euren Befehl hin betäube ich Eure Feinde, um sie festzunageln. Ich habe auch immer ein paar Tränke auf Lager.\n\nWarum trainieren wir nicht ein bisschen zusammen? Auf in die Wildnis, dann werdet Ihr sehen, was es heißt, mit einem echten Orc zusammen zu kämpfen.", sourceObjective = "Benutzt 'Amakkars Nierenhieb' und 'Amakkars Taschentrank'.", completion = "Ich freue mich darauf, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27892] = { id = 27892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jurrix der Vollstrecker", description = "Oh, Ihr wollt Euch unterhalten? Also schön.\n\nIch bin Jurrix, der einzige Söldner hier, der noch ein paar Gehirnzellen hat. Und der einzige, dessen Angriffe wirklich etwas bewirken. Diese lebenden Schilde um mich herum behalte ich nur, damit ich nicht getötet werde.\n\nHört zu, Ihr seid der Chef dieser Operation. Ihr müsst nur ein Wort sagen und ich werde einen Feuerball durch das Herz Eures Ziels jagen. Wenn das alles zu schnell geht, kann ich sogar die Zeit ein wenig verschieben, damit Ihr noch ein paar zusätzliche Angriffe unterbringen könnt.\n\nWarum versuchen wir nicht, gemeinsam zu kämpfen?", sourceObjective = "Benutzt 'Jurrix' Feuerstoß' und 'Jurrix' Zeitverschiebung'.", completion = "Ich glaube, Ihr seid bereit, {name}. Allmählich bekommt Ihr es in den Griff.", sourceObjectiveStatus = "unverified-source-field" }
quests[27893] = { id = 27893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargal, das Ungetüm", description = "Es ist Euch vielleicht nicht aufgefallen, aber für einen Orc bin ich recht groß.\n\nIch stelle sicher, dass meine beiden Kumpel hier nicht in zu große Schwierigkeiten geraten. Sie sind klein und haben nicht so einen großen Schild wie ich. Ich bin groß und kann ein paar Schläge von Monstern gut wegstecken! Außerdem kann ich es meistens schaffen, dass sie nur meinen Schild treffen!\n\nIch kann auch Euch beschützen. Kommt, gehen wir ein bisschen trainieren. Ich sorge dafür, dass die Gegner mich angreifen, nicht Euch.", sourceObjective = "Benutzt 'Gargals Schildwall' und 'Gargals mächtiger Ruf'.", completion = "Seht Ihr? Kein Grund zur Sorge, wenn Gargal da ist. Sagt mir nur Bescheid und ich beschütze Euch vor den Monstern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27894] = { id = 27894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn eines Drachenschwarms", description = "Hallo, {name}. Mir scheint, Ihr vier hattet genug Zeit, Euch anzufreunden.\n\nIch habe eine erste Aufgabe für Euch. Kalaran, ein uralter schwarzer Drache mit beträchtlicher Macht, hat sich der Jagd auf das von uns beschützte Ei angeschlossen. Wir müssen ihn aufhalten, bevor er ihm zu nahe kommt.\n\nIhr findet ihn und seine Diener im Staubbecken, östlich von Neu-Kargath. Sucht und besiegt ihn. Wahrscheinlich werdet Ihr die Hilfe Eurer neuen Söldnerverbündeten brauchen.", sourceObjective = "Tötet Kalaran den Vernichter und 4 Soldaten des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27895] = { id = 27895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd geht weiter", description = "Der schwarze Drachenschwarm meint es ernst. Wie Ihr wahrscheinlich bemerkt habt, hat er einen Großteil von Neu-Kargath an sich gerissen. Diese Truppen stehen unter dem Befehl von General Jirakka und seinem Champion Moldarr. Sie müssen aufgehalten werden.", sourceObjective = "Besiegt General Jirakka, Moldarr und 6 Mitglieder der Drachenbrut des dunklen Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[27896] = { id = 27896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leid und der Zorn", description = "Am meisten bereue ich, wie wir... nein, wie ich Nyxondra behandelt habe. Ich habe sie gezwungen, Eier zu legen, und dann mit ihnen experimentiert. Immer und immer und immer wieder.\n\nObwohl ich selbst Mutter bin, kann ich mir ihr Leid kaum vorstellen.\n\nNein... Ich darf nicht schwach werden. Unsere Arbeit dient immerhin dem Wohl der zukünftigen Generationen der schwarzen Drachen. Ihr Opfer war notwendig.\n\nNun umkreist sie die Ruinen von Kargath, nordwestlich von Neu-Kargath, wahnsinnig vor Zorn. Bitte, Helden... erlöst sie von ihrem Elend.", sourceObjective = "Erschlagt Nyxondra und 12 von Nyxondras Brutlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27897] = { id = 27897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteckte Gelege", description = "Jetzt, da die meisten schwarzen Drachen aus dem Ödland abgezogen sind, können wir das Ei wieder sicher transportieren. Ihr werdet mich auf einer kleinen Hochebene nördlich von Neu-Kargath finden.\n\nSucht mich dort auf.", sourceObjective = "Sprecht mit Rhea im Versteckten Gelege im Ödland.", completion = "Das Ei muss immer in Bewegung bleiben. Wir sind hier nicht mehr sicher.\n\nSogar in seinem Wahnsinn kennt Todesschwinge alle versteckten Orte dieser Welt. Das Ei kann nicht an einem Ort bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27898] = { id = 27898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastraszas Geschenk", description = "Wartet hier. Ich werde das Ei holen.", sourceObjective = "Wartet, während Rhea das Ei aus dem Versteckten Gelege holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27899] = { id = 27899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leuchten in seinen Augen", description = "Wenn Ihr nach Harrison sucht, den habt Ihr gerade verpasst.\n\nEr hat die ganze Zeit über seine neueste Entdeckung geredet und wie alles jetzt anfängt, einen Sinn zu ergeben.\n\nWie auch immer... Sein Gerede hat für mich keinen Sinn ergeben.\n\nIch habe versucht, ihn zum Hierbleiben zu bewegen und sich mit mir an ein paar Sonnenuntergängen in der Wüste zu erfreuen, aber wenn er dieses Leuchten in den Augen hat, kann man mit ihm nicht reden.\n\nKönntet Ihr einmal nach ihm sehen?\n\nEr ging nach Süden zu dem großen Monolith.", sourceObjective = "Sprecht mit Harrison Jones am Obelisk der Sonne.", completion = "Wie es scheint, bin ich nicht der einzige, der sich für diese Obelisken interessiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[27900] = { id = 27900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Kerl werde ich fertig", description = "Gutes Timing, {name}.\n\nAnscheinend bin ich nicht der Einzige, der sich für diese Obelisken interessiert und diese Jungs haben kein Interesse an einem Erfahrungsaustausch.\n\nIch glaube, mit dem Kerl hier werde ich fertig.\n\nVielleicht könntet Ihr Euch um ein paar seiner Freunde kümmern, bevor sie auch hierher kommen?", sourceObjective = "Tötet 10 Lufteinheiten von Schnottz.", completion = "Welch eine Erleichterung. Danke {name}.\n\nWie sich herausstellt, habe ich hier alle Hände voll zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27901] = { id = 27901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie wissen nicht, was sie hier haben", description = "Hört zu, {name}. Ich habe nicht viel Zeit zum Reden.\n\nDiese Kerle graben hier Relikte aus und greifen sich die Teile uralter Technologie, die wir brauchen!\n\nIhr müsst ihre Kisten nach Teilen eines uralten Aktivierungsgerätes durchsuchen. Die Offiziere müssten die Codes haben, die Ihr zum Öffnen der Kisten benötigt.\n\nBeeilt Euch.\n\nWir dürfen nicht zulassen, dass sie das Zeug in ihre Flugzeuge laden!", sourceObjective = "Baut das Aktivierungsgerät der Titanen zusammen.", progress = "Habt Ihr das Aktivierungsgerät der Titanen, {name}?", completion = "Das ist es!\n\nGut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27902] = { id = 27902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reinquell", description = "Magtoor hat mir von dem Schamanismus berichtet, den die Zerschlagenen betreiben. Der große Nobundo sagte einst, dass der Pfad der Elemente in gewisser Weise nur ein weiterer Weg zum Licht sein könnte.\n\nIch kann nur hoffen, dass daran etwas Wahres ist. Die Elementare, die sich in der Nähe der Reinquellhöhle im Süden aufhalten, sind eine Quelle wahrlich makellosen Wassers. Sie können chaotisch und brutal sein, aber das von ihnen erbeutete reine Wasser ist die perfekte Leitung für den Segen des Lichts.\n\nBitte bringt mir dieses Wasser, {name}.", sourceObjective = "Sammelt 6 Reinquellpartikel von Reinquellelementaren.", progress = "Haben die Elemente ihre Quelle aufgegeben?", completion = "Solch eine Klarheit... Hoffen wir, dass dies dem armen Magtoor hilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27903] = { id = 27903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zündung", description = "Dieser Kerl lässt sich nicht unterkriegen!\n\nIhr macht Eure Sache gut, <mein Junge/meine Liebe>. Jetzt bleibt nur noch eins zu tun.\n\nMeine Forschungen haben ergeben, dass dort unten eine Titanenstatue sein müsste. Benutzt das Gerät, um sie zu aktivieren und nehmt sie dann auseinander.\n\nWenn meine Theorie richtig ist, verbirgt sich in der Statue der Schlüssel, um diesen Obelisken wieder zu aktivieren.", sourceObjective = "Besorgt die Linse der Sonne.", progress = "Zeit, herauszufinden, ob dieser alte Mechanismus noch funktioniert...", completion = "Laut Harrisons Notizen, sollte der Obelisk reaktiviert werden, wenn man die Linse auf dieses Podest legt.\n\nWas genau das bedeutet, werden wir dann sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27904] = { id = 27904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelatem", description = "Die Grelle sind Waldgeister, die sich östlich von hier im Nebligen Tal aufhalten. Sie sehen zwar aus wie Wichtel, aber bei denen, die ich untersucht habe, konnte ich keine dämonischen Spuren feststellen. Soweit ich das sagen kann, sind sie unverderbt.\n\nDiejenigen, die im Tal leben, sind eins mit dem Wind. Sie beschwören Böen, wenn ihnen danach ist. Diese reine Luft kann ich vielleicht in meinem Heilmittel für den armen Magtoor verwenden.\n\nBitte, {name}, sammelt rauchgraue Kristalle für mich. Man findet sie in den Körpern der Grelle. Ich muss jedes mögliche Heilmittel ausprobieren.", sourceObjective = "Beschafft 5 rauchgraue Kristalle von Nebelgrellen.", progress = "Habt Ihr die Kristalle?", completion = "Hoffentlich werde ich mit ihnen eine Heilung finden, {name}. Danke, dass Ihr sie mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27905] = { id = 27905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heckschütze!", description = "Okay, ich habe diesen Kerl weichgeklopft, wie wäre es, wenn Ihr mir helft, ihn zu erledigen?\n\nIch habe einen Fluchtplan für uns, aber dafür braucht man viel Mut und ein bisschen Glück.\n\nSeid Ihr dabei, {name}?\n\nDann folgt mir...", sourceObjective = "Benutzt das Heckgeschütz, um den Bomber von Schnottz zu verteidigen.", completion = "Das war gute Arbeit da hinten, {name}.\n\nAnscheinend sind wir sie losgeworden - wenigstens für den Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27906] = { id = 27906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Blutnarbe", description = "Es gibt noch viel zu tun, um uns von dem Angriff zu erholen und auf den nächsten vorzubereiten. All unsere Späher werden sich koordinieren müssen.\n\nNeeka Blutnarbe ist unsere beste Späherin und im harschen Ödland ausgebildet worden. Sie wurde zur Splitterspeerkreuzung geschickt, um Allianzaktivitäten zu überwachen.\n\nBegebt Euch zu Neeka, {name}. Berichtet Ihr, was in Steinard vorgefallen ist. Unterstützt sie bei allem, worum sie Euch bittet.", sourceObjective = "Sprecht mit Neeka Blutnarbe an der Splitterspeerkreuzung.", completion = "Ich hoffe, dass Euch meine Trauer amüsiert, {name}. In dieser Gegend wird das die einzige Unterhaltung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27907] = { id = 27907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebetsblume", description = "Ich bin ruiniert, {class}. Ich habe meine Stärke in Helgrum investiert, und jetzt blutet sie aus seinen klaffenden Wunden. Wunden, die zu tief sind, um zu heilen, Fleisch, das sich nicht mehr schließen will.\n\nEr murmelt vor sich hin, vor Angst, Schmerz und Fieber. Ich kann jetzt nicht von seiner Seite weichen. Nicht jetzt. Bitte, ich muss Euch voller Scham bitten, mir ein paar Kräuter zu besorgen.\n\nDie Gebetsblume, die in den Sümpfen wächst, ist eine alte Heilpflanze. Damit sollten seine Schmerzen gestillt werden können.", sourceObjective = "Sammelt 10 Zweige der Gebetsblume im Wabersumpf.", progress = "Habt Ihr die Gebetsblume dabei?", completion = "Ich werde sie zermahlen und versuchen, sie ihm einzuflößen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[27908] = { id = 27908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Sumpfes", description = "Helgrums Wunden entzünden sich in dem Sumpfklima. Sie schwellen an und eitern, und erfüllen seine letzten Minuten mit Höllenqualen. Ich brauche etwas, um sie abzudecken.\n\nDie Geister gehen in diesem Sumpf um. Sie erfüllen selbst den Schlamm, formen ihn zu Brocken glatter Erde und hauchen ihm Leben ein.\n\nDie Geister des kühlen, reinen Schlicks werden ihm etwas Linderung verschaffen. Bitte sammelt ihn für mich, da ich ihn nicht allein lassen möchte.", sourceObjective = "Sammelt 10 Exemplare kräftigen Schlicks von Wabersumpfklumpen.", progress = "Helgrum atmet noch. Habt Ihr den Schlick dabei?", completion = "Wenigstens kann ich seine Schmerzen mit meinen Händen lindern, während er noch atmet. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27909] = { id = 27909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reinquell", description = "Helgrums Atemzüge werden langsamer. Seine Zeit ist gekommen.\n\nIch brauche Wasser. In den Teichen der Reinquellhöhle streifen Elementare umher. Das Wasser, das aus ihnen strömt, ist das reinste hier im Sumpf.\n\nSelbst wenn ich es wagte, von Helgrums Seite zu weichen, würde meine Axt in meiner Hand zittern. Ich flehe Euch nochmals an, Mitleid mit mir zu haben, um seinetwillen. Bringt mir die Partikel der Elementare, auf dass sein letzter Trank rein und erquicklich sein möge.", sourceObjective = "Sammelt 8 Reinquellpartikel von Reinquellelementaren.", progress = "Ihr seid zurückgekehrt.", completion = "Er kann nicht so viel trinken. Den Rest können wir vielleicht benutzen, um seinen Körper zu waschen, nachdem...\n\n<Neeka starrt frustriert, erschauert und dreht dann ihren Kopf zur Seite.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27910] = { id = 27910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späte Reue", description = "Wenn ich mich schon erniedrigen und kriechen muss, dann kann ich auch nach allem fragen, was ich kriegen kann. Es gibt einen letzten Gefallen, um den ich Euch bitten würde - nur noch eine Aufgabe, um die ein beschämter Orc Euch bittet.\n\nHelgrum hatte eine Beute, die er über alles schätzte. Dämmerfang, der Ogerfresser, der große Panther des Nebligen Tals. Er hat sich niemals die Muße genommen, ihn zu verfolgen. Obwohl er ihn unbedingt jagen wollte, so waren doch unsere Späherpflichten zu wichtig.\n\nWenn er Dämmerfang nicht in dieser Welt jagen kann, so soll er ihn in der nächsten jagen können. Nehmt die Jagd für ihn auf und bringt mir Dämmerfangs Balg.", sourceObjective = "Besorgt Dämmerfangs Balg.", progress = "Hat Dämmerfang sich gezeigt?", completion = "Jetzt, da Dämmerfang seinen Körper umhüllt, wird er den Geist des Tieres mit ins Jenseits nehmen.\n\nHört auf mich. Einen abergläubischen, alten Narren. Es tut mir so leid, Helgrum...", sourceObjectiveStatus = "unverified-source-field" }
quests[27911] = { id = 27911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Atemzug", description = "Er regt sich...\n\nBitte bleibt bei mir, {name}. Lasst uns gemeinsam Helgrum ehren. Ihr habt so viel für ihn getan.", sourceObjective = "Begleitet Helgrums letzte Momente auf Erden.", completion = "Er ist von uns gegangen.\n\nEr hat Recht. Ich muss stark für ihn sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[27912] = { id = 27912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Titanen", description = "Als der zweite Verteidiger zu Boden fällt, erscheint im hinteren Teil der Kammer eine Kiste. Könnte es das sein, was sie beschützt haben?", sourceObjective = "Untersucht den Schatz der Behüter.", completion = "Ihr werft einen Blick in die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[27913] = { id = 27913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Titanen", description = "Als der zweite Verteidiger zu Boden fällt, erscheint im hinteren Teil der Kammer eine Kiste. Könnte es das sein, was sie beschützt haben?", sourceObjective = "Untersucht den Schatz der Behüter.", completion = "Ihr werft einen Blick in die Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[27914] = { id = 27914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Grünen Drachenschwarms", description = "Ihr habt gute Arbeit geleistet, {name}. Jammal'an ist uns zwar entkommen, aber sein Rückzug erlaubt es mir, den Tempel nach Belieben zu betreten.\n\nBleibt, wo Ihr seid und bewegt Euch nicht. Ich werde Eure Rückkehr beschleunigen, indem ich Euren Geist durch den Smaragdgrünen Traum zu mir bringe.\n\nDabei wird Euch vielleicht etwas schwindelig.", sourceObjective = "Sprecht mit Lord Itharius an der Spitze des Tempels von Atal'Hakkar.", completion = "Ihr habt mir und meinem Volk einen großen Dienst erwiesen, {name}. Nehmt dies als Symbol meines Dankes und Eures Mutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27915] = { id = 27915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Tempels", description = "Ich muss gestehen, dass ich persönlich in diese Angelegenheit verwickelt bin. Einer der ersten grünen Drachen, die hier verderbt wurden, war mein Bruder Eranikus.\n\nIch dachte, dass Eranikus tot sei, für immer von den düstersten Rissen des Alptraums verschluckt. Doch nun habe ich gehört, dass sein Schemen im Tempel aufgetaucht ist. Ich weiß nicht, ob er es wirklich ist oder nur ein leeres, schwermütiges Echo seiner selbst.\n\nWenn Ihr mir weiter helfen wollt, kehrt zur Halle der Masken zurück und reist durch den Bogengang in das wahre Sanktum des Tempels. Ich werde dort auf Euch warten.", sourceObjective = "Sprecht im Inneren des Tempels von Atal'Hakkar erneut mit Lord Itharius.", completion = "Ich freue mich, Euch wiederzusehen, {name}. Es ist sehr ehrenhaft von Euch, dass Ihr mich weiterhin unterstützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27916] = { id = 27916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruags Bericht", description = "Hier ist Ruags Bericht, {name}. Sagt ihm, dass sein Kundschafter immer noch hier ist.\n\nErwähnt Helgrum nicht. Niemand sonst soll durch diese tragische Nachricht abgelenkt werden.\n\nIch selbst muss stark sein. Wir alle müssen stark sein.", sourceObjective = "Überbringt Zentralenkommandant Ruag in Steinard den Splitterspeerbericht.", progress = "Ja?", completion = "<Ruag überfliegt den Bericht.>\n\nIch verstehe. Danke für diese Informationen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27917] = { id = 27917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschnüffelt sie", description = "Ich konnte Godfrey und seine Kameraden schon kilometerweit riechen. Sie haben ihre Spuren auf der Flucht nicht gerade gut verwischt. Ein Fehler, der sie in ihr Grab bringen wird.\n\nEiner von ihnen ist sehr nah und obwohl sich ihr Geruch im Untod verändert hat, bin ich sicher, dass es Ashbury ist. Geht hinein und reißt ihn in Stücke! Wir stellen sicher, dass die Verlassenen uns bei unserer Aufgabe nicht in die Quere kommen.", sourceObjective = "Tötet Baron Ashbury.", completion = "Der Duft von frisch vergossenem Verräterblut füllt meine Nase und er ist überaus belebend. Mein Kampfrausch wird aber erst verebben, wenn Godfrey als lebloser Haufen im Staub liegt.\n\nEr glaubt, eine Armee lebloser Kadaver kann den Zorn der Blutfangworgen aufhalten? Wir werden ihre Knochen noch jahrelang abnagen, nachdem unser Werk hier vollbracht ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[27918] = { id = 27918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sichere Hafen", description = "Anachoret Avuun ist einer unseren nicht verderbten Brüder, die anderen Völkern als Draenei bekannt sind. Er kam in den Sicheren Hafen, um uns zu heilen und zu versuchen, ein Gegenmittel zu finden. Er war es, der mich hierher geschickt hat, um diese Kristalle zu sammeln.\n\nEr kümmert sich gerade um einen sehr kranken Freund, und obwohl er sogar an die Exodar selbst Nachricht entsandt hat, findet er niemanden, der ihn unterstützt. Könntet Ihr ihm diese Kristalle bringen, {name}? Ihr seid vielleicht <der Einzige, der/die Einzige> die; ihm helfen kann.", sourceObjective = "Bringt die Draenethystkristalle zu Anachoret Avuun.\n\nBereitgestellter Gegenstand:", completion = "Vielen Dank, {class}. Ich fürchte, dass es zu spät sein könnte... aber ich weigere mich aufzugeben, selbst wenn die Exodar mein Flehen nicht erhört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27919] = { id = 27919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter in die Verwüsteten Lande", description = "Wir wissen Eure Hilfe hier in diesem Sumpf zu schätzen, {name}. Ich muss Euch mitteilen, dass ich ein Schreiben aus Burg Nethergarde erhalten habe.\n\nEnohar Donnerbräu bittet um Hilfe bei der Untersuchung der Schiffswracks in den Roten Weiten, doch niemand will diese Reise unternehmen. Ich selbst kann den Sicheren Hafen leider nicht verlassen.\n\nBurg Nethergarde liegt in den Verwüsteten Landen, südlich der Sümpfe des Elends. Kommt Steinard auf Eurer Reise nicht zu nah.", sourceObjective = "Reist in die Verwüsteten Lande und sprecht mit Enohar Donnerbräu in Burg Nethergarde.", completion = "Ah, schickt Euch Avuun? Gut, gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[27920] = { id = 27920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis an die Zähne bewaffnet", description = "Bei unserem Angriff auf die Burg sind wir auf unvorhergesehene Hindernisse getroffen, {name}. Es scheint, als würden die Diener, die Baron Silberlein und Kommandant Grüntal im Leben umsorgten, dies auch noch im Tode tun, und Godfrey hat sie direkt zwischen sich und uns platziert.\n\nKeine Sorge, wir werden nicht zulassen, dass sie mehr als eine kleine Unannehmlichkeit darstellen. Vernichtet sowohl Silberlein als auch Grüntal. Es wird die Wächter nicht nur ihrer Meister berauben, die ihnen Anweisungen geben, es wird uns auch unserem finalen Ziel sehr viel näher bringen.", sourceObjective = "Tötet Baron Silberlein und Kommandant Grüntal.", progress = "Es ist zum Verrücktwerden, dass wir diese Geistersoldaten töten müssen, obwohl sie rein gar nichts mit dem eigentlichen Missionsziel zu tun haben. Godfrey ist in der Tat ein gerissener Gegner.", completion = "Wir haben es fast geschafft, {name}. Die Zeit ist gekommen, den letzten Vorstoß zu machen und Walden das Handwerk zu legen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27921] = { id = 27921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Klauen und Zähnen", description = "Es scheint, als hätte Lord Walden unsere Anwesenheit endlich bemerkt und seine Verteidigung verstärkt. Verschwendete Liebesmüh... nichts wird unser Rudel aufhalten.\n\nDer Weg zu ihm ist voller Diener der Geißel, doch ich vertraue darauf, dass Ihr ihn freimachen könnt, damit der Rest von uns folgen kann. Sobald wir Walden getötet haben, sollten wir direkt zu seinem feigen Anführer vordringen können.", sourceObjective = "Tötet Lord Walden.", progress = "Wir stehen voll hinter Euch, {name}.", completion = "<Rudelführer Ivar Blutfang grinst Euch an, wobei er seine rasiermesserscharfen Zähne entblößt.>\n\nDank Eurer wackeren Hilfe dauert es jetzt nicht mehr lang, bis die Burg uns gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27922] = { id = 27922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter!", description = "Bitte, <Fremder/Fremde>. Ihr müsst mir helfen.\n\nIch bin hierhergekommen, um die Ankunft eines mächtigen Verbündeten der Neferset zu untersuchen. Dabei wurde ich von meinen engsten Verbündeten verraten und dem Feind überlassen.\n\nGeht zu der Terrasse über uns im Osten und sucht die Information, die ich nicht finden konnte. Ihr müsst Euch vor den Neferset verbergen. Vielleicht könnt Ihr Euch hinter einer der großen Pflanzen auf der Plattform verstecken, um Eure Anwesenheit geheim zu halten.\n\nErledigt das für mich und ich werde Euren Freunden dabei helfen, in Sicherheit zu gelangen.", sourceObjective = "Versteckt Euch hinter einem Wedel der Neferset und enthüllt das Geheimnis der Neferset.", progress = "Was habt Ihr gesehen, {name}?", completion = "Einen Dschinn! Wir müssen hier so schnell wie möglich weg.\n\nDiese unheilige Allianz der Neferset mit den Helfern von Todesschwinge bedeutet nichts Gutes für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[27923] = { id = 27923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauch in ihren Augen", description = "Ich weiß zwar nicht, was für einen behämmerten Plan Euer Freund da ausbrütet, aber wir werden eine Ablenkung brauchen, wenn wir eine Chance haben wollen, zu entkommen.\n\nNehmt die Fackel von der Kohlenpfanne und legt ein paar Feuer.\n\nVielleicht gelingt es uns dadurch, den Neferset-Abschaum für ein paar Minuten abzulenken und das gibt uns die Gelegenheit, die wir brauchen.", sourceObjective = "Verbrennt Heuhaufen in der Verlorenen Stadt der Tol'vir in Uldum.", completion = "Ja. Ich höre, wie die Neferset sich gegenseitig nach Osten rufen. Das könnte noch klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27924] = { id = 27924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budds Plan", description = "Ich hab' 'ne Idee! Vertraut mir, diesmal ist es eine gute!\n\nBesorgt einige dieser glänzenden Rüstungsteile, die die Katzenmenschen tragen.\n\nDieser Plan kann nicht schiefgehen. Vertraut mir.", sourceObjective = "Besorgt 6 Rüstungen der Neferset.", progress = "Habt Ihr die Teile, {name}?", completion = "Ausgezeichnet. Ihr werdet schon sehen, das kann unmöglich schiefgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27925] = { id = 27925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effiziente Ausgrabungen", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nEs wird deutlich, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist. \n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", sourceObjective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[27926] = { id = 27926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gastfreundschaft des Ostens", description = "Der Kommandant ist gerade sehr beschäftigt, fürchte ich.\n\nDie Anforderungen solch einer Operation nehmen dieser Tage fast seine ganze Aufmerksamkeit in Anspruch.\n\nWas haltet Ihr davon, Euch ein wenig unter unsere Gäste zu mischen, während Ihr darauf wartet, mit ihm zu sprechen?\n\nWir haben eine Auswahl der berühmtesten Einwohner Azeroths eingeladen, um der Enthüllung der Geheimnisse dieser Region beizuwohnen.\n\nIch bin davon überzeugt, dass Ihr sie ausgesprochen faszinierend finden werdet.", sourceObjective = "Bellok Leuchtklinge möchte, dass Ihr Euch unter die Gäste in Schnottz' Landeplatz mischt.", completion = "Ich gehe davon aus, dass Ihr keine Schwierigkeiten hattet, mit unseren Gästen auszukommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27927] = { id = 27927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinunter zur Narbe", description = "Das Ödland beherbergt einige ungewöhnliche Leute, viele davon halten sich hier schon seit geraumer Zeit auf. \n\nDa waren zum Beispiel drei Herren, die hier in der Stadt lebten. Ich vergesse immer ihre Namen... Der Zwerg hieß glaube ich Theldurin. Jedenfalls sind sie vor einigen Tage mit einem Rucksack voller Bier nach Süden aufgebrochen und seitdem habe ich nichts mehr von ihnen gehört. Ich glaube, sie wollten zu der großen Narbe.\n\nWürde es Euch etwas ausmachen, nach ihnen zu sehen? Ich wüsste gerne, dass es ihnen gut geht.", sourceObjective = "Findet Theldurin den Verirrten nahe der Narbe des Weltenbrechers im Ödland.", completion = "Man hat Euch geschickt, um nach uns zu sehen? Pfft... Ich lebe schon länger in dieser Wüste als die meisten dieser Trottel. Wir lassen nur die Landschaft auf uns wirken und erzählen uns Geschichten über alte Zeiten.\n\nErzählt Ihr gerne Geschichten?", sourceObjectiveStatus = "unverified-source-field" }
quests[27928] = { id = 27928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feines für den Fellhändler", description = "Der Kommandant kann zu denen, die ihm Loyalität erweisen, sehr großzügig sein. Ich wüsste da etwas, das Ihr tun könnt, um Euch bei ihm beliebt zu machen.\n\nBevor er seine... äh... Belegschaft aufgebaut hat, handelte er mit Tierfellen.\n\nEr ist in der Kunst der Lederverarbeitung sehr bewandert. Der Fellhändler kann sogar bei den zerlumptesten Fellen noch Wunder bewirken.\n\nDie ausgetrocknete Oase im Osten beheimatet angeblich eine seltene Koyotenrasse.\n\nIhre Felle wären ein wunderbares Geschenk.", sourceObjective = "Erbeutet 5 Felle eines Wüstenkoyoten.", progress = "Hattet Ihr Erfolg auf der Jagd?", completion = "Oh, die sind vorzüglich!\n\nDer Kommandant wird daraus eine Winteruniform herstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27929] = { id = 27929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt sie 'runter", description = "Ein einziger Drache des Drachenmalklans wiegt ein Dutzend Wildhammergreifenreiter auf. Holt sie von ihren verlausten Vögeln und sie sind nichts mehr wert.\n\nSogar Ihr könnt sie dann mit Leichtigkeit töten, Horden-{class}.\n\nJagt Greifenreiter, die über den Fluss nördlich von Blutschlucht fliegen. Nehmt diesen Haken und werft ihn auf sie, während sie vorüberfliegen. Durch ihren Schwung werden sie von ihrem Reittier genau vor Eure Füße geschleudert. Tötet sie! Tötet einige Donnermar-Greifenreiter und ich werde glauben, dass Eure Horde so mächtig ist, wie Ihr behauptet.", sourceObjective = "Benutzt den gestachelten Fleischerhaken, um 4 Donnermar-Greifenreiter von ihren Reittieren zu holen und tötet sie dann.", completion = "Ihr seht leicht angeschlagen aus. Diese Zwerge haben Euch keine Schwierigkeiten bereitet, oder doch?\n\nEs war dennoch eine beeindruckende Vorstellung.", sourceObjectiveStatus = "unverified-source-field" }
quests[27930] = { id = 27930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüstung", description = "Die Luft ist rein. Wenn Rheastrasza oder das Ei durch ein Wunder Todesschwinges Flammen überlebt haben, werden sie so bald wie möglich Eure Hilfe benötigen.", sourceObjective = "Sucht nach Rheastrasza.", completion = "Helden:\n\nWenn Ihr das hier lest, war mein Verdacht berechtigt. Todesschwinge hat uns gefunden. Das Ei ist zerstört - ebenso wie ich.\n\nDas war allerdings von Anfang an der Plan. Ihr müsst wissen... Das Ei, das Todesschwinge zerstörte, war nicht das Ei, das er suchte.\n\nEs war meins.", sourceObjectiveStatus = "unverified-source-field" }
quests[27931] = { id = 27931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bebenden Felder", description = "Bevor Ihr uns hier helfen könnt, müssen wir uns erst um die Streitkräfte Therazanes, der Steinmutter, im Süden kümmern. Die Elementare und Riesen der Bebenden Felder werden momentan zusammengestellt.\n\nAuch sie sind auf der Suche nach dem mittleren Fragment der Weltensäule. Sie werden uns mitten in unserem Krieg mit den Steintroggs angreifen und wir werden sie nicht abwehren können.\n\nIch habe den Erzgeomanten bereits vorgeschickt. Geht zu Schiefer Treibsand und tut, was er sagt.", sourceObjective = "Sprecht mit Schiefer Treibsand auf den Bebenden Feldern in Tiefenheim.", completion = "Gut, dass Ihr hier seid, {race}.\n\nWir müssen schnell handeln, um die Streitmächte Therazanes vom Angriff abzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27932] = { id = 27932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt der irdischen Trennung", description = "Die Smaragdkolosse sind die größten Kreaturen der Steinmutter. Sie müssen als erstes von dem Feld entfernt werden.\n\nIch habe Steinvater Erzmantels Axt für diesen Zweck mitgebracht. Benutzt sie, um die Riesen zu spalten.\n\nDadurch bekommen sie eine leichter zu handhabende Größe. Dann könnt Ihr sie töten.", sourceObjective = "Tötet 5 gespaltene Smaragdkolosse.", completion = "Danke, {name}. Ohne all ihre Riesen werden Therazanes Streitkräfte es schwerer haben, Steinruh einzunehmen.\n\nWenn Ihr jetzt bitte meine Axt zurückgeben würdet. Ich werde darauf aufpassen, bis Ihr den Steinvater retten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27933] = { id = 27933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarerz", description = "Ihr werdet Euch hier mit dem Anführer von Therazanes Streitkräften auseinandersetzen müssen. Um aber schnell und sicher zu ihm zu gelangen, muss ich ein Ritual durchführen.\n\nGeht hinaus aufs Feld und sammelt Elementarerz von den Jadewütern. Wenn wir genug davon haben, sollte ich in der Lage sein, Euch eins mit der Erde werden zu lassen, damit Ihr dorthin gelangt, wo Ihr hin müsst.", sourceObjective = "Sammelt 6 Elementarerze.", progress = "Habt Ihr alles Notwendige?", completion = "Das sollte reichen. Ich benötige nur einen Moment für die Vorbereitung des Rituals.", sourceObjectiveStatus = "unverified-source-field" }
quests[27934] = { id = 27934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eins mit der Erde", description = "Der hiesige Anführer der Streitkräfte der Steinmutter ist ein großer Erdelementarlord namens Lavinius. Zum Glück für uns haben die Kultisten des Schattenhammers beschlossen, in seine Höhle einzumarschieren. Ihr Ziel ist es, seine Elementare ihrem Willen zu unterwerfen.\n\nAus diesem Durcheinander werden wir einen Vorteil schlagen. Das Erdritual, das ich beschwöre, wird Euch eins mit der Erde werden lassen. Es wird Euch in die Nähe von Lavinius versetzen, ohne dass er Eure Gegenwart bemerkt.\n\nDann ist es an Euch, ihn zu beseitigen.", sourceObjective = "Beendet das 'Eins mit der Erde'-Ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27935] = { id = 27935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lawine ins Rollen bringen", description = "Lavinius steht vor Euch. Tötet ihn, um Therazanes Streitkräfte von einem Angriff auf Steinruh abzuhalten.", sourceObjective = "Tötet Lavinius.", completion = "Ihr habt etwas getan, zu dem nur wenige fähig gewesen wären. Lavinius besiegt zu haben ist eine große Leistung.\n\nIch bin beeindruckt, {name}. Werdet Ihr uns bei unserem Krieg gegen die Steintroggs helfen, damit wir den Steinvater retten können?", sourceObjectiveStatus = "unverified-source-field" }
quests[27936] = { id = 27936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lawine ins Rollen bringen", description = "Ihr müsst zurückgehen und Lavinius töten, um Therazanes Streitkräfte von einem Angriff auf Steinruh abzuhalten!", sourceObjective = "Tötet Lavinius.", completion = "Ihr habt etwas getan, zu dem nur wenige fähig gewesen wären. Lavinius besiegt zu haben ist eine große Leistung.\n\nIch bin beeindruckt, {name}. Werdet Ihr uns bei unserem Krieg gegen die Steintroggs helfen, damit wir den Steinvater retten können?", sourceObjectiveStatus = "unverified-source-field" }
quests[27937] = { id = 27937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held kehrt zurück", description = "Der Steinvater wartet auf Euch in Steinruh im Süden.\n\nPutzt Euch ein wenig heraus. Ihr habt Euch den Empfang eines Helden verdient!", sourceObjective = "Stellt Euch bei Steinvater Erzmantel in Steinruh in Tiefenheim vor.", completion = "Unser Held kehrt zurück!\n\nIhr habt mein Volk gerettet, {name}. Ihr habt Euch das, was Ihr sucht, redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27938] = { id = 27938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das mittlere Fragment", description = "Ich überreiche Euch hiermit den Schlüssel von Steinruh. Mit ihm dürft Ihr die Schatzkammer in meiner Heimstatt aufschließen und das mittlere Fragment der Weltensäule herausnehmen.\n\nAchtet gut auf das Fragment, {name}. Stellt sicher, dass Ihr es so schnell wie möglich zum Tempel der Erde in Tiefenheim zurückbringt!\n\nIhr sollt wissen, dass Ihr hier immer willkommen sein werdet.", sourceObjective = "Bringt das mittlere Fragment der Weltensäule in Euren Besitz.", progress = "Ihr seid zurückgekehrt. Habt Ihr das mittlere Fragment geborgen?", completion = "Das mittlere Fragment der Weltensäule!\n\nIch danke Euch, {name}. Ich kann mir nur schwer vorstellen, was Ihr durchmachen musstet, um das hier zu uns zurückzubringen. Ich werde dafür sorgen, dass es in der Mitte der Kammer aufgestellt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27939] = { id = 27939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wüstenfuchs", description = "In dieser Region muss einiges getan werden, {race}.\n\nWir haben beide eine brennende Leidenschaft für uralte Technologien, nicht wahr? Vielleicht können wir ja irgendwie zusammenarbeiten?\n\nLassen wir die Missverständnisse der Vergangenheit einfach ruhen, hmm?\n\nNun, da ist ein sehr scheues Tier Richtung Osten, das ich zu jagen versucht habe. Bringt mir diese Kreatur als Zeichen Eurer Aufrichtigkeit, hmm?\n\nDann weihe ich Euch vielleicht in meine Operation ein...", sourceObjective = "Schnottz will, dass Ihr ihm den Wüstenfuchs bringt.", progress = "Habt Ihr den Wüstenfuchs gefangen, {class}?", completion = "Ihr habt es geschafft!\n\nVielleicht kann ich Euch mit wichtigeren Aufgaben betrauen, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27940] = { id = 27940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Vögel", description = "Der Himmel über der Verdorrten Oase ist voll mit diesen hässlichen Geiern.\n\nSie sind wie mit Krankheiten befallene Ratten mit Flügeln. Sie dienen keinem bedeutsamen Zweck und bringen unsägliches Leid.\n\nSäubert den Himmel von dieser Plage und hinterlasst die Region besser, als Ihr sie vorgefunden habt.", sourceObjective = "Ihr sollt 8 kranke Geier töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27941] = { id = 27941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modeismus", description = "Wir haben einen unerschütterlichen Grundsatz in unseren Rängen, den wir sehr ernst nehmen.\n\nUnsere Truppen müssen zu jeder Zeit in offizielle Uniformen gekleidet sein. Das hilft bei der Organisation - Beschuss durch die eigenen Streitkräfte kommt nicht so oft vor und die Truppen sehen immer großartig aus!\n\nWir nennen das Modeismus.\n\nIn letzter Zeit gehen uns aber die Uniformen aus. Ich muss Euch darum bitten, sie von den Soldaten, die während ihrer Pflichterfüllung gefallen sind, zu bergen.\n\nIhr solltet reichlich arme Kerle östlich von hier bei den Ruinen von Ammon finden.", sourceObjective = "Bellok Leuchtklinge möchte, dass Ihr 10 Gardistenuniformen aufsammelt.", progress = "Konntet Ihr die Uniformen, die wir benötigen, beschaffen?", completion = "Das ist sehr gute Arbeit, {class}.\n\nIhr solltet schnell bei uns im Rang aufsteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27942] = { id = 27942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzendienst", description = "Ich habe etwas, um das Ihr Euch kümmern müsst, {race}.\n\nMein engster Vertrauter ist von einem uralten Fluch befallen. Es handelt sich um einen Fluch, der ihn ausgerechnet in einen Truthahn verwandelt hat!\n\nIch habe tagelang nach einem Heilmittel gesucht und bin nun endlich soweit, das Ritual durchzuführen.\n\nIch werde einige Götzen aus den nahegelegenen Ruinen benötigen. Ihr werdet sie mir umgehend beschaffen!\n\nWeggetreten!", sourceObjective = "Kommandant Schnottz möchte, dass Ihr 8 gut erhaltene Götzen einsammelt.", progress = "Habt Ihr die Götzen für mich, {race}?", completion = "Diese Stücke scheinen mir von ausreichender Qualität zu sein.\n\nDamit kommen wir dem Reinigungsritual einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27943] = { id = 27943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verärgerte Geister", description = "Doktor Wenkmann war einer meiner besten Forscher, bis ich von seinem Elend erlöst werden musste.\n\nEr hat mir aber eine seiner größten Errungenschaften hinterlassen. Gegen einen richtig abgestimmten, übernatürlichen Gegner wird diese Waffe die Essenz des Zieles abzapfen.\n\nDas ist von entscheidender Bedeutung bei dem Ritual, das ich durchführen werde.\n\nWo Ihr ins Spiel kommt, fragt Ihr? Ganz einfach. Ihr habt das Privileg, das Material zu sammeln.\n\nDie Waffe ist darauf kalibriert, bei den wütenden Schreckgespenstern im Tempel im Osten zu funktionieren.", sourceObjective = "Kommandant Schnottz möchte, dass Ihr die L.P.B.K. benutzt und 5 wütende spektrale Essenzen einsammelt.", progress = "Also, junger Mann? Wart Ihr erfolgreich?", completion = "Sehr gut!\n\nIhr habt Euch die Teilnahme an dem Ritual redlich verdient.\n\nIhr werdet einer der Ersten sein, die Gubbel wieder in seiner... ursprünglichen Form willkommen heißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27944] = { id = 27944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnen der Brut", description = "Seit Wochen versuchen wir schon, im Finsterwald Fuß zu fassen, aber dort wimmelt es nur so von Spinnen. Tut mir einen Gefallen und schaut, ob Ihr ihre Zahl soweit eindämmen könnt, dass wir einen Angriff starten können.\n\nDoch seid vorsichtig da draußen. Mir wurde berichtet, dass Anfang der Woche Hordetruppen dort gesichtet wurden.", sourceObjective = "Tötet 12 Dunkelwaldlauerer im Finsterwald. Der Finsterwald liegt direkt westlich von hier, jenseits der Brücke auf der mittleren Insel.", completion = "Den Spinnen habt Ihr es gezeigt, {name}. Wenn wir so weitermachen, ist der Wald im Handumdrehen unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[27945] = { id = 27945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmalerei", description = "Die Erde blutet, {class}. Sie reißen sie auf, wie man Fleisch aufreißen würde.\n\nDiese Kultisten finden großen Gefallen an ihrer Geheimniskrämerei, aber eben die Elementare, die sie für ihre Untaten benutzen, könnten sie verraten. Sucht die Obsidiansteinsklaven im Nordosten von hier in der zerstörten Erde, die wir den Schwarzen Riss nennen.\n\nZerschmettert ihre Körper und sucht für mich ein perfektes Herz aus schwarzem Diamant. Ich werde in sein Herz blicken. Und ich werde seine Seele entblößen.", sourceObjective = "Besorgt ein schwarzes Diamantherz.", progress = "Das Herz. Ein Steinherz in tiefstem Schwarz. Habt Ihr eins gefunden?", completion = "<Mallia nimmt ihre Augenklappe ab und hält den Diamanten vor ihre leere Augenhöhle.>\n\nWas haben wir, was haben wir - Bresche, Bresche Nummer Drei. Zwei Köpfe, einer ganz seinem Meister gegeben. Ich sehe die Zukunft. Ein vereinigter Hammer. Ein zerschmetterter Berg. Oh - OH!\n\n<Mallia lässt den Diamanten zu Boden fallen und bedeckt ihr Gesicht mit den Händen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27947] = { id = 27947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision des Zwielichts", description = "Cho'gall behält seine Handlanger durch mächtige magische Kugeln im Blick: \"Die Augen des Zwielichts\"\n\nIn Hyjal haben die Wächter von Hyjal es geschafft, eine zu finden und für ihre Zwecke zu verändern. Das müssen wir auch tun. Ich will eine dieser Kugeln und ich will sie benutzen, um hineinzuschauen und mitten in Cho'galls Versteck zu blicken.\n\nDurchsucht den Schwarzen Riss jenseits des Flusses im Nordosten und findet ein Auge des Zwielichts. Tut alles Notwendige, um es zu mir zurückzubringen!", sourceObjective = "Spürt ein Auge des Zwielichts in dem Schwarzen Riss auf.", completion = "<Das Auge liegt vor Euch und summt unheilvoll vor dunkler Energie.>\n\n<Ohne Warnung dreht sich die Kugel, als sehe sie Euch an. Ihr spürt die Anwesenheit des Bösen, als sei die Kugel lebendig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27948] = { id = 27948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine klebrige Angelegenheit", description = "Auf dieser Insel Vorräte zu sammeln, hat sich, gelinde gesagt, als schwierig erwiesen.\n\nGlücklicherweise haben wir ein gutes Angebot an Seide im Finsterwald, direkt westlich von hier, ausmachen können. Der unschöne Teil an der Sache ist, dass die Seide aus den Drüsen von Brutmutterspinnen gewonnen werden muss. Ich möchte, dass Ihr mir vier davon besorgt.\n\nDas sollte genügen, um die letzte Ladung Hemden fertigzustellen.", sourceObjective = "Sammelt 4 klebrige Seidendrüsen von Finsterwaldbrutmutterspinnen im Finsterwald. Der Finsterwald liegt westlich von hier, über die Brücke hinweg, auf der zentralen Insel.", progress = "Konntet Ihr die klebrigen Seidendrüsen bekommen?", completion = "Diese Drüsen sind genau richtig. Wir sind für Eure Hilfe dankbar, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27949] = { id = 27949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergessenen", description = "Viele Soldaten sind auf dieser Insel gestorben, {name}. Es ist nur rechtens, dass wir ihnen auf jede mögliche Art und Weise unseren Respekt erweisen.\n\nIch möchte, dass Ihr zum Vergessenen Hügel reist, der westlich von hier liegt, und die Seelen unserer geknechteten Waffenbrüder von hier fort geleitet. Seid bitte vorsichtig da draußen, uns haben Berichte über Machenschaften der Untoten in dem Bereich erreicht.", sourceObjective = "Schenkt den Geistern von 6 gequälten Seelen die Freiheit am Vergessenen Hügel. Die Seelen können kanalisiert werden, indem Ihr mit den Händen die Grabsteine berührt. Der Vergessene Hügel liegt direkt westlich von hier, vorbei am Finsterwald und der Rastlosen Front.", completion = "Mögen ihre Seelen in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27950] = { id = 27950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gubbel!", description = "Endlich! Die Zeit ist gekommen, meinen Gubbel von diesem furchtbaren Fluch zu befreien!\n\nPasst gut auf, {race}, und seid auf der Hut. Es darf keine Unterbrechungen während des Rituals geben.\n\nSagt mir Bescheid, wenn die Umgebung sicher ist!\n\nBewegung!", sourceObjective = "Schnottz möchte, dass Ihr ihn ansprecht, wenn Ihr bereit seid, dem Ritual beizuwohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27951] = { id = 27951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen alle Opfer bringen", description = "<Das Auge spricht mit Euch; seine 'Stimme' scheint aus allen Richtungen zugleich zu erschallen.>\n\nIhr wünscht einen Blick durch mich zu werfen, {race}? Meine Macht ist nur für einen bestimmten Preis zu haben. Diese Jünger des Zwielichts haben mich mit dem Blut der Wildhammerzwerge beehrt, aber ich verspüre immer noch Durst. Vielleicht könntet Ihr es besser machen.\n\nTötet meine alten Herren und meine Visionen gehören Euch. Ehrt mich, indem Ihr Schamanen der Schwärze tötet. Schließlich ist ein Blut so gut wie das andere.", sourceObjective = "Tötet 10 Schamanen der Schwärze.", completion = "<Das Auge schimmert dunkel, Farben wirbeln über seine düstere Oberfläche.>\n\nAh, die wohlschmeckende Spannung ausgelöschten Lebens. Könnt Ihr das fühlen, {class}? Gefällt es Euch so gut wie mir?\n\nNein, wie ich sehe, nicht. Ihr kämpft, um das Leben anderer zu beschützen. Schade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27952] = { id = 27952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Forscher", description = "Eine Gruppe der Forscherliga befindet sich in der Kammer im Nordwesten im Tempel.\n\nNun machen sie immer lauteres Geschrei über etwas, das der Schattenhammer anstellt.\n\n{name}, würdet Ihr ein Schatz sein und nachsehen, was sie brauchen?", sourceObjective = "Sprecht mit Entdeckerin Mowi im Tempel der Erde in Tiefenheim.", completion = "Donnerwetter! Es ist endlich jemand hier, um uns zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27953] = { id = 27953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Archäologische Akademie", description = "Eine Gruppe der Archäologischen Akademie befindet sich in der Kammer im Nordwesten im Tempel.\n\nNun machen sie immer lauteres Geschrei über etwas, das der Schattenhammer anstellt.\n\n{name}, würdet Ihr ein Schatz sein und nachsehen, was sie brauchen?", sourceObjective = "Sprecht mit Prüfer Rowe im Tempel der Erde in Tiefenheim.", completion = "Ah, es wurde auch langsam Zeit, dass jemand herkommt, um mit uns über Angelegenheiten größter Dringlichkeit zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27954] = { id = 27954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Auge des Betrachters", description = "Also gut, {race}. Ihr habt Euch meine Dienste mit Blut erkauft. Bringt mich zu Garona der Halborcin zurück.\n\nOh ja, ich weiß bereits, wo Ihr mich hinbringt. Garonas unablässige Suche nach Rache ist kein Geheimnis. Es wird ein Genuss sein, dabei zuzusehen, wie sie sich entfaltet.", sourceObjective = "Bringt das Auge des Zwielichts zu Garona der Halborcin in der Blutschlucht im Schattenhochland.", progress = "Hattet Ihr Glück im Schwarzen Riss?", completion = "Ihr habt eins gefunden? Ich habe überall gesucht. Gebt es her!\n\nEinige dieser Augen kann man mit Rätseln oder Versen für sich gewinnen. Bei anderen benötigt man Magie. Was hat dieses hier verlangt? Ah, das spielt keine Rolle. Es zählt nur, dass es uns gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[27955] = { id = 27955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe was, was Ihr nicht seht...", description = "Dieses furchtbare Ding lässt mir die Haare zu Berge stehen. Cho'gall benutzt diese Dinger, um seine Gehilfen zu überwachen - jetzt ist es an der Zeit, dieses gegen ihn zu verwenden.\n\nSchauen wir mal... hmm, es ist ganz milchig. Ich sehe nur Euch. Warum zeigt es mir Euch?\n\n<Garona stellt das Auge vor sich hin.>\n\nSchaut in das Auge und sagt mir, was Ihr seht. Werft einen Blick in Cho'galls Versteck! Was macht er? Ist er schwer bewacht? Sagt es mir!", sourceObjective = "Blickt für Garona in das Auge des Zwielichts.", completion = "Ihr seid ganz blass geworden, {class}. Was hat das Auge Euch gezeigt?\n\nIhr habt Cho'gall gesehen? Moment - Cho'gall hat Euch gesehen? Er beobachtet uns? Er beobachtet uns jetzt gerade!?\n\nVerflucht sei diese blöde, dunkle Magie! Ich werde mich selbst in Cho'galls Festung einschmuggeln müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27956] = { id = 27956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Aufgabe", description = "Lunk kam aus dem Ödland. Andere Oger Lunk gezwungen zu kämpfen.\n\nLunk hasst kämpfen. Lunk will lernen.\n\nLunk sieht Maschinen im Süden. Maschinen sind aus Zahnrädern.\n\nVielleicht, wenn Ihr nett fragt, Maschinen geben Euch ein paar Zahnräder? Dann kann Lunk vielleicht ein Zahnrad haben und über Maschinen lernen.", sourceObjective = "Beschafft 15 gehärtete Schwungräder von ausgehärteten Kriegsgolems.", progress = "Habt Ihr die Zahnräder? Wie habt Ihr sie bekommen?", completion = "Ihr habt... ...nicht die Maschinen GETÖTET, stimmt's?\n\n<Lunk sieht verstört aus.>\n\nStimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[27957] = { id = 27957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk nicht töten", sourceObjective = "Nein! Ihr seid wie Zwerg von Thoriumbruderschaft.\n\n\"Zwerg töten. Spinne töten. Maschine töten. Töten, töten, töten.\"\n\nLunk ist in Schlucht gekommen für Abenteuer, nicht für Mörderserie.\n\nLebt wohl, {race}. Ihr tötet zu viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27958] = { id = 27958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anständiges Gegengift", description = "Eigentlich schade, dass Lunk weg ist. Ich hatte gerade angefangen, Vergnügen an seiner Gesellschaft zu finden.\n\nAber na ja, zurück an die Arbeit!\n\nIch bin das Beste, was diese Expedition in Sachen Medizinversorgung hat, und meine Gegengiftvorräte gehen langsam zur Neige.\n\nDer Schlüssel zu vernünftigem Gegengift ist es, IMMER mit dem Gift selbst zu beginnen. Die Glasnetzspinnen in der Umgebung sollten einen guten Ausgangspunkt bieten. Wenn Ihr sie tötet, könnt Ihr wahrscheinlich etwas Gift aus den Säcken in ihren Kiefern gewinnen.", sourceObjective = "Beschafft Euch 14 Proben Glasnetzgift.", progress = "Sieh mal einer an, ihr arbeitet wirklich schnell! Ihr habt doch das Gift, oder?", completion = "Das... das ist weit mehr, als ich erwartet hatte. Das wird uns monatelang reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27959] = { id = 27959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Abenteuer: Spinnenreiter", description = "Lunk merkt, Ihr tötet gerne. Lasst Lunk Euch etwas anderes zeigen.\n\nLunk wollte schon immer auf Spinnenrücken reiten. Sieht spaßig aus. Spinnen bewegen sich aber zu schnell. Hauen immer ab.\n\nWir arbeiten zusammen. Ihr kämpft gegen Spinne, bis Spinne schwach und müde ist. Dann springt Lunk auf Spinnenrücken und reitet.\n\nVielleicht sammelt Lunk etwas Gift für Euch! Nicht müssen töten!", sourceObjective = "Schwächt 7 Glasnetzspinnen, damit Lunk sie reiten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27960] = { id = 27960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je weniger, desto besser", description = "Ich bin kein besonderer Kämpfer... Ich bin eher der Bergbauzwerg. Das gleiche gilt für Jack und Pris. Was Lunk betrifft... na ja, man könnte glauben, er wäre ein großer Kämpfer, aber eigentlich ist er der größte Feigling von uns allen.\n\nWas ich damit sagen will: Es ist gut, dass Ihr hierhergekommen seid.\n\nEs scheint wahrscheinlich, dass wir von der Thoriumbruderschaft schon bald gegen die anderen Dunkeleisenzwerge kämpfen müssen. Ich denke, dass wir zunächst einige ihrer besten ausschalten sollten, bevor der Krieg so richtig losgeht. Fangt mit den Geologen und den Wächtern im Süden an.", sourceObjective = "Tötet 10 Geologen der Dunkeleisenzwerge oder Wachmänner der Dunkeleisenzwerge.", completion = "Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27961] = { id = 27961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehl am Platz", description = "Die Schlucht ist ein unerbittlicher Ort. Hier laufen nicht besonders viele flauschige Wildtiere herum.\n\nWir haben versucht, etwas Jagdwild anzusiedeln, aber sie haben sich nicht besonders gut gehalten. Es gibt einfach nichts für sie zu fressen. Die Spinnen in der Nähe allerdings - die an sich schon gefährlich genug sind - schlagen sich den Bauch mit Hühnchenfleisch voll.\n\nWir werden die Spinnen niemals los, aber wir können die paar Hühner, die es noch gibt, retten. Damit werdet Ihr nicht nur die Bruderschaft versorgen, sondern ihnen auch einen qualvollen Tod durch den Biss einer Spinne ersparen.", sourceObjective = "Beschafft Euch 8 Aschehühnchen.", progress = "Diese armen Tiere.", completion = "Ihr müsst wirklich sehr geschickt sein, wenn Ihr so viele in so kurzer Zeit sammeln konntet.\n\nAusgezeichnete Arbeit, {name}. Ich werde dafür sorgen, dass sie nicht zu Schaden kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27962] = { id = 27962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor der Schlucht", description = "Margol die Wütende ist eine alte Donnerechse, die hier in der Gegend ab und zu auftaucht. Der Legende nach lebte sie schon in dieser Schlucht, bevor es diese Schlucht gab. Einer anderen Legende nach hat sie meinen Bruder Barnabas gefressen.\n\nEs interessiert mich nicht, wie alt sie ist oder welche Magie sie aus ihrer Nase verschießt. Ich will ihren Tod. Um Barnabas' Willen.\n\nIhr findet sie in den Klippen südlich von hier.", sourceObjective = "Erbeutet Margols gigantisches Horn.", progress = "Bringt mir das Horn, {name}.", completion = "Ja, das war wirklich Margols Horn. Kann man nich' dran rütteln.\n\nBarnabas war wie ich ein Gräber. Im Kampf gegen diese Bestie war er chancenlos. Ich bin froh, dass Ihr für Gerechtigkeit gesorgt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27963] = { id = 27963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Meister... nur wer?", description = "Ihr seid gerade zur rechten Zeit gekommen.\n\nDarum geht's: Die Dunkeleisenzwerge in der Schlucht verhalten sich merkwürdig und die Thoriumbruderschaft hat vor, herauszufinden, warum. Aufseher Schlickfaust hat nicht viel für Überraschungen übrig.\n\nWir vermuten, dass sie den Befehlen von irgendeinem neuen Anführer folgen. Ich habe Grund zu der Annahme, dass Gravius Rußschlack, direkt südlich von hier, weiß, um wen es sich dabei handelt.\n\nSelbst hier in der Sengenden Schlucht, hat sich die Kunde Eurer Heldentaten herumgesprochen, {name}. Rußschlack sollte Euch keine Probleme bereiten.", sourceObjective = "Beschafft Euch die Dunkeleisennotiz von Gravius Rußschlack bei Rußschlacks Arbeitsstätte.", progress = "Gibt es Neuigkeiten?", completion = "Mal sehen... Aufseher Maltorius... ihn und seine Arbeit kennen wir schon.\n\nWas ist das denn? Der \"Erzherzog\"? Das klingt ja vielversprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[27964] = { id = 27964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsboss Krawallschnäuzer", description = "Rußschlack war in der Hierarchie nicht so weit oben, wie ich dachte. Wir müssen seinen Vorgesetzten aus dem Weg schaffen und herausfinden, was er weiß.\n\nSein Name ist Ausgrabungsboss Krawallschnäuzer und er leitet die Ausgrabungen der Dunkeleisenzwerge im Kessel etwas nordwestlich von hier. Seine Ausgräber und Fußsoldaten patrouillieren auf der östlichen Seite des Kessels und graben sich Tag und Nacht weiter nach unten.\n\nEr zeigt sich nicht sehr oft in der Öffentlichkeit, aber wenn Ihr genug seiner Männer tötet, wird er gezwungen sein, herauszukommen und sich mit Euch zu befassen.", sourceObjective = "Tötet Ausgräber und Fußsoldaten der Dunkeleisenzwerge im Kessel, bis Ausgrabungsboss Krawallschnäuzer erscheint. Dann tötet den Ausgrabungsboss Krawallschnäuzer und bringt seine Dunkelglut an Euch.", progress = "Wenn Krawallschnäuzer das Gewünschte nicht bei sich trägt, bin ich nicht sicher, was wir als nächstes tun werden.", completion = "Eine... eine Glut? Was ist das für ein Ding?", sourceObjectiveStatus = "unverified-source-field" }
quests[27965] = { id = 27965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thoriumspitze: Der Sitz der Bruderschaft", description = "Habt... habt Ihr das gesehen? Das ist das Puzzlestück, das uns gefehlt hat! Wir müssen diese Informationen zu jemandem an der Thoriumspitze bringen.\n\nEs ist bekannt, dass die Dunkeleisenzwerge in der Vergangenheit gemeinsame Sache mit dem Feuerfürsten gemacht haben, aber noch nie zuvor haben sie sich so weit in die Sengende Schucht hinaus gewagt.\n\nDie Thoriumspitze liegt westlich und nördlich von hier. Ihr findet sie versteckt in den Klippen, die die Pyroxebenen überragen. Bringt diese Informationen schnurstracks zu Aufseher Schlickfaust.", sourceObjective = "Meldet Euch bei Aufseher Schlickfaust auf der Thoriumspitze in der Sengenden Schlucht.", completion = "Kenne ich Euch, {race}?\n\n\n\nDas klingt nach einem weiteren Diener von Ragnaros. So etwas höre ich überhaupt nicht gern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27966] = { id = 27966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Überreste", description = "Der Vergessene Hügel ist von Zombies und Ghulen überrannt worden, seit dem Tag, an dem wir diese erbärmliche Insel für uns beanspruchten. Wir haben versucht, sie loszuwerden, aber es scheint, als kämen sie immer wieder.\n\nEiner unserer Leutnants hat vorgeschlagen, die Ghulknochen wegzuräumen, nachdem wir sie getötet haben, in der Hoffnung, dass sie nicht über Nacht wiederauferstehen. Glaubt Ihr, dass Ihr uns hierbei helfen könntet?", sourceObjective = "Ihr müsst 9 verfluchte Oberschenkelknochen von den Ghulen, die auf dem Vergessenen Hügel hausen, einsammeln. Der Vergessene Hügel befindet sich auf der westlichen Seite der Insel, direkt vorbei an der Vergessenen Front.", progress = "Konntet Ihr die Oberschenkelknochen sammeln? Mir ist lieber, Ihr versucht es, als dass ich es tun müsste.", completion = "Ich hätte nicht gedacht, dass Ihr es schaffen könnt, {name}. Ihr steckt ja voller Überraschungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27967] = { id = 27967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberleutnant Connor", description = "Als ich das erste Mal von Oberleutnant Connor hörte, war ich ein junger Rekrut im Verlies von Sturmwind. Niemand von uns hätte je gedacht, dass er mal hier auf Tol Barad enden würde. Traurigerweise wandert er noch immer über diese elenden Inseln und richtet verheerenden Schaden an der Moral unserer Truppen an.\n\nIch möchte, dass Ihr seinem Elend ein Ende macht... und damit unserem.", sourceObjective = "Findet und tötet Oberleutnant Connor auf dem Vergessenen Hügel. Ihr findet den Vergessenen Hügel auf der westlichen Seite der Insel.", completion = "He, Ihr habt es lebendig hierher zurück geschafft! Ich kann nicht behaupten, dass Ihr der Erste wart, der dieses Unterfangen versucht hat, aber Ihr seid gewiss der Erste, der in einem Stück zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27968] = { id = 27968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut des Rudels", description = "Ah, der süße Geruch von Sieg! Meine Männer sollten Godfrey in eben diesem Augenblick in Stücke reißen. Begebt Euch zu ihm und holt Euch Euren Teil der Beute - Ihr habt es Euch verdient!\n\nMan hätte gedacht, dass es schwieriger würde, ihn zu vernichten...", sourceObjective = "Tötet Lord Godfrey.", completion = "Wir haben es geschafft, {name}! Es hat uns viel gekostet, aber der Sieg ist unser.\n\nDiese Burg könnte mir und meinem Rudel als Heimstatt dienen, auch wenn wir normalerweise einen etwas natürlicheren Lebensraum bevorzugen.\n\nVielleicht ist es das Beste, sie zur Erinnerung an Godfreys Verrat und die Blutfangkrieger, die hier gefallen sind, zu belassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27969] = { id = 27969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht Euch nützlich", description = "Wir werden Gubbel sehr vermissen, aber die Mission darf nicht darunter leiden.\n\nVielleicht gibt es da etwas, das Ihr tun könnt, um Euch zu rehabilitieren.\n\nNehmt eine der Uniformen, die Ihr gefunden habt. Wenn Ihr sie tragt, werden meine Arbeiter nicht so... aggressiv reagieren.\n\nIn letzter Zeit war ihre Moral nicht gerade hoch. Einige der Arbeiter weigern sich gar, ihren Pflichten nachzukommen.\n\nOh, diese Dreistigkeit!\n\nFindet diese faulen Schwachköpfe und überzeugt sie davon, an die Arbeit zu gehen... oder sonst!", sourceObjective = "Kommandant Schnottz möchte, dass Ihr 6 faulenzende Arbeiter davon überzeugt, wieder an die Arbeit zu gehen.", completion = "Gut gemacht, {class}.\n\nVielleicht besteht ja noch Hoffnung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27970] = { id = 27970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän P. Harris", description = "Das Kap der Verlorenen Hoffnung steckt uns hier auf Tol Barad seit Wochen wie ein Stachel im Fleisch. Die Hälfte unserer Versorgungsschiffe endet auf den Felsen dort unten.\n\nHinzu kommt, dass es von einer Bande untoter Matrosen überrannt wurde. Wir haben versucht, sie zu dezimieren, aber sie kommen immer wieder zurück. Unsere letzte Hoffnung ist es, den Kapitän zu töten, der ihnen ihre Befehle gibt. Ihr solltet ihn auf einem Schiff nahe des Ufers finden.\n\nOh, und ich hoffe, Ihr habt keine große Angst vor Haien.", sourceObjective = "Ihr habt den Auftrag, Kapitän P. Harris am Kap der Verlorenen Hoffnung zu töten. Das Kap der Verlorenen Hoffnung liegt gleich nordwestlich von hier, die Küste entlang. Haltet einfach Ausschau nach den Schiffswracks.", completion = "Ihr habt es geschafft! Vielleicht schaffen es jetzt endlich ein paar Schiffe in den Hafen! Danke sehr, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27971] = { id = 27971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stört ihre vorletzte Ruhe", description = "Seit einiger Zeit haben wir Probleme mit den Untoten unten am Kap der Verlorenen Hoffnung. Bei jedem neuen Schiffbruch schließen sich ihnen neue Untote an.\n\nKönnt Ihr uns einen Gefallen tun und die Mannschaft dort etwas ausdünnen? Ich weiß, Ihr könnt sie nicht alle töten, aber jeder Beitrag ist für uns von Nutzen.\n\nHaltet ein Auge auf die Horde, in letzter Zeit wird gemeldet, dass ihre Kämpfer am Strand im Hinterhalt liegen.", sourceObjective = "Lagerkommandant Brack hat Euch gebeten, am Kap der Verlorenen Hoffnung 8 schiffbrüchige Seemänner zu töten. Das Kap befindet sich nordwestlich von hier, am Strand.", completion = "Gute Arbeit mit den Untoten da oben, {name}. Wir wissen Eure Hilfe wirklich sehr zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27972] = { id = 27972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkung der Moral", description = "Die Stimmung ist in letzter Zeit schlecht, {name}. Wir tun, was wir können, um die Truppen bei Laune zu halten, aber leider geht uns der wichtigste Stimmungsaufheller aus... Rum.\n\nUnsere Infanterie im Osten berichtet, dass in den Rümpfen der Schiffswracks am Kap der Verlorenen Hoffnung jede Menge Südmeerrum liegt. Würdet Ihr dort hinreisen und dem nachgehen?\n\nBringt so viel Rum mit, wie Ihr finden könnt.", sourceObjective = "Ihr habt den Auftrag erhalten, 6 Fässer mit Südmeerrum aus den Schiffswracks am Kap der Verlorenen Hoffnung zu beschaffen. Das Kap liegt nördlich von hier, entlang der Küste.", progress = "Konntet Ihr den Rum bergen? Ich würde es ja versuchen, aber ich habe Angst vor Wasser. Und vor diesem verrückten Hai.", completion = "Der Rum wird uns sehr helfen, {name}. Sie werden sich morgen früh zwar nicht gut fühlen, aber wenigstens schlafen sie glücklich ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27973] = { id = 27973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Splitter", description = "Wart Ihr schon in Wellsons Werft, {name}? Am besten haltet Ihr Euch davon fern, es sei denn, Ihr habt einen guten Grund, dort hinzugehen. Und unglücklicherweise werde ich Euch einen guten Grund geben.\n\nWisst Ihr, wir haben hier nur wenige Vorräte, seit wir die Insel wieder eingenommen haben. Auf der von Geistern heimgesuchten Werft ist viel Holz, aber alle, die ich bisher geschickt habe, um es zu holen, kamen nicht zurück.\n\nKönnt Ihr uns helfen?", sourceObjective = "Bringt 15 Stücke Schiffsbauholz von Wellsons Werft zu Unteroffizier Grau. Das Holz wird von den Geistern in der Werft bewacht oder liegt frei zugänglich in der Werft verteilt. Die Werft ist an der Küste nordwestlich von hier.", progress = "Haben die Geister Euch Angst eingejagt?", completion = "Ich habe nicht damit gerechnet, dass Ihr diese Aufgabe erfüllen könnt, {name}. Ihr steckt voller Überraschungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27974] = { id = 27974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist unser Land", description = "Dachtet Ihr, dass eine Handvoll Worgengezücht mich aufhalten kann? Ha!\n\nZu Lebzeiten war Burg Schattenfang Teil des Königreichs Lordaeron, also ist es nur gerecht, dass es im Tode den Verlassenen gehört. Godfrey und seine Komplizen sind bestenfalls kleine Hindernisse und natürlich freuen wir uns, sie als Strafe für den Verrat an der Dunklen Fürstin beseitigen zu können.\n\nAshbury hat sich bei der Vorderseite der Burg niedergelassen und ist einem Angriff gegenüber völlig ungeschützt. Bereitet uns einen schönen Anfang, ja?", sourceObjective = "Tötet Baron Ashbury.", completion = "Ah, sehr gut! Sie haben sich mächtige Verbündete beschafft, aber offensichtlich ist das nichts, womit ein herausragender {class} der Bansheekönigin nicht fertig würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27975] = { id = 27975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorarbeiter Wellson", description = "Vorarbeiter Wellson ist uns schon seit unserer Ankunft ein Dorn im Auge. In seiner Werft lagert er haufenweise Materialien, die für uns von extrem hohem Nutzen sein könnten... wenn wir nur an sie heran kämen.\n\nEr lässt sie von seinen Dienern streng bewachen und macht es uns schwer, auch nur einen Fuß in die Werft zu setzen. Ihr müsst Wellson ein für alle Mal für mich erledigen. Aber seid vorsichtig, {name}. Uns wurde berichtet, dass die dreckige Horde überall in der Gegend ihr Unwesen treibt.", sourceObjective = "Tötet Vorarbeiter Wellson in Wellsons Werft. Die Werft befindet sich nordwestlich von hier an der Westküste.", completion = "Ausgezeichnete Arbeit, {name}. Ich werde Eure Taten sofort unserem Oberkommando melden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27976] = { id = 27976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt seien diese fetten Finger", description = "Leider kann ich wegen dieses Fettfingerproblems meine Schläge nicht mehr so austeilen wie früher. Durch das Klima hier draußen und den fehlenden Luftdruck dehnen sich meine Finger aus. Die sehen aus wie riesige Thelsamarblutwürste, oder?\n\nIhr werdet meine Befehle und all so'n Zeug ausführen müssen.\n\nPunkt Eins auf der Liste: Die schweren Kriegsgolems in der Schlucht windelweich prügeln. Legt los.", sourceObjective = "Tötet 12 schwere Kriegsgolems.", completion = "Ihr seid ein wirklich guter Junge. Ich hab ein kleines Geschenk für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27977] = { id = 27977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärungsausstattung", description = "Früher hatten wir hier mal mehr Zeug. Ich glaube, es gab hier mal irgendwo ein Handfernrohr, zusammen mit einer Schmiedwindform.\n\nIch bin mir ziemlich sicher, dass sie von Dunkeleisenzwergen gestohlen wurden. Ja, ich weiß, dass ich ein Dunkeleisenzwerg bin! Ich spreche von den bösen Dunkeleisenzwergen, die in der Schlucht leben.\n\nAm besten versucht Ihr es mal bei den Dampfschmieden, die südlich von hier arbeiten. Bei ihnen ist es am Wahrscheinlichsten, dass sie solche Werkzeuge benutzen.", sourceObjective = "Findet die Schmiedewindform und das Ausguckhandfernrohr und bringt sie zurück.", progress = "Wenn Ihr wegen Eurer Belohnung hier seid, dann müsst Ihr mir erst die gestohlenen Gegenstände aushändigen.", completion = "Fantastische Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[27978] = { id = 27978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterjäger", description = "Seht Ihr den Hügel, direkt außerhalb unseres Basislagers? Das ist Largos Warte und es ist nicht der schönste Ort, um daneben ein Lager zu errichten. Wir mussten uns mit Geistern und Schreckgespenstern herumschlagen, seit wir unser Basislager hier aufgeschlagen haben.\n\nKönnt Ihr Euch dorthin begeben und sie wissen lassen, dass wir nicht vorhaben, uns sobald von hier wegzubewegen? Ein paar Abschüsse in ihren Reihen sollten sie zur Räson bringen.\n\nVielen Dank für Eure Hilfe hierbei, {name}.", sourceObjective = "Tötet 14 beliebige Geister bei Largos Warte, direkt nordöstlich des Basislagers.", completion = "Hervorragend, {name}! So bald sollten wir von den Geistern nichts mehr hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[27979] = { id = 27979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Dienste", description = "Ich habe noch eine Aufgabe für Euch. Diese kommt direkt vom Aufseher. Offenbar war er ziemlich aufgewühlt, als er von dem \"Erzherzog\" hörte, den Ihr entdeckt habt.\n\nEr hat uns gebeten, drei Zwielichtpriester, die drüben am Feuerwachtgrat im Westen arbeiten, aufzuspüren. Sie heißen Kiyuubi, Letherio und Fiester und jeder von ihnen trägt einen speziellen Stein bei sich. Setzt die drei zusammen und bringt sie herher.\n\nHört zu - wenn der Aufseher Befehle gibt, stellt man keine Fragen. Man tut es einfach.", sourceObjective = "Beschafft Euch die Steinkügelchen von Kiyuubi, Letherio und Fiester. Setzt sie zu einem Zwielichttripetrizin zusammen.", progress = "Habt Ihr das Ding?", completion = "<Hansel wiegt den Stein in seinen Händen.>\n\nDieses Ding ist seltsam, {name}. Ich weiß nicht, was ich davon halten soll. Eins ist sicher - es ist nicht natürlichen Ursprungs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27980] = { id = 27980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spinnen müssen weg", description = "Mit Spinnen von normaler Größe kann ich umgehen.\n\nBei riesigen Glasnetzspinnen fühle ich mich unbehaglich, aber die sind weit genug weg, sodass ich mir nicht allzu viele Sorgen machen muss.\n\nAber Lavaspinnen? <Lolo erschauert.> Lavaspinnen sind GRUSELIG. Das sind gewaltige Spinnen. Die in LAVA leben.\n\nIch habe gerade meinen Lohn für die letzte Arbeitswoche bekommen und werde Euch gut bezahlen, wenn Ihr diese Dinger tötet. Ihr findet sie überall in der Sengenden Schlucht.", sourceObjective = "Erschlagt 9 Lavaspinnen in der Sengenden Schlucht.", completion = "Ihr konntet sicher nicht alle Spinnen in der Schlucht töten, aber Ihr habt definitiv eine Lücke in ihre Reihen geschlagen.\n\nGut, hier ist, was ich Euch versprochen habe. Aber gebt nicht alles auf einmal aus. Außer Ihr tut es auf der Thoriumspitze.", sourceObjectiveStatus = "unverified-source-field" }
quests[27981] = { id = 27981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitze, die nie vergeht", description = "Wir schmieden, wir schmelzen, wir rösten jegliches Spinnenfleisch, das wir finden können. Buschhühner, wenn wir Glück haben. Der Punkt ist, dass wir für all diese Arbeiten unglaublich viel Feuer benötigen.\n\nOh, wenn wir doch bloß in einer Aschewüste leben würden, in der einem an jeder Ecke der Bart versengt wird.\n\nNatürlich stammt das beste Feuer von den Elementaren. Man findet sie überall in der Sengenden Schlucht, hauptsächlich aber in der Nähe von Lava. Hier, nehmt diese Flaschen und benutzt sie bei den Elementaren.\n\nOh, habe ich schon erwähnt, dass die Elementare am Leben sein müssen, wenn Ihr die Proben einsammelt?", sourceObjective = "Besorgt 10 gefüllte Ofenflaschen. Ihr müsst die Ofenflaschen bei lebendigen Elementaren in der Sengenden Schlucht benutzen.", progress = "Schlickfaust sagt, wir sollen bald Feuerbomben für ihn bauen. Umso dringender benötigen wir diese Flaschen.", completion = "Auaaaaaaaaa! Ihr dürft dieses Zeug doch nicht einfach in die offene Hand eines Zwergs legen. Das Zeug ist doch glühend heiß!\n\nJetzt werden meine Hände noch mehr anschwellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27982] = { id = 27982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthalsbänder", description = "Habt Ihr diese lächerlichen Ketten gesehen, die die Kultisten des Schattenhammers tragen? Die Edelsteine auf den Dingern sind größer als Hansels Faust!\n\nNur ein paar von diesen spiegeleigroßen Juwelen und Burninate da drüben könnte dieses Schmiedegeschäft auf die nächste Ebene bringen. Bringt ihm diese Halsbänder und es soll Euer Schaden nicht sein.", sourceObjective = "Beschafft 20 Zwielichthalsbänder", progress = "Ein rubinbesetzer Hammer... Klingt doch nett, oder?", completion = "Hmm... Aus der Ferne sahen diese Edelsteine irgendwie... funkelnder aus. Aus der Nähe sind sie doch ganz schön stumpf.\n\nAch, was soll's! Ein wenig Spucke und Politur sollte die Sache schon richten. Und falls nicht, kann ich sie immer noch nutzen, um meine Entzauberkünste zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27983] = { id = 27983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Abenteuer: Launische kleine Zwerge", description = "Was Ihr machen? Warum Ihr töten?\n\nIhr brauchen Sachen von Zwergen? Ah, Lunk verstehen. Lunk haben besseren Weg.\n\nHört zu: Ihr bekämpfen Zwerg, aber nicht töten! Nur bekämpfen, bis Zwerg müde sein. Dann Lunk wird helfen, wenn Zwerg einschlafen. Zwerge wahrscheinlich nur griesgrämig, weil sie nicht schlafen.\n\nKommt, vertraut Lunk.", sourceObjective = "Schwächt 7 Dampfschmiede der Dunkeleisenzwerge, sodass Lunk ihnen helfen kann, einzuschlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27984] = { id = 27984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distelmonds Geschichte", description = "Werdet Ihr mir helfen, <Sterblicher/Sterbliche>? Hört meine Geschichte.", sourceObjective = "Lauscht Zamaels Erzählung.", completion = "Ich habe mich in mein Schicksal hier in diesem Käfig ergeben, aber das Gebet muss gefunden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27985] = { id = 27985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Ich denke, dass sie sie in einer ihrer widerwärtigen Kisten aufbewahren, in der Nähe des Eingangs zu ihrer Höhle, am Boden des Grats.\n\nWenn es Euch gelingt, mein Gebet zurückzubekommen, so bringt es nicht zu mir zurück. Stattdessen nehmt Euch bitte die Zeit, es zu lesen.\n\nVergebung ist vielleicht zu viel verlangt, wenn man die Sünden bedenkt, die ich begang. Es wird mich aber nicht davon abhalten, weiterhin zu hoffen.Ihr erlernt:", sourceObjective = "Findet und lest das Gebet an Elune.", sourceObjectiveStatus = "unverified-source-field" }
quests[27986] = { id = 27986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Hallen des Bergfürsten", description = "Die Thoriumbruderschaft verfügt über keinerlei Miliz - nur ein paar Wachen und ich, und das war's. Wenn wir einen erfolgreichen Schlag gegen die Dunkeleisenzwerge in der Schlacht führen wollen, dann brauchen wir Hilfe.\n\nBergfürst Rendan befindet sich oben im Turm, über die Schlucht hinweg, von uns aus im Süden. Er verkehrt nicht mit dem Gesindel des Schattenhammers oder mit Feuerelementaren, aber er hat sich auch nicht der Bruderschaft angeschlossen. Vielleicht ist es an der Zeit, dass wir ihm einen Besuch abstatten. Mit seiner Hilfe könnten wir eine Chance haben.", sourceObjective = "Sprecht mit Bergfürst Rendan auf dem Eisengipfel in der Sengenden Schlucht.", completion = "Und wer seid Ihr wohl?\n\nAh, ein Abgesandter der Thoriumbruderschaft. Ihr benötigt meine Unterstützung? Nun gut, ich könnt' mich bereit erklären, Euch zu helfen...\n\n...wenn die Bezahlung stimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27987] = { id = 27987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenkugel!", description = "Seit wir unser Lager hier errichtet haben, stehlen Largo und seine Handlanger unsere Vorräte. Das ist mehr als frustrierend.\n\nUns wurde berichtet, dass er oben auf seiner Warte Kanonenkugeln in den Türmen lagert, die über das Wasser hinausblicken. Würdet Ihr Euch dorthin aufmachen und versuchen, einige davon für uns zurückzuholen?\n\n{name}, vergesst nicht, auch vor der Horde auf der Hut zu sein.", sourceObjective = "Ihr müsst 4 Stapel Kanonenkugeln aus Largos Warte für Unteroffizier Grau besorgen. Ihr findet Largos Warte nordöstlich des Basislagers.", progress = "Habt Ihr die Kanonenkugeln gefunden?", completion = "Eine sehr gelungene Bergung, {name}. Diese Kanonenkugeln sollten eine Weile reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27988] = { id = 27988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuche... Überall Seuche!", description = "Das Beste an dieser Seuche ist: selbst wenn der sichtbare Teil verblasst, so ist der verbleibende Überrest doch immer noch recht mächtig! Allerdings haben wir immer noch eine riesige Fläche abzudecken, bevor wir fertig sind, auf der sich jede Menge von Godfreys Verteidigungen befinden.\n\nEs scheint, als würden die Diener, die Baron Silberlein und Kommandant Grüntal im Leben umsorgten, dies auch noch im Tode tun, und dass Godfrey sie benutzt, um uns zu behindern. Zeigt ihnen den eisernen Willen der Verlassenen!", sourceObjective = "Tötet Baron Silberlein und Kommandant Grüntal.", progress = "Ein paar körperlose Geister werden es doch wohl nicht mit Euch aufnehmen können, oder?", completion = "Cromush besitzt sowohl einen dicken Schädel, als auch ein Spatzenhirn und das werden wir uns zunutze machen. Bis irgendjemand herausfindet, wie stark die Seuche in Wahrheit ist, wird es viel zu spät sein.\n\nDanke, dass Ihr während seiner Tirade an Euch gehalten habt. Ich verspreche Euch, dass Ihr das nicht bereuen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27989] = { id = 27989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo verlangt Honig", description = "Ruumbo hat Hunger!\n\nDie Totenwaldidioten haben der Holzschlundfeste den ganzen Honig gestohlen! Wir haben es... äh... Ruumbo hat es gesehen! Und jetzt muss Ruumbo den Honig bekommen!\n\nNehmt diesen... diesen Stock! Ja, diesen Stock! Nehmt den Stock und benutzt ihn, um den Honig aus ihren Bienenstöcken im Lager der Totenwaldfelle zu klauen.\n\nRuumbo muss so viel Honig wie möglich haben. Das ist wichtig.", sourceObjective = "Sammelt 10 Honigtropfen der Totenwaldfelle aus den Bienenstöcken im Lager der Totenwaldfelle, indem Ihr Ruumbos Honigstock benutzt.", progress = "Ruumbo kann riechen, ob Ihr Honig dabei habt, oder nicht!", completion = "Honig! Köstlicher Honig!\n\nGut gemacht, hässliches Geschöpf! Ihr könnt den Honig genau... dort hinstellen. Nein, weiter links. Ja, da. Lasst ihn da stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27990] = { id = 27990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefechtszone", description = "Es scheint, als gäbe es da noch eine Möglichkeit, Euch zu rehabilitieren, {race}.\n\nDieser kleine Zwischenfall hat mich einige Panzerkanoniere gekostet.\n\nMeint Ihr, Ihr habt es drauf, einen von ihnen zu ersetzen?\n\nMeine Panzer befinden sich gleich westlich des Lagers. Geht da raus und bereitet diesem Unfug ein Ende!", sourceObjective = "Kommandant Schnottz möchte, dass Ihr einen der Belagerungspanzer bemannt und ihn benutzt, um 7 altersschwache Behüter zu besiegen. Meldet Euch danach wieder bei ihm.", progress = "Und?\n\nIst unser kleines Problem behoben worden?", completion = "Autsch!\n\nWäre ich nur eine Handbreit größer, wäre ich jetzt tot!", sourceObjectiveStatus = "unverified-source-field" }
quests[27991] = { id = 27991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Warte", description = "Es gibt nur eine Möglichkeit, wie wir Largos Warte zurückzuerobern können.\n\nIch glaube, Ihr wisst, was Ihr tun müsst, {name}. Largo ist in letzter Zeit ziemlich paranoid. Ihr solltet ihn also auf der Turmspitze finden, wo er nach seiner eingebildeten Flotte Ausschau hält.", sourceObjective = "Unteroffizier Grau hat Euch beauftragt, Kommandant Largo in Largos Warte zu töten. Die Warte befindet sich direkt nordöstlich des Basislagers.", completion = "Ha! Endlich haben wir Largo erledigt! Sehr gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27992] = { id = 27992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinischer Magnetismus", description = "Nützliche Maschinenteile hier draußen auf der Insel zu bekommen, war sehr schwierig, {name}. Wir haben versucht, die kaputten Belagerungsmaschinen hier im Camp zu reparieren, doch uns sind brauchbare Ersatzteile ausgegangen.\n\nUnser Zweites Regiment berichtete uns von schrottreifen Belagerungsmaschinen auf einem Schlachtfeld im Westen. Vielleicht könnten wir dort Ersatzteile finden?\n\nIhr werdet Probleme haben, überhaupt irgendetwas auf dem alten Schlachtfeld zu finden. Nehmt deshalb diesen magnetisierten Schrottsammler und macht ihn Euch zunutze.", sourceObjective = "Ihr habt die Aufgabe erhalten, 7 Stücke Belagerungsmaschinenschrott zu bergen. Benutzt den magnetisierten Schrottsammler an der Rastlosen Front, um die Schrottteile zu finden. Die Rastlose Front befindet sich im Westen hinter der zweiten Brücke.", progress = "Hat diese Magnetvorrichtung wirklich funktioniert?", completion = "Diese Ersatzteile werden uns wirklich weiterhelfen, {name}! Wer hätte gedacht, dass man unter all diesem nutzlosen Schrott noch so nützliche Dinge finden kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[27993] = { id = 27993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt's ihnen!", description = "Wir haben echt Glück gehabt, dass wir entkommen sind, {class}. Ich glaub ich würde mich nicht sehr wohl in meiner Haut fühlen, wenn wir's den Wegelagerern nicht gezeigt hätten.\n\nWie wär's, wenn Ihr zurück zum Grab des Khartut geht und den kleinen Nervensägen was auf die Nase gebt?\n\nDas Grab ist im Nordosten, direkt hinter dem Eingang zu Uldum, wenn ich mich recht entsinne.\n\nWarum guckt Ihr so dumm? Ich bin nicht in der Verfassung, das selbst zu machen!", sourceObjective = "Mack möchte, dass Ihr das Grab des Khartut untersucht.", completion = "Schön, Euch zu sehen.\n\nNoch schöner wäre es allerdings gewesen, wenn Ihr hier gewesen wärt und mir geholfen hättet, diese kleinen Wilden in den Griff zu bekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27994] = { id = 27994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo verlangt Gerechtigkeit", description = "Ihr! Wanderer! Verneigt Euch vor der Macht Ruumbos, dem großen Gott des Stamms der Holzschlundfeste!\n\nVernehmt meinen Willen! Der bösartige Stamm der Totenwaldfelle lebt in dem Lager hinter mir! Sie sind riesige Blödmänner!\n\nIch meine... sie... sie besudeln meinen Namen mit ihren niederträchtigen Missetaten! Sie verfolgen meinen geliebten Stamm der Holzschlundfeste und verletzen sie!\n\nIch verlange, dass Ihr meine Gerechtigkeit walten lasst! Vernichtet die Totenwaldfelle und ich werde Euch meine... meine Gunst gewähren! Ja! Die Gunst von RUUMBO!", sourceObjective = "Tötet 15 Furbolgs der Totenwaldfelle jedweder Art.", completion = "Es hat geklappt!\n\nÄhm, ich meine natürlich, JA! Ruumbos Wille wurde vollstreckt! Das habt Ihr gut gemacht, Geschöpf! Ihr dürft diese glänzenden Münzen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27995] = { id = 27995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzt für Ruumbo!", description = "Ihr habt gute Arbeit geleistet, {race}! Ruumbo ist erfreut über Eure Tapferkeit und den leckeren Honig, den Ihr Ruumbo gegeben habt.\n\nUnd jetzt müsst Ihr... müsst Ihr tanzen! Ja!\n\nTanzt für Ruumbo! Tanzt!", sourceObjective = "Tanzt einen albernen Tanz für Ruumbo.", completion = "Diese zwei Gören... ich hätte es wissen sollen! Sie waren schlau genug, immer dann leise zu sein, wenn ich nach dem Totem gesehen habe.\n\nIch werde sie ausfindig machen und bei den Ohren zur Holzschlundfeste zurückzerren! Danke, dass Ihr Euch der Sache angenommen habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[27996] = { id = 27996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle sind was für die Lebenden", description = "Wie nicht anders erwartet, werden wir natürlich nicht auf Cromush hören, was die Seuche betrifft. Nichtsdestotrotz wird uns seine brachiale Kraft nützlich sein, wenn es darum geht, auf dem Weg zu Godfrey einen Durchgang für meine Männer durch die Gegnerreihen zu erzwingen. Der mächtigste in ihren Rängen dürfte seine rechte Hand, Lord Walden, sein.\n\nIch treffe Euch in Waldens Kammer, nachdem Ihr mit ihm fertig seid. Dann endlich werden wir Burg Schattenfang für die Verlassenen einnehmen!", sourceObjective = "Tötet Lord Walden.", completion = "Die Stunde hat geschlagen! Godfrey wird fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27997] = { id = 27997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadefeuerverderbnis", description = "Das Säubern dieses Waldes hat sich als zermürbender Prozess herausgestellt. Für jeden errungenen Erfolg, hat sich eine neue Herausforderung aufgetan.\n\nDie Jadefeuersatyrn sind ein fortwährendes Ärgernis. Sie streben danach, den Wald zu verderben, während wir uns bemühen, ihn zu reinigen. Nun haben wir Schritte eingeleitet, um sie im Teufelswald vollständig auszurotten.\n\nReist ins Jadefeuertal im Westen und säubert den Wald von ihrer Präsenz. Ihr findet den Eingang direkt nördlich der Mauern zum Lager der Totenwaldfelle; haltet einfach Ausschau nach ihren widerwärtigen Bannern.", sourceObjective = "Tötet 12 Jadefeuersatyrn oder Jadefeuerteufelsanbeter im Jadefeuertal.", progress = "Das Jadefeuertal ist unser erstes Ziel in einer ganzen Reihe von koordinierten Angriffen. Um die anderen kümmern wir uns später.", completion = "Der Dank des Smaragdkreises ist Euch sicher, {name}. Wenn wir hier alle zusammenarbeiten, können wir diese Dämonen aus unserer Mitte tilgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27998] = { id = 27998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße, gnadenlose Rache", description = "Wenn alles gut geht, solltet Ihr in der Lage sein, direkt in Godfreys persönliche Gemächer zu spazieren und eine Belohnung zu erhalten, die <einem/einer:c> {class}, wie Ihr es seid, gebührt.\n\nGodfrey ist allerdings ein listiger Gegner, es könnte also weise sein, Euch schnell auf den Weg dorthin zu machen, für den Fall, dass Ihr benötigt werdet. Er wird dafür bezahlen, was er der Dunklen Fürstin angetan hat!", sourceObjective = "Tötet Lord Godfrey.", completion = "Einen Moment lang dachte ich, alles wäre dahin. Selbst als ich in Gilneas von den Worgen umzingelt war, hatte ich mehr Hoffnung!\n\nAber Ihr habt meine Befürchtungen widerlegt, {name}. Ich werde dafür sorgen, dass Sylvanas selbst von Eurem heutigen Sieg erfährt. Macht Euch keine Gedanken über die Unordnung hier. Ich werde mich gern selbst darum kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27999] = { id = 27999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Doyles", description = "Anscheinend haben die Doyles ihren letzten Kampf hinter sich. Iain wird über ihr Schicksal Bescheid wissen wollen.", sourceObjective = "Kehrt mit den Neuigkeiten über den Klan Doyle zu Iain Feuerbart auf Feuerbarts Friedhof zurück.", completion = "Das ist wirklich schade. Genauso stur, wie sie sich verhielten, wenn man mit ihnen reden wollte, waren sie auch im Kampf. Es wäre gut gewesen, sie dabeizuhaben.\n\nSobald das hier erledigt ist, werden wir einige der Jungs aussenden, um sie zurückzuholen, damit wir ihnen ein anständiges Begräbnis verschaffen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28000] = { id = 28000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichteln, einmal anders", description = "Die Satyrn verstecken ihren verderbten Mondbrunnen hinter einer undurchdringlichen Barriere aus dämonischem Feuer. Ihre eigenen Truppen müssen über eine Möglichkeit verfügen, ungehindert hindurchzudringen.\n\nDie Satyrn zu verhören wird sinnlos sein, aber die Wichtel, mit denen sie verkehren, dürften leicht zu beeinflussen sein. Ich habe da einen ganz bestimmten im Auge...\n\nÖstlich von hier, am Gebirgsfuß, wurde ein einsamer Wichtel gesehen, der weit abseits der anderen Dämonen umherstreift. Er dürfte leichte Beute sein. Schwächt ihn im Kampf und benutzt dann diesen verzauberten Sack, um ihn einzufangen. Das Reden übernehme ich dann...", sourceObjective = "Schwächt Impsy und dann benutzt den verzauberten Wichtelsack, um ihn einzufangen.", completion = "Wichtel sind betrügerische Kreaturen. Da so viele von ihnen am Schattenlauergrat gesehen wurden, bin ich sicher, dass dort etwas versteckt wird.\n\nUnser kleiner Freund wird uns genau beschreiben, wie wir das finden können, wenn er nicht wieder in den Sack zurück will.", sourceObjectiveStatus = "unverified-source-field" }
quests[28001] = { id = 28001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was einem Feigling zusteht", description = "Mag ja sein, dass wir hier sicher sind, aber da draußen gibt es noch eine Menge Wildhämmer, die Unterstützung brauchen können. Unser Geschwader kann die bieten, aber wir müssen unsere Streitkräfte verstärken, wenn wir den Schattenhammer auslöschen wollen.\n\nIch werde mit Colin Donnermar sprechen. Nur ein Feigling wendet sich von dem Ruf seines Volkes ab, vor allem in schwierigen Zeiten wie diesen.\n\nGeht nach Donnermar, findet Colin und lasst Euch von ihm eine vernünftige Erklärung geben. Ich werde keine Feigheit bei einem Anführer der Wildhammer dulden.", sourceObjective = "Sprecht mit Colin Donnermar in Donnermar.", completion = "Bitte? BITTE WAS!? Er nennt MICH einen FEIGLING?!\n\nTypisch Feuerbart - nur heiße Luft und keine Spur von Verstand. Ich habe die Hauptlast des Einmarsches des Drachenmalklans aus dem Süden ertragen, Donnermar liegt zum großen Teil in Trümmern und kommt mal einer der anderen Klans zu Hilfe? NEIN! Der alte Donnermar ist hier ganz allein und Ihr könnt mir glauben, dass ich alles in meinem Arsenal benutze, nur um die Flutwelle aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28002] = { id = 28002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krisenmanagement", description = "Es gibt eine heikle Situation, die nach der... unparteiischen Diskretion eines Außenstehenden verlangt.\n\nWisst Ihr, ein unglücklicher Vorfall hat einige unserer Gäste beunruhigt. Seid versichert, dass unsere besten Leute sich um die Einzelheiten kümmern.\n\nIn der Zwischenzeit wäre es wunderbar, wenn Ihr unsere etwas überempfindlichen Gäste beruhigen könntet.\n\nWenn Ihr damit gut umgeht, wird der Fellhändler mit Sicherheit davon hören!", sourceObjective = "Bellok Leuchtklinge möchte, dass Ihr die Gäste in Schnottz' Landeplatz beschwichtigt.", completion = "Hmm, sie sind immer noch ein wenig außer sich, wie?\n\nNun, Ihr kennt ja das Sprichwort. Die Zeit heilt alle Wunden.\n\nAußer die des Botschafters natürlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[28003] = { id = 28003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Flammenschlund", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Flammenschlund, direkt unterhalb des großartigen Orgrimmars, zu reisen!\n\nDie Sengende Klinge ist bereit, jeden Augenblick anzugreifen und die Stadtwachen können nicht mehr viel länger aushalten! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Flammenschlund und sprecht mit Steingardist Kurjack, dem Leiter der Verteidigungsinitiative, um der Bedrohung für Orgrimmar ein für alle Mal ein Ende zu setzen!", sourceObjective = "Sprecht mit Steingardist Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28004] = { id = 28004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Todesminen", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im weit entfernten Westfall zu reisen!\n\nEure Unterstützung ist vonnöten, um ein Schiff der Defias, die Moloch, für die Horde einzunehmen und es gegen die Allianz einzusetzen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zu den Todesminen und sprecht mit Kagtha, einer Schurkin der Zerschmetterten Hand, um im Krieg gegen die Allianz behilflich zu sein.", sourceObjective = "Sprecht mit Kagtha.", sourceObjectiveStatus = "unverified-source-field" }
quests[28005] = { id = 28005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Todesminen", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Todesminen im südlichen Westfall zu reisen!\n\nEs wird Unterstützung dabei benötigt, die Schreckensherrschaft der wiedergeborenen Bruderschaft der Defias dort zu beenden! Entschließt Ihr Euch zu helfen, so begebt Euch zu den Todesminen und sprecht dort mit Horatio Laine, dem leitenden Ermittler in der Sache, um der Defias ein für alle Mal das Handwerk zu legen.", sourceObjective = "Sprecht mit Leutnant Horatio Laine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28006] = { id = 28006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Höhlen des Wehklagens", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zu den Höhlen des Wehklagens westlich des Wegekreuzes zu reisen!\n\nNaralex muss erweckt werden, um das Brachland zu retten! Ihr solltet Eure Entscheidung weise treffen, zu den Höhlen des Wehklagens aufbrechen und mit Nalpak, einem Jünger Naralex' sprechen, um dabei zu helfen, das zerstörte Land zu heilen.", sourceObjective = "Sprecht mit Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28007] = { id = 28007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Die Höhlen des Wehklagens", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zu den Höhlen des Wehklagens westlich des Wegekreuzes zu reisen!\n\nNaralex muss erweckt werden, um das Brachland zu retten! Ihr solltet Eure Entscheidung weise treffen, zu den Höhlen des Wehklagens aufbrechen und mit Nalpak, einem Jünger Naralex' sprechen, um dabei zu helfen, das zerstörte Land zu heilen.", sourceObjective = "Sprecht mit Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28008] = { id = 28008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Burg Schattenfang", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Burg Schattenfang im südlichen Silberwald zu reisen!\n\nDer Verräter, Lord Godfrey, soll dafür bezahlen, was er Sylvanas angetan hat! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zur Burg Schattenfang und sprecht mit Todespirscherkommandant Belmont, dem Leiter der dortigen Kriegsanstrengungen, um bei der Durchführung der angemessenen Rache behilflich zu sein.", sourceObjective = "Sprecht mit Todespirscherkommandant Belmont.", sourceObjectiveStatus = "unverified-source-field" }
quests[28009] = { id = 28009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Burg Schattenfang", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Burg Schattenfang im südlichen Silberwald zu reisen!\n\nDer Verräter, Lord Godfrey, soll dafür bezahlen, was er unseren neuen Verbündeten angetan hat! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zur Burg Schattenfang und sprecht mit Rudelführer Ivar Blutfang, dem Leiter der dortigen Kriegsanstrengungen, um bei der Durchführung der angemessenen Rache behilflich zu sein.", sourceObjective = "Sprecht mit Rudelführer Ivar Blutfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[28010] = { id = 28010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Tiefschwarze Grotte", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Tiefschwarzen Grotte nördlich vom Außenposten von Zoram'gar zu reisen!\n\nDer Schattenhammerkult bedroht dort mit seinen Taten das Wohl der Welt! Ihr solltet Eure Entscheidung weise treffen, zur Tiefschwarzen Grotte aufbrechen und mit Je'neu Sancrea, einem Mitglied des Irdenen Rings sprechen, um die Bedrohung durch den Kult aufzuhalten.", sourceObjective = "Sprecht mit Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[28011] = { id = 28011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Tiefschwarze Grotte", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Tiefschwarzen Grotte westlich von Astranaar zu reisen!\n\nDer Schattenhammerkult bedroht dort mit seinen Taten das Wohl der Welt! Ihr solltet Eure Entscheidung weise treffen, zur Tiefschwarzen Grotte aufbrechen und mit Schildwache Aluwyn, der Anführerin der Truppen der Nachtelfen vor Ort sprechen, um die Bedrohung durch den Kult aufzuhalten.", sourceObjective = "Sprecht mit Schildwache Aluwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28012] = { id = 28012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Verlies von Sturmwind", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Verlies von Sturmwind innerhalb der Stadt selbst zu reisen!\n\nIm Verlies ist es zu einer Massenrevolte gekommen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Verlies und sprecht mit Schützenkommandant Coe, dem Anführer der Wache des Verlieses, um den Aufstand niederzuschlagen.", sourceObjective = "Sprecht mit Schützenkommandant Coe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28013] = { id = 28013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Gnomeregan", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Gnomeregan westlich von Eisenschmiede zu reisen!\n\nDie Gnome brauchen Hilfe dabei, ihre Stadt wieder einzunehmen! Falls Ihr interessiert seid, begebt Euch nach Gnomeregan und sprecht mit Mör'dok, dem Rekrutierer des G-Teams, um ihnen zu helfen.", sourceObjective = "Sprecht mit Mör'dok.", sourceObjectiveStatus = "unverified-source-field" }
quests[28014] = { id = 28014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Kral der Klingenhauer", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Kral der Klingenhauer im südlichsten Teil des Südlichen Brachlands zu reisen!\n\nAuld Steinkeil braucht Hilfe dabei, die Verbreitung der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Kral der Klingenhauer und sprecht mit Auld Steinkeil, einem weisen und respektierten Schamanen, um ihm zu helfen.", sourceObjective = "Sprecht mit Auld Steinkeil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28015] = { id = 28015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Kral der Klingenhauer", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Kral der Klingenhauer im südlichsten Teil des Südlichen Brachlands zu reisen!\n\nAuld Steinkeil braucht Hilfe dabei, die Verbreitung der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Kral der Klingenhauer und sprecht mit Auld Steinkeil, einem weisen und respektierten Schamanen, um ihm zu helfen.", sourceObjective = "Sprecht mit Auld Steinkeil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28016] = { id = 28016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Friedhof", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, damit sie ihren Angriff beginnen kann! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara - einer äußerst klugen Kämpferin - um Euren Teil beizutragen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28017] = { id = 28017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Bibliothek", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Bibliothek des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Verteidigung dort zu durchbrechen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Bibliothek des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28018] = { id = 28018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Waffenkammer", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Waffenkammer des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um die Offensivkräfte dort auszuschalten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Waffenkammer des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euren Teil beizutragen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28019] = { id = 28019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Kathedrale", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Kathedrale des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nDie dunkle Waldläuferin Velonara hat um weitere Soldaten gebeten, um den letzten Nagel in den Sarg des Scharlachroten Kreuzzuges zu schlagen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Kathedrale des Scharlachroten Klosters und sprecht mit der dunklen Waldläuferin Velonara, um Euch an dem Sieg der Verlassenen zu erfreuen!", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28020] = { id = 28020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Friedhof", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Friedhof des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Erweckte - ein ehemaliger Kreuzfahrer - hat um Hilfe gebeten, die dortigen Anführer auszuschalten und den Kreuzzug neu zu formieren! Wenn Ihr Euch dazu entschließt, begebt Euch zum Friedhof des Scharlachroten Klosters und sprecht mit Joseph dem Erweckten, um Euren Teil beizutragen.", sourceObjective = "Sprecht mit Joseph dem Erweckten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28021] = { id = 28021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Bibliothek", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Bibliothek des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Erweckte hat um weitere Hilfe gebeten, um die Magier des Kreuzzugs auszuschalten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Bibliothek des Scharlachroten Klosters und sprecht mit Joseph dem Erweckten, um die Kreuzfahrer ins Licht zurückzuführen.", sourceObjective = "Sprecht mit Joseph dem Erweckten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28022] = { id = 28022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Waffenkammer", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Waffenkammer des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Wahnsinnige hat um Hilfe gebeten, um Herod den Scharlachroten Champion zu töten! Wenn Ihr Euch dazu entschließt, begebt Euch zur Waffenkammer des Scharlachroten Klosters und sprecht mit Joseph dem Wahnsinnigen, um ihm zu helfen.", sourceObjective = "Sprecht mit Joseph dem Wahnsinnigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28023] = { id = 28023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scharlachrotes Kloster - Kathedrale", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Kathedrale des Scharlachroten Klosters nordöstlich von Unterstadt zu reisen!\n\nJoseph der Rasende braucht Hilfe, um den Scharlachroten Kreuzzug endlich zu übernehmen! Wenn Ihr Euch dazu entschließt, begebt Euch zur Kathedrale des Scharlachroten Klosters und sprecht mit Joseph dem Rasenden, um Geschichte zu schreiben.", sourceObjective = "Sprecht mit Joseph dem Rasenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28024] = { id = 28024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Hügel der Klingenhauer", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Hügel der Klingenhauer in Tausend Nadeln zu reisen!\n\nDie geheimnisvolle Koristrasza braucht Hilfe dabei, die Allianz der Geißel und der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Hügel der Klingenhauer und sprecht mit Koristrasza, um ihr zu helfen.", sourceObjective = "Sprecht mit Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28025] = { id = 28025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Hügel der Klingenhauer", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Hügel der Klingenhauer in Tausend Nadeln zu reisen!\n\nDie geheimnisvolle Koristrasza braucht Hilfe dabei, die Allianz der Geißel und der Stacheleber zu unterbinden! Falls Ihr interessiert seid, begebt Euch zum Hügel der Klingenhauer und sprecht mit Koristrasza, um ihr zu helfen.", sourceObjective = "Sprecht mit Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28026] = { id = 28026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Uldaman", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Uldaman unweit Neu-Kargaths zu reisen!\n\nDie Archäologische Akademie und ihr Leiter, der Oberste Prüfer Tae'thelan Blutwächter, benötigt Unterstützung, um die mächtigen Artefakte im Inneren zu sichern! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Uldaman und sprecht mit dem Obersten Prüfer, um sie in ihren Bestrebungen zu unterstützen.", sourceObjective = "Sprecht mit dem Obersten Prüfer Tae'thelan Blutwächter.", sourceObjectiveStatus = "unverified-source-field" }
quests[28027] = { id = 28027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Uldaman", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Uldaman im Ödland zu reisen!\n\nDie Forscherliga und ihr Leiter, der Oberausgrabungsleiter Durdin, benötigt Unterstützung, um gegen die großen Gefahren zu bestehen, die die Jagd nach Wissen mit sich bringt! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Uldaman und sprecht mit dem Oberausgrabungsleiter Durdin, um sie in ihren Bestrebungen zu unterstützen.", sourceObjective = "Sprecht mit dem Oberausgrabungsleiter Durdin.", sourceObjectiveStatus = "unverified-source-field" }
quests[28028] = { id = 28028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung!", description = "Aufseher Schlickfaust hätte sich keinen schlechteren Zeitpunkt aussuchen können, um mich zu bitten, einem Kampf beizutreten. Meine Spitze wird bereits belagert!\n\nNichts, womit meine Wachen nicht umgehen könnten, aber trotzdem... es wird nicht leicht für mich sein, damit weiterzumachen und gleichzeitig Zwerge in diese höllische Schlucht zu entsenden.\n\nIch sage Euch was: Ihr schaltet deren Schützen aus, die unsere Festung belagern, und ich denke noch mal über Euer Angebot nach. Sie schleichen auf den Felsvorsprüngen im Osten herum.", sourceObjective = "Tötet 9 Schützen der Dunkeleisenzwerge.", completion = "Das Mindeste, was Ihr für uns getan habt, ist uns etwas Zeit und Platz zu verschaffen, unsere Versorgungslinien durch diese Belagerung zu öffnen.\n\nSeid 'n feiner {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28029] = { id = 28029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt sie in Brand!", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber mein Turm ist um einiges größer als die anderen Türme hier in der Schlucht. Manche Zwerge bilden sich etwas darauf ein, wie tief sie graben können... ich nicht. Manchmal glaube ich, ich hätte eigentlich als Wildhammerzwerg zur Welt kommen sollen.\n\nTrotzdem gefällt mir der Anblick dieser anderen Türme nicht. Wie sie sich so in den Himmel recken und meinem Turm an den Zehen kitzeln. Hier, nehmt diese Fackel und benutzt sie an den Kohlepfannen auf den anderen Türmen. Es wird ihnen noch leid tun, diese Türme überhaupt gebaut zu haben.", sourceObjective = "Benutzt die Fackel der Vergeltung auf den vier Türmen, die den Kessel umgeben.", completion = "Ihr wisst offenbar, wie man Dinge in Brand steckt. Eine bewunderungswürdige Fertigkeit für jeden {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28030] = { id = 28030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Kugel", description = "Diese in der Schlucht grabenden Zwerge machen wenigstens eine Sache richtig: Sie stellen qualitativ hochwertige Patronen her. Es war mir bisher nicht möglich, ihre Ergebnisse zu reproduzieren, weshalb ich dazu gezwungen war, ihnen alle Kugeln, die ich finden konnte, zu stehlen.\n\nIhr wollt meine Hilfe? Besorgt mir ein paar Hundert Dunkeleisenkugeln von ihren Schützen da unten.\n\nIch bin mir sicher, dass sie Euch mit Vergnügen eine Kugel nach der anderen geben werden, aber es könnte einfacher sein, wenn Ihr nach den Kisten Ausschau haltet, in denen sie sie lagern.", sourceObjective = "Beschafft Euch 200 Dunkeleisenkugeln.", progress = "Ein richtiger {class} hätte die Kugeln mit seinen Zähnen gefangen.", completion = "Ich verteil' die mal unter den Wachen. Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[28031] = { id = 28031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderlieferung für Langnase", description = "Ich habe einen neuen Geschäftspartner, meinen besten Freund Langnase. Gerade jetzt arbeitet er daran, die Infrastruktur für unser neues Eiscremeimporium aufzuarbeiten!\n\nEr hat unseren Kühlschlepper, unser gesamtes Inventar, und auch die Mitarbeiter in die Versunkene Ausgrabungsstätte befördert. Leider sehe ich gerade keine Möglichkeit, ihm die nächste Lieferung zukommen zu lassen... eine äußerst wichtige Lieferung: unsere supergeheime SchrEIS-Kryokanone!\n\nEs würd Euch nicht stören, sie ihm zu bringen, oder?", sourceObjective = "Liefert die SchrEIS-Kryokanone an Langnase in der Versunkenen Ausgrabungsstätte in Tausend Nadeln.", progress = "Das ist nicht das, was ich glaube, dass es ist? Oder doch?!", completion = "Das muss die neue SchrEIS-Kryokanone sein! Oh, ist sie nicht wunderschön?!\n\n<Langnase betrachtet Euch mit dem geübten Auge eines Geschäftsmannes.>\n\nIch werde Euch ein Geheimnis verraten, meine Liebe: die Grundmauern eines großen Handelsimperiums werden hier gelegt!\n\nSagt mir... mögt Ihr Eiscreme?", sourceObjectiveStatus = "unverified-source-field" }
quests[28032] = { id = 28032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse des Feuermuskelmagens", description = "Es gibt so vieles, was wir bei den Incendosauriern nicht wissen. Woher kommen sie? Wie überleben sie hier draußen in den Ebenen? Und warum schmecken sie so überhaupt nicht?\n\nDer Schlüssel zum Verständnis dieser prähistorischen Bestien liegt, so glaube ich, im Feuermuskelmagen. Jeder Incendosaurier verfügt über einen. Ich hätte gerne ein paar davon, um sie zu untersuchen.\n\nIhr findet Incendosaurier, die sich am Fuße des Eisengipfels aufhalten, hauptsächlich im Westen.", sourceObjective = "Sammelt 6 Feuermuskelmägen.", progress = "Endlich bekomme ich ein paar dieser Reptilienmägen in die Finger!", completion = "Oh, die sind aber schnuckelig. Lasst mich jetzt mit meinen Innereien allein. Es gibt viel zu untersuchen!\n\n<Agnes beginnt, mit einem Stock in den Mägen herumzustochern.>\n\nJa, sehr interessant. Äußerst interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[28033] = { id = 28033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrug", description = "Was? Warum seid Ihr noch immer hier? Oh, habe ich versprochen, dass ich Euch und der Thoriumbruderschaft in Eurem Kampf helfen würde?\n\nIch habe gelogen.\n\nIch habe im Moment einfach keine Männer übrig. Ich weiß, ich habe gesagt, ich würde helfen, aber ich werde mich unter keinen Umständen von Euch überzeugen lassen, den Eisengipfel jetzt zu verlassen. Unter keinen Umständen.", sourceObjective = "Findet einen Weg, den Bergfürsten Rendan davon zu überzeugen, sich der Thoriumbruderschaft anzuschließen.", completion = "So, so, so. Einer mal ansehen, wer diesmal Lunks Hilfe brauchen!\n\nDas klingen nach Fall für Lunks einzigartigen Ansatz für Problemlösung ohne Töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28034] = { id = 28034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunks Abenteuer: Rendans Schwäche", description = "Lunk nicht klug, aber Lunk fallen Dinge auf. Heute ist Lunk aufgefallen, dass Bergzwerg es mag, Leute tanzen zu sehen.\n\nLunk mag tanzen! {name} mag tanzen! Wahrscheinlich!\n\nVielleicht finden wir mehr Zwerge die tanzen mögen. Dann wir reden mit Bergzwerg und er wird {name} zuhören.", sourceObjective = "Sprecht mit drei Eisengipfelwachen und bittet sie, bei Eurem Tanz mitzumachen.", completion = "Sprech' ich etwa undeutlich? Ich habe doch ganz klar gesagt, dass ich... nicht...\n\nHe, Ihr habt echt was drauf! Bin beeindruckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28035] = { id = 28035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstützung des Bergfürsten", description = "In Ordnung, in Ordnung! Wenn ich gewusst hätte, dass Ihr so tanzen könnt, dann hätte ich Euch nicht den ganzen anderen Kram machen lassen.\n\nSagt Aufseher Schlickfaust, dass ich mich Euch anschließen werde. Ich treffe Euch in der Schlackengrube, <Kumpel/Mädel>! Mit den vereinten Kräften der Thoriumsspitze und des Eisengipfels werden die Schluchtzwerge gar nicht wissen, wie ihnen geschieht!", sourceObjective = "Berichtet Aufseher Schlickfaust auf der Thoriumsspitze in der Sengenden Schlucht von Eurem Erfolg.", completion = "So, Rendan steht also auf unserer Seite? Wurde auch Zeit, dass der Tölpel sich einen Ruck gegeben hat.\n\nAlso Abmarsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28036] = { id = 28036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Zul'farrak", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Zul'farrak westlich von Gadgetzan zu reisen!\n\nGadgetzan wird von den Trollen der Sandwüter und ihrer wachsenden Armee bedroht! Falls Ihr interessiert seid, begebt Euch nach Zul'farrak und sprecht mit Tran'rek, um den Goblins zu helfen.", sourceObjective = "Sprecht mit Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28037] = { id = 28037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Zul'farrak", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Zul'farrak westlich von Gadgetzan zu reisen!\n\nGadgetzan wird von den Trollen der Sandwüter und ihrer wachsenden Armee bedroht! Falls Ihr interessiert seid, begebt Euch nach Zul'farrak und sprecht mit Tran'rek, um den Goblins zu helfen.", sourceObjective = "Sprecht mit Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28038] = { id = 28038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut im Hochland", description = "Ihr habt einigen Kampfeswillen in Euch, {class}. Ihr könntet Euch im Schmelztiegel gut schlagen.\n\nWie bitte? Ihr habt noch nie vom Schmelztiegel des Gemetzels gehört? Dieser schmierige Goblin Gurgthock und sein Trollkumpel pflastern uns ständig mit Handzetteln zu, seit er sich hier im Hochland angesiedelt hat. Champions aus ganz Azeroth kämpfen dort bis zum Tod. Ihr solltet ein paar Freunde zusammentrommeln und sehen, was Ihr dort ausrichten könnt.\n\nDer Schmelztiegel ist genau im Südwesten. Sucht nach Wodin dem Trolldiener, der sich irgendwo in der Mitte eines Rings aus Knochen befindet.", sourceObjective = "Sprecht mit Wodin dem Trolldiener am Schmelztiegel des Gemetzels im Schattenhochland.", completion = "Hey, ein {class}, der ein kräftiger Bursche zu sein scheint. Könnt Ihr im Schmelztiegel bestehen? Wir haben sogar Buchmacher in Bereitschaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[28039] = { id = 28039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Maraudon", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Maraudon im westlichen Desolace reisen!\n\nMaraudon von seiner derzeitigen Verderbnis zu heilen, würde der Gesamtheit Desolaces sehr helfen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Maraudon und sprecht mit Zaetars Geist. Er wird Euch leiten.", sourceObjective = "Sprecht mit Zaetars Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28040] = { id = 28040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Maraudon", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Maraudon im westlichen Desolace zu reisen!\n\nMaraudon von seiner derzeitigen Verderbnis zu heilen, würde der Gesamtheit Desolaces sehr helfen! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch nach Maraudon und sprecht mit Zaetars Geist. Er wird Euch leiten.", sourceObjective = "Sprecht mit Zaetars Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28041] = { id = 28041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ködern und würgen", description = "Ihr könnt Euch gut behaupten, {name}, das muss ich Euch lassen.\n\nAber wir vom Drachenmalklan dominieren den Himmel ebenso wie das Land. Solange Ihr mir nicht beweist, dass Ihr mit einem Drachen ebenso gut umgehen könnt, wie ein Mitglied des Drachenmalklans, zählt Eure Horde nicht für mich.\n\nSchauen wir einmal, ob Ihr einen zur Blutschlucht zurückbringen könnt.\n\nAls erstes braucht Ihr einen Köder. Geht und tötet einen der Greife, die durch die Wälder im Westen oder Nordosten von hier streifen. Achtet darauf, dass es kein gezähmter ist! Drachen hassen den Gestank von Zwergen auf ihrem Futter.\n\nBesorgt den Greifenkadaver und Ihr werdet wissen, was zu tun ist.", sourceObjective = "Besorgt einen frischen Greifenkadaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[28042] = { id = 28042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderlieferung für Langnase", description = "Ich habe vor Kurzem etwas erhalten, das einem Gnom namens Langnase geliefert werden muss. Stumpfnase wäre wohl passender, wenn Ihr mich fragt.\n\nWie dem auch sei, ich möchte, dass Ihr die Lieferung nach Südwesten, zur verlassenen Ausgrabungsstätte bringt. Er hat etwas vor, und es hat mit viel Zaster zu tun... ich kann es förmlich riechen!\n\nWerft ein Auge darauf, was er treibt, {name}, und versucht, an einen Teil seines Gewinns heranzukommen. Einen großen Teil!", sourceObjective = "Liefert die SchrEIS-Kryokanone an Langnase in der Versunkenen Ausgrabungsstätte in Tausend Nadeln.", progress = "Das ist nicht das, was ich glaube, dass es ist? Oder doch?!", completion = "<Langnase schaut Euch von Kopf bis Fuß an, aber wird aufgeregt und überglücklich, als er die Sonderlieferung sieht.>\n\nWillkommen, Freudenlieferer, herzlich willkommen! Ich kann Euch eine Einstiegsposition in einer wahrlich lebensverändernden Arbeit anbieten.\n\nDem Unternehmergeist sind die Unterschiede zwischen Horde und Allianz egal!\n\nSagt mir... mögt Ihr Eiscreme?", sourceObjectiveStatus = "unverified-source-field" }
quests[28043] = { id = 28043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachen quälen leicht gemacht", description = "<Ihr werft Euch den blutüberströmten Greifenkadaver über die Schulter. Seine Flügel schleifen auf dem Boden.>\n\n<Hochlandschwarzdrachen nisten südwestlich des Schmelztiegel des Gemetzels auf einem Kreis aus niedrigen Berggipfeln.>\n\n<Wenn Ihr den Greifenkadaver dort ablegt, wird sicherlich ein Drache beginnen, ihn zu fressen. Da er nicht wachsam sein wird, solltet Ihr in der Lage sein, ihn anzugreifen, bis er schwach genug ist, dass Ihr aufsitzen und ihn fliegen könnt.>", sourceObjective = "Lockt einen geköderten Schwarzdrachen an, greift ihn an, bis er geschwächt ist und dann reitet ihn zurück zur Blutschlucht.", completion = "Das war eine beeindruckende Flugvorführung, {name}, aber ich wünschte, sie hätte zu einem passenderen Zeitpunkt stattgefunden.\n\nNarkrall ist ein großer Krieger, aber er ist auch ein ungeduldiger Narr. Er ist gerade dabei, sich umzubringen... und wir sind gerade dabei, eine unserer wichtigsten Waffen im Kampf um das Hochland zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[28044] = { id = 28044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unberührbare berühren", description = "Ich habe einen Tropfen meiner eigenen Essenz in den Schlamm gegeben. Haltet im Westen, am Rand des Schattenlauergrats, nach einem Siegelzeichen Ausschau. Stellt Euch darauf, konzentriert Euch, und gießt dann dieses Zeug über Euch. Es sollte ausreichen, damit Ihr in den Nether wechseln und sehen könnt, was WIRKLICH da ist.\n\nIhr werdet nicht alleine sein... Der Schatz des Satyrs wird von dem größten Leerenwandler beschützt, den sie beschwören konnten. Besiegt ihn, und der Schatz gehört Euch.\n\nUnd kommt heil zurück, oder dieses verrückte Weib wird mich in Stücke reißen!", sourceObjective = "Benutzt den Phasenbluttrank beim Siegelzeichen des Tichondrius, um in den Nether zu wechseln, und sucht nach der Klaue des Tichondrius.", progress = "Könnt Ihr mich da drin hören, {name}? Habt Ihr die Klaue?", completion = "Die Klaue des Tichondrius...\n\nIhr haltet ein Stück des Dämons in der Hand, der die Legion in diese Wälder geführt hat, {name}. Es ist besser in unseren Hände als bei den Satyrn.\n\nHaltet still. Ich werde Euch auf unsere Ebene zurückholen und dafür sorgen, dass Ihr und die Klaue sicher hier ankommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28045] = { id = 28045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Geschmack der Welt!", description = "Unter uns ist eine Höhle - eine riesige Höhle! Etwas besseres können wir für unsere neue Kühlhalle fast nicht finden. Die Höhle ist so groß, dass alle unsere Vorräte hineinpassen, und wir sogar expandieren können.\n\nLeider sind Insektentiere aus dem Nichts erschienen, als wir fast fertig waren, die Rohre zu verlegen, und haben alle meine Angestellten getötet!\n\nDamit konnte ich nicht rechnen!\n\nIch habe allerdings deshalb eine tolle Idee gehabt: Eiscreme mit Silithidengeschmack! Das wird der absolute Renner!\n\nWir brauchen nur noch die Zutaten.", sourceObjective = "Erhaltet 8 Löffel Silithidenglibber.", progress = "Habt Ihr genug Glibber für die erste Ladung Eiscreme?", completion = "Oh ja! Das wird mit Sicherheit der beste Eiscremegeschmack auf der Welt!\n\nForor und Tigule können einpacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[28046] = { id = 28046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es zu Ende", description = "Wir versuchen schon die ganze Woche, an der Front brauchbaren Schrott zu sammeln. Jedes Mal, wenn wir eine Ladung zusammengestellt haben und sie zum Lager zurückbringen wollen, werden wir von der rastlosen Infanterie aus der Umgebung angegriffen. Könntet Ihr Euch dorthin begeben und sie beseitigen?", sourceObjective = "Tötet 5 rastlose Infanteristen an der Rastlosen Front. Ihr findet die Front auf der westlichen Seite der Insel, direkt vor dem Vergessenen Hügel.", completion = "Wurde auch Zeit, dass sich die Burschen jemand vorknöpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28047] = { id = 28047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rohre einfrieren", description = "Es ist an der Zeit, dass wir die SchrEIS-Kryokanone einweihen!\n\nWir konnten die Technik der Frostkanonen der Rennboote entfernen - wenn wir Gnome eines wirklich gut können, dann ist es Sachen klein machen, indem wir alles andere vergrößern!\n\nBringt die Kanone in die Höhle und friert die Rohre ein, die wir in den Wänden installiert haben. Das wird einen guten Anstoß geben!", sourceObjective = "Benutzt die SchrEIS-Kryokanone, um die vier Rohre in der Höhle einzufrieren.", completion = "Hört Ihr das, {name}? Dieses Brummen ist das hübsche Geräusch, dass von der Kühlung hervorgerufen wird.\n\nWir werden unsere Vorräte hier unten schon sehr bald lagern können. Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[28048] = { id = 28048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarmaufseher muss entfernt werden", description = "Hinten in der Höhle ist eine Art schlaues Insekt. Es scheint, es hält den Posten des Aufsehers der Silithiden inne.\n\nMeine Eiscreme schmilzt! Wie soll ich nur mein Eiscremimperium erfolgreich starten und meine Vorräte sichern, wenn dieses Ding in der Höhle ist?!", sourceObjective = "Töten den Schwarmaufseher.", completion = "Großartig! jetzt kann uns nichts mehr davon abhalten, die besten Eiscremehersteller Azeroths zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28049] = { id = 28049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unsichtbare sehen", description = "Ja, ja, Eure hochnäsige Magierfreundin da hat den Nagel auf den Kopf getroffen. Die Wichtel im Schattenlauergrat verstecken den Schlüssel zu der Satyrbarriere im Nether. Es ist direkt da, aber man kann es weder sehen noch berühren, wenn man sich nicht innerhalb einer Phasenverschiebung befindet.\n\nEs scheint, als hättet Ihr kein Glück, da nur Wichtel der Phasenverschiebung mächtig sind! Ihr solltet also einfach die Augen zumachen, Euch umdrehen und mich gehenlassen...\n\nEs war ein Witz! Tut mir nicht weh! Ich brauche Schleim von den verfluchten Schlammen in diesen Ruinen. Bringt mir genug, um Euch von Kopf bis Fuß damit zu bedecken!", sourceObjective = "Sammelt 8 Einheiten verfluchten Schlamm aus den Ruinen von Constellas.", progress = "Habt Ihr den Schleim?", completion = "Ah gut, Ihr seid wieder da! Lasst mich mit ihr nicht allein! Sie ist irre!\n\nHer damit. Ihr werdet im Handumdrehen Unsichtbares sehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28050] = { id = 28050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank, der Haifisch", description = "Ich hasse Haie. Alle meine Soldaten hassen Haie ebenfalls. Und hier kommt Ihr ins Spiel, {name}.\n\nIch möchte, dass Ihr Euch zum Kap der Verlorenen Hoffnung begebt und einen riesigen Hai namens Tank aus dem Weg räumt. Mit Tank ist nicht zu spaßen, deshalb würde ich an Eurer Stelle noch ein paar Freunde mitbringen.", sourceObjective = "Ihr habt den Auftrag erhalten, Tank, einen großen Hai, der die Gewässer um das Kap der Verloren Hoffnung durchpflügt, zu töten. Das Kap kann nördlich von hier gefunden werden, an der nördlichen Küste.", completion = "Ihr macht Witze, oder? Ihr habt ihn tatsächlich besiegt? Heute Abend stehen Haifischtacos auf der Speisekarte!", sourceObjectiveStatus = "unverified-source-field" }
quests[28051] = { id = 28051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle wollen Eiscreme... und finden den Tod!", description = "Versteht mich nicht falsch... ich mag zwar gut gelaunt erscheinen, aber innerlich bin ich in in tausend Stücke gerissen. Alle meine Freunde und Angestellten sind tot.\n\nKönntet Ihr mir einen Gefallen tun? Könntet Ihr in die Höhle schwimmen und den Haken am Seil an den Köpfen der toten Angestellten befestigen? Ich ziehe sie dann hoch.", sourceObjective = "Befestigt den Haken des Abschleppseils an 10 toten Angestellten.", completion = "Vielen Dank, {name}. Sie haben ihr Leben für Eiscreme gelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28052] = { id = 28052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Rührt den Kessel um", description = "Ich setze Euch in eine Flugmaschine, {name}.\n\nIhr werdet dafür zuständig sein, dass unsere Landung in der Schlackengrube so glatt wie möglich verläuft. Sprecht mit Eurem Flugmeister hier an der Thoriumspitze und fliegt dann runter zur Schlucht.\n\nSobald Ihr Euch dem Landepunkt nähert, werden zweifellos Horden von Dunkeleisenzwergen auf Euch warten. Benutzt die Kanonen unserer Flugmaschine, um so viele von ihnen außer Gefecht zu setzen, wie Ihr könnt, und landet dann am Eingang der Höhle. Rendan sollte bei Eurer Ankunft schon auf Euch warten.", sourceObjective = "Sprecht mit dem Flugmeister der Thoriumsspitze und benutzt dann die Kanonen der Flugmaschine der Bruderschaft, um Kesselverteidiger zu töten, bis der Bereich sicher genug ist, um ihn zu betreten.", completion = "So, da wären wir.\n\nIch hoffe, Ihr seid bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28053] = { id = 28053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk mag Euren Stil", sourceObjective = "Lunk gehört, dass Ihr Stein benutzt habt, um Feuerechse zu verbannen. Ihr gerettet Schlucht und habt nicht einmal getötet!\n\nLunk so stolz. Lunk ist gern Lehrer von {name}.\n\nVielleicht ihr das hier nehmen. Lunk es nicht brauchen. Lunk zu beschäftigt mit Abenteuern!", sourceObjectiveStatus = "unverified-source-field" }
quests[28054] = { id = 28054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduzierung des Wettbewerbs", description = "Ähnlich wie Aufseher Maltorius bin auch ich ein reicher Zwerg. Wie dem auch sei, ich habe meine Reichtümer durch harte Arbeit und weise Entscheidungen verdient, nicht durch Sklaverei.\n\nOkay, gut, durch ein wenig Sklaverei. Kaum der Rede wert.\n\nJedenfalls, das erste, was ich in diesen Höhlen sehe, sind Sklavenhändler und Zuchtmeister. Das kann ich nicht tolerieren! Während Ihr Euch durch die Höhle bewegt, solltet Ihr so viele, wie Ihr könnt, töten. Erstattet Evonice Rußraucher, die sich tiefer in der Schlackengrube befindet, Bericht über Eure Resultate.", sourceObjective = "Tötet 10 Zuchtmeister der Dunkeleisenzwerge oder Sklavenhändler der Dunkeleisenzwerge.", completion = "Das habt Ihr gut gemacht. Ich mag Sklaverei auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28055] = { id = 28055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße, furchtbare Freiheit", description = "Natürlich wollen wir so lange wir hier sind so viele Sklaven wie möglich befreien. Die meisten von ihnen werden sich uns wahrscheinlich anschließen, begierig, ihre ehemaligen Geiselnehmer zu bekämpfen.\n\nAllerdings werdet Ihr manchmal auch auf Sklaven treffen, die sich ihrer Befreiung widersetzen. Ein seltsames Phänomen, das oft das \"Durnholdesyndrom\" genannt wird.\n\nWie dem auch sei, Ihr solltet versuchen, sie zu befreien. Wenn sie sich widersetzen, müsst Ihr sie als Feinde behandeln. Erstattet Evonice Rußraucher, die sich tiefer in der Schlackengrube befindet, Bericht über Eure Resultate.", sourceObjective = "Befreit 12 Sklavenarbeiter. Wenn sie sich widersetzen: Tötet sie.", completion = "Es ist merkwürdig, dass so viele Sklaven nicht mit der Freiheit zurechtkommen. Eine Schande, dass wir das tun müssen, aber so ist das nun mal im Krieg.\n\nWidmen wir uns wieder dringenderen Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28056] = { id = 28056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Obsidion", description = "Aufseher Maltorius hat hier das Sagen, aber er ist nicht der einzige Zwerg mit Macht innerhalb der Schlackengrube. Lathoric der Schwarze und sein fürchterlicher Golem, Obsidion, lauern gerade diesen Korridor runter.\n\nWenn Ihr Euch an Lathorics Altar zu schaffen macht, sollten sie beide beschworen werden. Findet ihn, beschwört Lathoric und tötet ihn. Meldet Euch bei Evonice Rußraucher, wenn Ihr fertig seid.", sourceObjective = "Benutzt den Altar von Suntara und tötet dann Lathoric den Schwarzen und Obsidion.", completion = "Eine glorreiche Schlacht, {name}! Ich merke schon, wie sich das Blatt wendet.\n\nNun dann. Wenn Ihr bereit seid, lasst uns diesen Dunkeleisenzwergen ordentlich einheizen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28057] = { id = 28057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie durch Schlafentzug", description = "Es ist eine wenig bekannte Tatsache, dass Zwerge, und insbesondere diejenigen, die dem Dunkeleisenklan angehören, Schlaf brauchen! Viel Schlaf!\n\nJetzt frage ich Euch: Wie können sie ohne Kissen schlafen? Ganz genau, {name}... gar nicht! Und genau darum müsst Ihr ihre Kissen stehlen.\n\nSobald Ihr den Kissendiebstahl vollendet habt, solltet Ihr mit Zuchtmeister Skrange sprechen. Er befindet sich etwas tiefer in der Höhle und arbeitet mit Hansel an einem geheimen Projekt.", sourceObjective = "Beschafft Euch 16 Dunkeleisenkissen.", progress = "Was? Kissen?\n\nHä?", completion = "Wie ich sehe, spielt Evonice wieder ihre alten Spielchen. Ich, ähm, behalte diese Kissen erstmal für eine Weile.\n\nHauptsache, Ihr seid hier. Wir werden Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28058] = { id = 28058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie groß das ist!", description = "So, so, so... Na, wenn das keine Überraschung ist. Das Zimmermädchen hatte ein riesiges Zierkissen und jetzt gehört es Euch. Evonice Rußraucher wird das gute Stück mit Sicherheit gern in ihre schmuddeligen Grabbelfinger bekommen. Sprecht mit ihr und seht, ob sie Euch für Eure Mühen etwas Nettes anbietet.", sourceObjective = "Bringt das Kissen von Zimmermädchen Kissenquetscher zu Evonice Rußraucher in der Sengenden Schlucht.", progress = "Na, das ist mal ein riesiges Kissen! Wo habt Ihr das her?", completion = "Das ist besser, als ich es mir je vorstellen konnte! Das magische Kissen des Zimmermädchens gehört mir! Und ob Ihr eine schöne Belohnung für diese Errungenschaft bekommt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28059] = { id = 28059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einnahme der Festung", description = "Habt Ihr die Festung auf der Nordseite der Insel gesehen, {name}? Von dort aus überwacht Festungslord Farson seine Operationen.\n\nFarson verfügt über eine kleine Gruppe loyaler Anhänger, die uns seit unserer Ankunft Ärger machen. Wir haben ein paar unserer Leute heimlich in die Burg geschickt und sie konnten uns seinen genauen Aufenthaltsort dort melden.\n\nWürdet Ihr ihn für uns erledigen?", sourceObjective = "Man hat Euch gebeten, Festungslord Farson in der Farsonfestung zu töten. Die Farsonfestung werdet Ihr auf der Nordseite der Insel finden.", completion = "Ihr habt ihn getötet? Das haben wir wochenlang vergeblich versucht! Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28060] = { id = 28060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtige Zwielichtbande", description = "Hansel und ich sind hier auf geheimer Mission: um Aufseher Maltorius zu töten. Während unser Hauptziel unverändert bleibt - Erzherzog Calcinder zu vernichten - wird es nicht schaden, den berüchtigten Aufseher der Schlackengrube auszuschalten, wenn wir schon mal da sind.\n\nDas einzige Problem ist, dass Hansel nur darauf vorbereitet war, es mit einem Zwerg aufzunehmen, doch es scheint, als hätte Maltorius einen Besucher... einen Gesandten des Schattenhammers!\n\nSprecht mit Hansel und helft ihm aus. Dann begebt Euch weiter den Korridor hinunter und entlang des Balkons draußen, um Aufseher Schlickfaust anzutreffen.", sourceObjective = "Sprecht mit Hansel Bleihand und helft ihm, Aufseher Maltorius und Zwielichtfürst Arkkus zu bekämpfen.", completion = "Der Schattenhammer, wie? Das hätte ich mir denken können. Ich bin froh, dass Ihr rechtzeitig zu ihrer Hilfe gekommen seid.\n\nEs sieht so aus, als hätten wir entgegen aller Aussichten unseren Vorstoß bis vor Calcinders Haustür getrieben. Jetzt ist es an der Zeit, die Sache zuende zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28061] = { id = 28061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calcinders Handlanger", description = "Man kann auch zu tief graben, {name}. Man findet die reichhaltigsten Mineralienadern zwar tief unter der Oberfläche, aber auch die bösartigsten Kreaturen.\n\nWie zum Beispiel Feuerelementare.\n\nCalcinders Günstlinge durchstreifen die Höhle vor uns. Jeder von ihnen trägt ein Stück von Calcinders Übel in sich. Vernichtet so viele von ihnen, wie Ihr könnt und zeigt keine Reue.", sourceObjective = "Tötet 6 sengende Flammengespenster.", sourceObjectiveStatus = "unverified-source-field" }
quests[28062] = { id = 28062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woher er kam", description = "Erzherzog Calcinder windet sich im hinteren Teil genau dieser Höhle. Wir sind kurz davor, ihn zu töten... allerdings werden wir das nicht tun.\n\nCalcinder hier zu töten hat keinerlei Bedeutung. Seine Akolythen können ihn leicht wiederbeleben. Stattdessen werden wir ihn verbannen.\n\nIch habe Euch zuvor gebeten, einen wertvollen Stein vom Schattenhammer zu erlangen. Diesen werden wir nun gegen Calcinder einsetzen. Verwickelt ihn in einen Kampf, schwächt ihn und setzt dann dieses Gerät gegen ihn ein. Er wird aus diesem Reich verbannt werden.\n\nViel Glück, {name}.", sourceObjective = "Schwächt Erzherzog Calcinder und setzt dann den Geweihten Tripetrizin ein, um ihn zu verbannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28063] = { id = 28063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keine Waffen zurück", description = "Nachschub für den Kampf ist auf diesem Felsen beinahe unmöglich zu bekommen. Jedes Mal, wenn wir die Horde abwehren, kommt es uns vor, als ob wir mit Stöcken und Steinen kämpfen.\n\nWir haben Berichte erhalten, dass Festungslord Farson auf der Nordseite der Insel große Vorräte an Gewehren hat, die wir gebrauchen könnten. Könnt Ihr Euch dorthin begeben und das überprüfen?\n\nSeid vorsichtig, {name}, die Anhänger Farsons werden alles tun, um ihn zu beschützen.", sourceObjective = "Besorgt 12 rostige Gewehre aus Burg Farson auf der Nordseite der Halbinsel von Tol Barad.", progress = "Habt Ihr mit den Gewehren Glück gehabt?", completion = "Danke, dass Ihr die für uns eingesammelt habt, {name}. Ist schwierig, ohne Gewehre eine Schlacht zu schlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28064] = { id = 28064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Bruderschaft", description = "Ihr solltet zur Thoriumsspitze zurückkehren. Aufseher Schlickfaust und die Thoriumbruderschaft werden sich fragen, wie Ihr im Kampf gegen Calcinder abgeschnitten habt.", sourceObjective = "Erstattet Aufseher Schlickfaust auf der Thoriumsspitze in der Sengenden Schlucht Bericht.", completion = "Unsere Aufgabe hier ist vollbracht und es ist allein Euch zu verdanken, {name}. Bitte wählt Euch aus unserem Besitz aus, wonach Euch der Sinn steht. Darüberhinaus möchte ich Euch zu einem vollwertigen Mitglied unseres Ordens machen. Willkommen in der Thoriumbruderschaft, {name}. Euch Bruder nennen zu können erfüllt mich mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[28066] = { id = 28066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Versunkene Tempel", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Versunkenen Tempel unweit von Steinard zu reisen!\n\nDie Trolle des Stammes der Atal'ai versuchen dort, Hakkar den Seelenschinder zu beschwören! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Versunkenen Tempel und sprecht mit dem grünen Drachen Lord Itharius, der bereit ist, diesen gefährlichen Trollen ein Ende zu machen.", sourceObjective = "Sprecht mit Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28067] = { id = 28067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Versunkene Tempel", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Versunkenen Tempel unweit der Marschtidenwacht zu reisen!\n\nDie Trolle des Stammes der Atal'ai versuchen dort, Hakkar, den Seelenschinder, herbeizubeschwören! Wenn Ihr Euch für diesen Weg entscheidet, so begebt Euch zum Versunkenen Tempel und sprecht mit dem grünen Drachen Lord Itharius, der bereit ist, diesen gefährlichen Trollen ein Ende zu machen.", sourceObjective = "Sprecht mit Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28068] = { id = 28068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelstiefen", description = "König Varian Wrynn fordert alle diensttauglichen Abenteurer auf, umgehend in die Schwarzfelstiefen nordwestlich von Morgans Wacht zu reisen!\n\nDie Dunkeleisenzwerge stellen für die Rotkammbewohner eine ernst zu nehmende Bedrohung dar! Falls Ihr interessiert seid, begebt Euch in die Schwarzfelstiefen und sprecht mit Morgan, die nach langer Abwesenheit wieder unter uns ist und ihre Rache an den Dunkeleisenzwergen verüben möchte.", sourceObjective = "Sprecht mit Morgan.", completion = "Ihr seht so aus, als könntet Ihr es kaum erwarten, ein paar hundert Dunkeleisenzwerge im Namen der Gerechtigkeit zu töten.\n\nPerfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28069] = { id = 28069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelstiefen", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in die Schwarzfelstiefen westlich vom Flammenkamm zu reisen!\n\nDie Dunkeleisenzwerge haben bereits das von der Allianz gehaltene Rotkammgebirge angegriffen und wenn sie nicht kontrolliert werden, könnten sie schon bald eine Gefahr für unsere wenigen Hordestellungen im südlichen Azeroth darstellen.\n\nFalls Ihr interessiert seid, begebt Euch in die Schwarzfelstiefen und sprecht mit Oberhenker Nuzrak, der die Expeditionskorps von Kargath reformiert, um den Dunkeleisenzwergen ein für alle Mal ein Ende zu bereiten.", sourceObjective = "Sprecht mit Oberhenker Nuzrak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28070] = { id = 28070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelsspitze", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zur Schwarzfelsspitze westlich vom Flammenkamm zu reisen!\n\nNefarians Armeen und die Anhänger Rend Schwarzfausts bedrohen die Existenz der Horde! Falls Ihr interessiert seid, begebt Euch zur Schwarzfelsspitze und sprecht mit Acride, unserem einzigen Kontakt vor Ort, der die Invasion aufhalten könnte.", sourceObjective = "Sprecht mit Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28071] = { id = 28071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Schwarzfelsspitze", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zur Schwarzfelsspitze nordwestlich von Morgans Wacht zu reisen!\n\nNefarians Armeen und die Anhänger Rend Schwarzfausts bedrohen sein Königreich! Falls Ihr interessiert seid, begebt Euch zur Schwarzfelsspitze und sprecht mit Acride, unserem einzigen Kontakt vor Ort, der die Invasion aufhalten könnte.", sourceObjective = "Sprecht mit Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28072] = { id = 28072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Wucherborkenviertel", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Wucherborkenviertel in Düsterbruch östlich der Mondfederfeste zu reisen!\n\nAlzzin der Wildformer hat Verderbnis in die Gegend gebracht und könnte ganz Düsterbruch einnehmen! Falls Ihr interessiert seid, begebt Euch zum Wucherborkenviertel und sprecht mit Furgus Wucherborke, dem einzigen nicht verderbten Wesen, das in der Gegend noch am Leben ist.", sourceObjective = "Sprecht mit Furgus Wucherborke.", sourceObjectiveStatus = "unverified-source-field" }
quests[28073] = { id = 28073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Wucherborkenviertel", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Wucherborkenviertel in Düsterbruch westlich von Camp Mojache zu reisen!\n\nAlzzin der Wildformer hat Verderbnis in die Gegend gebracht und könnte ganz Düsterbruch einnehmen! Falls Ihr interessiert seid, begebt Euch zum Wucherborkenviertel und sprecht mit Furgus Wucherborke, dem einzigen nicht verderbten Wesen, das in der Gegend noch am Leben ist.", sourceObjective = "Sprecht mit Furgus Wucherborke.", sourceObjectiveStatus = "unverified-source-field" }
quests[28074] = { id = 28074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Hauptstadtgärten", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in die Hauptstadtgärten in Düsterbruch westlich von Camp Mojache zu reisen!\n\nDer gefallene Hochgeborene Prinz Tortheldrin benutzt den riesigen Dämon Immol'thar, um die Gärten unter Kontrolle zu halten! Falls Ihr interessiert seid, begebt Euch in die Hauptstadtgärten und sprecht mit Estulan, einem reinen Hochgeborenen, der erst vor Kurzem aus der Vergessenheit erschienen ist und nun versucht, die gefallene Stadt für sein Volk zurückzuerobern.", sourceObjective = "Sprecht mit Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28075] = { id = 28075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Düsterbruch - Hauptstadtgärten", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich in die Hauptstadtgärten in Düsterbruch östlich der Mondfederfeste zu reisen!\n\nDer gefallene Hochgeborene Prinz Tortheldrin benutzt den riesigen Dämon Immol'thar, um die Gärten unter Kontrolle zu halten! Falls Ihr interessiert seid, begebt Euch in die Hauptstadtgärten und sprecht mit Estulan, einem reinen Hochgeborenen, der erst vor Kurzem aus der Vergessenheit erschienen ist und nun versucht, die gefallene Stadt für sein Volk zurückzuerobern.", sourceObjective = "Sprecht mit Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28076] = { id = 28076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Norden Düsterbruchs", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Druiden der Kralle, der bereits zur Erkundung vorgeschickt wurde.", sourceObjective = "Sprecht mit dem Druiden der Kralle.", sourceObjectiveStatus = "unverified-source-field" }
quests[28077] = { id = 28077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Der Norden Düsterbruchs", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Oger der Steinbrecher, der bereits zur Erkundung vorgeschickt wurde.", sourceObjective = "Sprecht mit dem Oger der Steinbrecher.", sourceObjectiveStatus = "unverified-source-field" }
